// app/(tabs)/feed.tsx
// Tela de Comunidade/Feed - NOVAIX FITNESS

import { useState, useEffect, useMemo, useCallback, Suspense, lazy } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated, Modal, FlatList, ActivityIndicator, useWindowDimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../src/constants/colors'
import { useTheme } from '../../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS } from '../../src/constants/spacing';
import { SHADOWS } from '../../src/constants/shadows';
import { PostCard, NotificationModal, ChallengesList, TutorialOverlay, ErrorBoundary, PostSkeleton, FeedEmptyState, FeedHeader, FeedFilters, StoryRing, StoryCreateModal, Loading, ReelItem, AnimatedRefresh, WorkoutStories, DailyCheckIn } from '../../src/components';
import { ComposerCard } from '../../src/components/feed/ComposerCard';
import { ReelsBar } from '../../src/components/feed/ReelsBar';
import { DuelsSection } from '../../src/components/feed/DuelsSection';
import { useTutorial } from '../../src/hooks/useTutorial';
import { useFeedData } from '../../src/hooks/useFeedData';
import { performCheckIn, getTodayCheckIn, getCheckInStreak } from '../../src/services/checkIn';
import { getActiveStories } from '../../src/services/stories';
import { useAuth } from '../../src/context/AuthContext';
import { useSecurity } from '../../src/hooks/useSecurity';
import { layout } from '../../src/styles';
import { useResponsive } from '../../src/hooks/useResponsive';
import { useReelsFeed } from '../../src/hooks/useReelsFeed';

// Lazy-loaded heavy components (only shown conditionally)
const LazyCreatePostModal = lazy(() => import('../../src/components/social/CreatePostModal'));
const LazyStoryViewer = lazy(() => import('../../src/components/social/StoryViewer'));
const LazyChallengeFriend = lazy(() => import('../../src/components/social/ChallengeFriend'));

const POST_ITEM_HEIGHT = 420;

// Loading fallback for lazy components
function LazyFallback() {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  return <ActivityIndicator size="small" color={colors.primary} />;
}

const makeStyles = (colors: any) => StyleSheet.create({
  fab: { position: 'absolute', backgroundColor: colors.primary, ...SHADOWS.lg },
  fabInner: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  loadingContainer: { gap: SPACING.md },
  loadingMore: { paddingVertical: SPACING.xl, alignItems: 'center' },
  postWrapper: { marginBottom: SPACING.md },
  endOfFeed: { alignItems: 'center', paddingVertical: SPACING.xl, gap: SPACING.sm },
  endOfFeedText: { fontFamily: 'Inter_500Medium', fontSize: 13, color: colors.textMuted },
  reelsModalContainer: { flex: 1, backgroundColor: 'black', position: 'relative' },
});

export default function FeedScreen() {
  const { height: SCREEN_HEIGHT } = useWindowDimensions();
  const { user, profile } = useAuth();
  const { fabSize, fabBottom, fabRight, isSmall } = useResponsive();
  const { visible: tutorialVisible, steps: tutorialSteps, handleComplete, handleSkip } = useTutorial('feed', true);
  const filters = ['Todos', 'Populares', 'Recentes', 'Meus Posts'];
  const {
    loading, loadingMore, refreshing, onRefresh, loadMore, hasMore,
    selectedFilter, setSelectedFilter, showCreatePost, setShowCreatePost,
    hasNotif, setHasNotif, showNotifications, setShowNotifications,
    filteredPosts, showEmpty, handleLike, handleNewPost, handleComment,
  } = useFeedData();

  const [showCheckIn, setShowCheckIn] = useState(false);
  const [checkInStreak, setCheckInStreak] = useState(1);
  const [stories, setStories] = useState<any[]>([]);
  const [showStoryViewer, setShowStoryViewer] = useState(false);
  const [selectedStoryIndex, setSelectedStoryIndex] = useState(0);
  const [showStoryCreate, setShowStoryCreate] = useState(false);
  const [workoutStories, setWorkoutStories] = useState<any[]>([]);
  const [activeReelIndex, setActiveReelIndex] = useState<number | null>(null);
  const [showReelsModal, setShowReelsModal] = useState(false);
  const { checkAndPerform, ACTIONS } = useSecurity();
  const { reels: feedReels } = useReelsFeed();
  const fabAnim = useMemo(() => new Animated.Value(0), []);

  useEffect(() => {
    Animated.spring(fabAnim, { toValue: 1, friction: 5, delay: 500, useNativeDriver: true }).start();
  }, []);

  useEffect(() => {
    if (!user?.id) return;
    checkDailyCheckIn();
    loadStories();
  }, [user?.id]);

  const checkDailyCheckIn = async () => {
    if (!user?.id || (global as any).hasShownCheckInThisSession) return;
    const existing = await getTodayCheckIn(user.id);
    if (!existing) {
      const streak = await getCheckInStreak(user.id);
      setCheckInStreak(streak + 1);
      setShowCheckIn(true);
      (global as any).hasShownCheckInThisSession = true;
    }
  };

  const loadStories = async () => {
    const data = await getActiveStories(user?.id) as any[];
    const grouped: Record<string, any[]> = {};
    data.forEach((s: any) => {
      if (!grouped[s.user_id]) grouped[s.user_id] = [];
      grouped[s.user_id].push(s);
    });
    setStories(Object.entries(grouped).map(([userId, userStories]) => ({
      userId, name: userStories[0]?.profiles?.name || 'User',
      avatar: userStories[0]?.profiles?.avatar_url || null,
      stories: userStories, seen: false,
    })));
  };

  const loadWorkoutStories = async () => {
    setWorkoutStories([
      { id: '1', userId: 'user1', userName: 'Ana Silva', userAvatar: 'https://i.pravatar.cc/150?img=1', workoutName: 'Treino de Peito', workoutThumbnail: 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=200', duration: 45, exercises: 8, seen: false },
      { id: '2', userId: 'user2', userName: 'Carlos Santos', userAvatar: 'https://i.pravatar.cc/150?img=3', workoutName: 'HIIT Cardio', workoutThumbnail: 'https://images.unsplash.com/photo-1534258936925-c58bed479fcb?w=200', duration: 30, exercises: 12, seen: false },
      { id: '3', userId: 'user3', userName: 'Maria Costa', userAvatar: 'https://i.pravatar.cc/150?img=5', workoutName: 'Yoga Flow', workoutThumbnail: 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=200', duration: 60, exercises: 15, seen: true },
    ]);
  };

  useEffect(() => { loadWorkoutStories(); }, []);

  const handleCheckInClaim = async () => {
    if (!user?.id) return;
    await checkAndPerform(ACTIONS.CHECK_IN, 'check_in', async () => {
      await performCheckIn(user!.id);
    }, 'Erro ao fazer check-in');
  };

  const handleViewStory = useCallback((storyGroup: any) => {
    const idx = stories.findIndex(s => s.userId === storyGroup.userId);
    setSelectedStoryIndex(idx >= 0 ? idx : 0);
    setShowStoryViewer(true);
  }, [stories]);

  const handleViewWorkoutStory = useCallback((_story: any, _index: number) => {}, []);

  const handleAddWorkoutStory = useCallback(() => setShowStoryCreate(true), []);
  const handleNotifPress = useCallback(() => { setHasNotif(false); setShowNotifications(true); }, []);
  const handleFabPress = useCallback(() => setShowCreatePost(true), []);
  const handleReelPress = useCallback((i: number) => { setActiveReelIndex(i); setShowReelsModal(true); }, []);
  const onCheckIn = useCallback(() => setShowCheckIn(true), []);
  const onStoryCreateClose = useCallback(() => { setShowStoryCreate(false); loadStories(); }, []);
  const onStoryViewerClose = useCallback(() => setShowStoryViewer(false), []);
  const onNotificationsClose = useCallback(() => setShowNotifications(false), []);
  const onCreatePostClose = useCallback(() => setShowCreatePost(false), []);
  const onDailyCheckInClose = useCallback(() => setShowCheckIn(false), []);
  const onReelsClose = useCallback(() => { setShowReelsModal(false); setActiveReelIndex(null); }, []);
  const keyExtractor = useCallback((item: any) => item.id, []);
  const getItemLayout = useCallback((_data: any, index: number) => ({
    length: POST_ITEM_HEIGHT, offset: POST_ITEM_HEIGHT * index, index,
  }), []);
  const renderItem = useCallback(({ item, index }: { item: any; index: number }) => (
    <View style={[styles.postWrapper, { opacity: Math.min(1, 0.5 + index * 0.1) }]}>
      <PostCard post={item} onLike={handleLike} onComment={handleComment} currentUserId={user?.id} />
    </View>
  ), [handleLike, handleComment, user?.id]);
  const onScroll = useCallback((e: any) => {
    const { layoutMeasurement, contentOffset, contentSize } = e.nativeEvent;
    if (layoutMeasurement.height + contentOffset.y >= contentSize.height - 200) loadMore();
  }, [loadMore]);
  const reelsKeyExtractor = useCallback((item: any) => item.id, []);
  const reelsGetItemLayout = useCallback((_data: any, index: number) => ({
    length: SCREEN_HEIGHT, offset: SCREEN_HEIGHT * index, index,
  }), []);
  const onReelsMomentumScrollEnd = useCallback((e: any) => {
    setActiveReelIndex(Math.round(e.nativeEvent.contentOffset.y / SCREEN_HEIGHT));
  }, []);
  const reelsRenderItem = useCallback(({ item, index }: { item: any; index: number }) => (
    <ReelItem item={item} isPlaying={index === activeReelIndex} onClose={onReelsClose} screenHeight={SCREEN_HEIGHT} />
  ), [activeReelIndex, onReelsClose]);

  const listHeader = useMemo(() => (
    <>
      <FeedHeader hasNotif={hasNotif} onNotificationsPress={handleNotifPress} />
      <FeedFilters filters={filters} selected={selectedFilter} onSelect={setSelectedFilter} />
      <ComposerCard userName={user?.name} onPhoto={handleFabPress} onVideo={handleFabPress} onCheckIn={onCheckIn} />
      <StoryRing currentUserId={user?.id || ''} currentUserAvatar={profile?.avatar_url} currentUserName={profile?.name} onViewStory={handleViewStory} onAddStory={handleAddWorkoutStory} />
      <WorkoutStories stories={workoutStories} currentUserId={user?.id || ''} onViewStory={handleViewWorkoutStory} onAddStory={handleAddWorkoutStory} />
      <ReelsBar reels={feedReels} onPressReel={handleReelPress} />
      <DuelsSection />
      <ChallengesList userId={user?.id} />
    </>
    ), [hasNotif, handleNotifPress, selectedFilter, user?.name, user?.id, profile, handleViewStory, handleAddWorkoutStory, handleViewWorkoutStory, handleReelPress, handleFabPress, onCheckIn, workoutStories, feedReels]);

  const listEmpty = useMemo(() => {
    if (loading) return <View style={styles.loadingContainer}><PostSkeleton /><PostSkeleton /><PostSkeleton /></View>;
    if (showEmpty) return <FeedEmptyState hasFilter={selectedFilter !== 'Todos'} />;
    return null;
  }, [loading, showEmpty, selectedFilter]);

  const listFooter = useMemo(() => (<>
      {loadingMore && <View style={styles.loadingMore}><Loading variant="dots" /></View>}
      {!hasMore && filteredPosts.length > 0 && (
        <View style={styles.endOfFeed}>
          <Ionicons name="checkmark-circle" size={24} color={colors.primary} />
          <Text style={styles.endOfFeedText}>Você viu todos os posts</Text>
        </View>
      )}
      <View style={{ height: 100 }} />
    </>
  ), [loadingMore, hasMore, filteredPosts.length]);

  return (
    <ErrorBoundary screenName="Feed">
    <View style={layout.screen}>
      <TutorialOverlay visible={tutorialVisible} steps={tutorialSteps} onComplete={handleComplete} onSkip={handleSkip} onRestart={handleSkip} />
      <FlatList data={filteredPosts} renderItem={renderItem} keyExtractor={keyExtractor}
        getItemLayout={getItemLayout} ListHeaderComponent={listHeader} ListEmptyComponent={listEmpty}
        ListFooterComponent={listFooter} contentContainerStyle={layout.scroll}
        refreshControl={<AnimatedRefresh refreshing={refreshing} onRefresh={onRefresh} />}
        showsVerticalScrollIndicator={false} onScroll={onScroll} scrollEventThrottle={400}
        removeClippedSubviews initialNumToRender={10} maxToRenderPerBatch={10} windowSize={5} />
      <Animated.View style={[styles.fab, { width: fabSize, height: fabSize, borderRadius: fabSize / 2, bottom: fabBottom, right: fabRight, transform: [{ scale: fabAnim }] }]}>
        <TouchableOpacity style={styles.fabInner} onPress={handleFabPress} activeOpacity={0.8}>
          <Ionicons name="add" size={isSmall ? 24 : 28} color={colors.background} />
        </TouchableOpacity>
      </Animated.View>
      <Suspense fallback={<LazyFallback />}>
        <LazyCreatePostModal visible={showCreatePost} onClose={onCreatePostClose} onSubmit={handleNewPost} userId={user?.id} />
      </Suspense>
      <NotificationModal visible={showNotifications} onClose={onNotificationsClose} />
      <DailyCheckIn visible={showCheckIn} streakDay={checkInStreak} xpEarned={0} onClose={onDailyCheckInClose} onClaim={handleCheckInClaim} />
      <Suspense fallback={<LazyFallback />}>
        <LazyStoryViewer visible={showStoryViewer} stories={stories} initialIndex={selectedStoryIndex} onClose={onStoryViewerClose} />
      </Suspense>
      <StoryCreateModal visible={showStoryCreate} onClose={onStoryCreateClose} userId={user?.id} />

      {showReelsModal && activeReelIndex !== null && (
        <Modal visible={showReelsModal} animationType="slide" transparent>
          <View style={styles.reelsModalContainer}>
            <FlatList
              data={feedReels} keyExtractor={reelsKeyExtractor}
              initialScrollIndex={activeReelIndex}
              getItemLayout={reelsGetItemLayout}
              pagingEnabled showsVerticalScrollIndicator={false}
              onMomentumScrollEnd={onReelsMomentumScrollEnd}
              renderItem={reelsRenderItem}
            />
          </View>
        </Modal>
      )}
    </View>
    </ErrorBoundary>
  );
}

