// app/gamification.tsx
// Gamification com rankings animados e melhorias visuais - NOVAIX FITNESS

import React, { useEffect, useRef } from 'react';
import { View, Text, ScrollView, RefreshControl, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../src/constants/colors'
import { useTheme } from '../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS } from '../src/constants/spacing';
import { SHADOWS } from '../src/constants/shadows';
import { ACHIEVEMENTS } from '../src/constants/gamification';
import { Header, ErrorBoundary, LevelCard, AchievementGrid, GamificationChallenges, XpBreakdown, RankingCard, Loading, EmptyState, LiveLeaderboard } from '../src/components';
import { useGamification } from '../src/hooks/useGamification';
import { useAuth } from '../src/context/AuthContext';

import { useResponsive } from '../src/hooks/useResponsive';

function StatsSummary({ data }) {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  const stats = [
    { key: 'totalXP', label: 'XP total', icon: 'flash', color: colors.primary },
    { key: 'achievements', label: 'Conquistas', icon: 'trophy', color: colors.attention },
    { key: 'streak', label: 'Sequência', icon: 'flame', color: colors.secondary },
    { key: 'totalWorkouts', label: 'Treinos', icon: 'barbell', color: colors.success },
  ];
  const values = {
    totalXP: `${data?.totalXP || 0}`,
    achievements: `${(data?.achievements || []).length}/${ACHIEVEMENTS.length}`,
    streak: `${data?.streak || 0} dias`,
    totalWorkouts: `${data?.totalWorkouts || 0}`,
  };
  return (
    <View style={styles.statsGrid}>
      {stats.map((s) => (
        <View key={s.key} style={[styles.statCard, { borderLeftColor: s.color, borderLeftWidth: 3 }]}>
          <Ionicons name={s.icon} size={18} color={s.color} />
          <Text style={styles.statValue}>{values[s.key]}</Text>
          <Text style={styles.statLabel}>{s.label}</Text>
        </View>
      ))}
    </View>
  );
}

function GamificationContent() {
  const { user } = useAuth();
  const {
    data, loading, refreshing, error,
    onRefresh, unlockedIds, xpBreakdown,
  } = useGamification();

  // Live Leaderboard state
  const [leaderboardEntries, setLeaderboardEntries] = useState([
    { id: '1', userId: 'user1', userName: 'Ana Silva', userAvatar: 'https://i.pravatar.cc/150?img=1', xp: 2450, workouts: 28, rank: 1, previousRank: 2 },
    { id: '2', userId: 'user2', userName: 'Carlos Santos', userAvatar: 'https://i.pravatar.cc/150?img=3', xp: 2180, workouts: 24, rank: 2, previousRank: 1 },
    { id: '3', userId: 'user3', userName: 'Maria Costa', userAvatar: 'https://i.pravatar.cc/150?img=5', xp: 1920, workouts: 22, rank: 3, previousRank: 3 },
    { id: '4', userId: 'user4', userName: 'Pedro Lima', userAvatar: 'https://i.pravatar.cc/150?img=7', xp: 1650, workouts: 19, rank: 4, previousRank: 5 },
    { id: '5', userId: 'user5', userName: 'Julia Ferreira', userAvatar: 'https://i.pravatar.cc/150?img=9', xp: 1420, workouts: 17, rank: 5, previousRank: 4 },
  ]);
  const [leaderboardFilter, setLeaderboardFilter] = useState<'friends' | 'all' | 'global'>('all');

  // Animacoes
  const fadeAnim = useMemo(() => new Animated.Value(0), []);
  const slideAnim = useMemo(() => new Animated.Value(20), []);

  useEffect(() => {
    if (!loading) {
      Animated.parallel([
        Animated.timing(fadeAnim, { toValue: 1, duration: 500, useNativeDriver: true }),
        Animated.spring(slideAnim, { toValue: 0, friction: 8, tension: 55, useNativeDriver: true }),
      ]).start();
    }
  }, [loading]);

  const handleRefreshLeaderboard = async () => {
    // In production, this would fetch fresh data from Supabase
    // For now, we'll simulate with mock data
    await new Promise(resolve => setTimeout(resolve, 1000));
  };

  const handleLeaderboardFilterChange = (filter: 'friends' | 'all' | 'global') => {
    setLeaderboardFilter(filter);
    // In production, this would filter the leaderboard data
  };

  if (loading) {
    return (
      <View style={styles.center}>
        <Loading variant="pulse" />
        <Text style={styles.loadingText}>{'Carregando conquistas...'}</Text>
      </View>
    );
  }

  if (error) {
    return (
      <View style={styles.center}>
        <Ionicons name="alert-circle-outline" size={48} color={colors.error} />
        <Text style={styles.loadingText}>{error}</Text>
      </View>
    );
  }

  return (
    <ScrollView
      style={styles.screen}
      contentContainerStyle={styles.content}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.primary} colors={[colors.primary]} />}
      showsVerticalScrollIndicator={false}
    >
      <Header title={'CONQUISTAS E NÍVEIS'} showBack />

      <Animated.View style={{ opacity: fadeAnim, transform: [{ translateY: slideAnim }] }}>
        <StatsSummary data={data} />
      </Animated.View>

      <View style={styles.section}>
        <LevelCard xp={data?.totalXP || 0} />
      </View>

      <View style={styles.section}>
        <XpBreakdown breakdown={xpBreakdown} />
      </View>

      <View style={styles.section}>
        <AchievementGrid unlockedIds={unlockedIds} />
      </View>

      <View style={styles.section}>
        <RankingCard userId={user?.id} />
      </View>

      <View style={styles.section}>
        <LiveLeaderboard
          entries={leaderboardEntries}
          currentUserId={user?.id || ''}
          onRefresh={handleRefreshLeaderboard}
          filter={leaderboardFilter}
          onFilterChange={handleLeaderboardFilterChange}
        />
      </View>

      <View style={styles.section}>
        <GamificationChallenges progress={{ workouts: data?.totalWorkouts || 0, minutes: data?.totalMinutes || 0, posts: data?.social_first_post_count || 0, streak: data?.maxStreak || 0 }} />
      </View>

      <View style={styles.bottomSpacer} />
    </ScrollView>
  );
}

const makeStyles = (colors: any) => StyleSheet.create({
  screen: { flex: 1, backgroundColor: colors.background },
  content: { paddingBottom: SPACING.massive },
  center: { flex: 1, backgroundColor: colors.background, justifyContent: 'center', alignItems: 'center', gap: SPACING.md },
  loadingText: { fontFamily: 'Inter_400Regular', fontSize: 14, color: colors.textMuted },
  section: { marginBottom: SPACING.lg, paddingHorizontal: SPACING.lg },
  statsGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.sm, paddingHorizontal: SPACING.lg, marginBottom: SPACING.lg },
  statCard: { width: '47%', backgroundColor: colors.surface, borderRadius: BORDER_RADIUS.md, padding: SPACING.md, alignItems: 'center', gap: 4, borderWidth: 1, borderColor: colors.border, ...SHADOWS.sm },
  statValue: { fontFamily: 'Montserrat_700Bold', fontSize: 16, color: colors.textTitle },
  statLabel: { fontFamily: 'Inter_400Regular', fontSize: 10, color: colors.textMuted, textTransform: 'uppercase', letterSpacing: 0.5 },
  bottomSpacer: { height: SPACING.xxxl },
});

export default function GamificationScreen() {
  return (
    <ErrorBoundary screenName="Gamification">
      <GamificationContent />
    </ErrorBoundary>
  );
}

