// app/language-select.tsx
// Seleção de idioma antes do cadastro

import { useState, useEffect, useMemo } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated, Dimensions } from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { COLORS } from '../src/constants/colors'
import { useTheme } from '../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS } from '../src/constants/spacing';
import { SHADOWS } from '../src/constants/shadows';
import { SUPPORTED_LANGUAGES } from '../src/ml/languages';
import { ErrorBoundary } from '../src/components';

const LANGUAGE_KEY = '@novaix:selected_language';
const { width: SCREEN_WIDTH } = Dimensions.get('window');

const AVAILABLE = SUPPORTED_LANGUAGES.filter(l => l.available);

const makeStyles = (colors: any) => StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.background,
  },
  content: {
    flex: 1,
    justifyContent: 'center',
    paddingHorizontal: SPACING.xl,
  },
  header: {
    alignItems: 'center',
    marginBottom: SPACING.xxl,
  },
  title: {
    fontFamily: 'Montserrat_800ExtraBold',
    fontSize: 24,
    color: colors.textTitle,
    textAlign: 'center',
    marginTop: SPACING.lg,
    letterSpacing: 1,
  },
  subtitle: {
    fontFamily: 'Inter_400Regular',
    fontSize: 14,
    color: colors.textMuted,
    textAlign: 'center',
    marginTop: SPACING.sm,
  },
  options: {
    gap: SPACING.sm,
  },
  option: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: SPACING.md,
    padding: SPACING.lg,
    borderRadius: BORDER_RADIUS.md,
    backgroundColor: colors.surface,
    borderWidth: 2,
    borderColor: colors.border,
  },
  optionActive: {
    borderColor: colors.primary,
    backgroundColor: colors.primary + '10',
    ...SHADOWS.sm,
  },
  flag: {
    fontSize: 32,
  },
  optionInfo: {
    flex: 1,
  },
  optionLabel: {
    fontFamily: 'Montserrat_700Bold',
    fontSize: 16,
    color: colors.textTitle,
  },
  optionLabelActive: {
    color: colors.primary,
  },
  optionNative: {
    fontFamily: 'Inter_400Regular',
    fontSize: 12,
    color: colors.textMuted,
    marginTop: 2,
  },
  checkCircle: {
    width: 24,
    height: 24,
    borderRadius: 12,
    backgroundColor: colors.primary,
    justifyContent: 'center',
    alignItems: 'center',
  },
  info: {
    fontFamily: 'Inter_400Regular',
    fontSize: 12,
    color: colors.textMuted,
    textAlign: 'center',
    marginTop: SPACING.xl,
  },
  bottomSection: {
    paddingHorizontal: SPACING.xl,
    paddingBottom: SPACING.xxl,
  },
  ctaBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: SPACING.sm,
    backgroundColor: colors.primary,
    borderRadius: BORDER_RADIUS.md,
    paddingVertical: SPACING.lg,
    ...SHADOWS.md,
  },
  ctaBtnText: {
    fontFamily: 'Montserrat_700Bold',
    fontSize: 14,
    color: colors.background,
    letterSpacing: 1,
  },
});

export default function LanguageSelectScreen() {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  const router = useRouter();
  const [selected, setSelected] = useState('pt');

  const fadeAnim = useMemo(() => new Animated.Value(0), []);
  const slideAnim = useMemo(() => new Animated.Value(30), []);

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, { toValue: 1, duration: 600, useNativeDriver: true }),
      Animated.spring(slideAnim, { toValue: 0, friction: 8, tension: 55, useNativeDriver: true }),
    ]).start();
  }, []);

  const handleContinue = async () => {
    await AsyncStorage.setItem(LANGUAGE_KEY, selected);
    router.replace('/');
  };

  return (
    <ErrorBoundary screenName="LanguageSelect">
      <View style={styles.container}>
        <Animated.View style={[styles.content, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
          {/* Header */}
          <View style={styles.header}>
            <Ionicons name="globe-outline" size={48} color={colors.primary} />
            <Text style={styles.title}>ESCOLHA SEU IDIOMA</Text>
            <Text style={styles.subtitle}>Selecione o idioma do app</Text>
          </View>

          {/* Language options */}
          <View style={styles.options}>
            {AVAILABLE.map((lang) => {
              const isActive = selected === lang.code;
              return (
                <TouchableOpacity
                  key={lang.code}
                  style={[styles.option, isActive && styles.optionActive]}
                  onPress={() => setSelected(lang.code)}
                  activeOpacity={0.8}
                >
                  <Text style={styles.flag}>{lang.flag}</Text>
                  <View style={styles.optionInfo}>
                    <Text style={[styles.optionLabel, isActive && styles.optionLabelActive]}>
                      {lang.label}
                    </Text>
                    <Text style={styles.optionNative}>{lang.native}</Text>
                  </View>
                  {isActive && (
                    <View style={styles.checkCircle}>
                      <Ionicons name="checkmark" size={16} color={colors.background} />
                    </View>
                  )}
                </TouchableOpacity>
              );
            })}
          </View>

          {/* Info */}
          <Text style={styles.info}>
            Você pode alterar o idioma depois nas configurações.
          </Text>
        </Animated.View>

        {/* CTA Button */}
        <View style={styles.bottomSection}>
          <TouchableOpacity style={styles.ctaBtn} onPress={handleContinue} activeOpacity={0.8}>
            <Text style={styles.ctaBtnText}>CONTINUAR</Text>
            <Ionicons name="arrow-forward" size={18} color={colors.background} />
          </TouchableOpacity>
        </View>
      </View>
    </ErrorBoundary>
  );
}

