// app/onboarding/objetivo.tsx
// Tela 1 - Objetivo Principal com melhorias visuais - NOVAIX FITNESS

import { useState } from 'react';
import { View, Text, StyleSheet, Animated, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { COLORS } from '../../src/constants/colors'
import { shadow } from '../../src/helpers/shadows';
import { useTheme } from '../../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS } from '../../src/constants/spacing';
import { SHADOWS } from '../../src/constants/shadows';
import { Button, ErrorBoundary } from '../../src/components';
import { useAuth } from '../../src/context/AuthContext';
import { useResponsive } from '../../src/hooks/useResponsive';
import OnboardingLayout from '../../src/components/onboarding/OnboardingLayout';
import { useStaggeredEntry } from '../../src/utils/animations';


const makeStyles = (colors: any) => StyleSheet.create({
  cardsContainer: { gap: SPACING.sm, marginBottom: SPACING.xxl },
  goalCard: {
    backgroundColor: colors.surface,
    borderRadius: BORDER_RADIUS.lg,
    borderWidth: 2,
    borderColor: colors.border,
    padding: SPACING.lg,
    flexDirection: 'row',
    alignItems: 'center',
    gap: SPACING.lg,
    ...SHADOWS.sm,
  },
  goalCardActive: {
    borderColor: colors.primary,
    backgroundColor: colors.primary + '06',
    ...SHADOWS.md,
  },
  iconWrap: {
    width: 54,
    height: 54,
    borderRadius: 16,
    justifyContent: 'center',
    alignItems: 'center',
    flexShrink: 0,
  },
  goalInfo: { flex: 1 },
  goalLabel: {
    fontFamily: 'Montserrat_700Bold',
    fontSize: 16,
    color: colors.textTitle,
    marginBottom: 2,
  },
  goalDesc: {
    fontFamily: 'Inter_400Regular',
    fontSize: 12,
    color: colors.textMuted,
    lineHeight: 18,
  },
  radio: {
    width: 22,
    height: 22,
    borderRadius: 11,
    borderWidth: 2,
    borderColor: colors.border,
    justifyContent: 'center',
    alignItems: 'center',
    flexShrink: 0,
  },
  radioActive: {
    borderColor: colors.primary,
    backgroundColor: colors.primary + '15',
  },
  radioDot: {
    width: 10,
    height: 10,
    borderRadius: 5,
    backgroundColor: colors.primary,
  },
  btnWrap: { marginTop: SPACING.md },
});

export default function GoalScreen() {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  const router = useRouter();
  const { saveOnboarding, updateProfile } = useAuth();

  const goals = [
    { id: 'weight_loss', icon: 'flame', color: colors.secondary, emoji: '🔥' },
    { id: 'muscle_gain', icon: 'barbell', color: colors.primary, emoji: '💪' },
    { id: 'fitness', icon: 'heart', color: colors.success, emoji: '❤️' },
    { id: 'flexibility', icon: 'body', color: colors.cyan, emoji: '🧘' },
  ];

  const { isSmall } = useResponsive();
  const [selectedGoal, setSelectedGoal] = useState(null);
  const [anim0, anim1, anim2, anim3, anim4] = [0, 1, 2, 3, 4].map(useStaggeredEntry);

  const handleNext = async () => {
    if (!selectedGoal) return;
    await saveOnboarding({ goal: selectedGoal });
    await updateProfile({ current_step: 'onboarding' });
    router.push('/onboarding/dados-fisicos');
  };

  return (
    <ErrorBoundary screenName="Objetivo">
      <OnboardingLayout
        stepNumber={1}
        totalSteps={3}
        title={'O QUE VOCÊ\nBUSCA HOJE?'}
        subtitle={'Selecione seu objetivo principal'}
        icon="target"
        iconColor={colors.primary}
      >
        <View style={styles.cardsContainer}>
          {goals.map((goal, index) => {
            const anim = [anim0, anim1, anim2, anim3][index];
            const isSelected = selectedGoal === goal.id;
            return (
              <Animated.View
                key={goal.id}
                style={{
                  opacity: anim?.opacity,
                  transform: [{ translateY: anim?.translateY }],
                }}
              >
                <TouchableOpacity
                  style={[
                    styles.goalCard,
                    isSelected && styles.goalCardActive,
                    isSelected && { borderColor: goal.color, ...shadow({ color: goal.color, blur: 10, opacity: 0.2 }) },
                  ]}
                  onPress={() => setSelectedGoal(goal.id)}
                  activeOpacity={0.85}
                >
                  <View style={[styles.iconWrap, { backgroundColor: goal.color + (isSelected ? '25' : '12') }]}>
                    <Ionicons name={goal.icon as any} size={28} color={goal.color} />
                  </View>
                  <View style={styles.goalInfo}>
                    <Text style={[styles.goalLabel, isSelected && { color: colors.primary }]}>
                      {goal.id === 'weight_loss' ? 'Emagrecimento' : goal.id === 'muscle_gain' ? 'Ganho de Massa' : goal.id === 'fitness' ? 'Condicionamento' : 'Flexibilidade'}
                    </Text>
                    <Text style={styles.goalDesc}>
                      {goal.id === 'weight_loss' ? 'Queima de gordura e perda de peso' : goal.id === 'muscle_gain' ? 'Hipertrofia e definição muscular' : goal.id === 'fitness' ? 'Saúde, disposição e qualidade de vida' : 'Mobilidade, yoga e alongamento'}
                    </Text>
                  </View>
                  <View style={[styles.radio, isSelected && styles.radioActive]}>
                    {isSelected && (
                      <Animated.View style={styles.radioDot} />
                    )}
                  </View>
                </TouchableOpacity>
              </Animated.View>
            );
          })}
        </View>

        <View style={styles.btnWrap}>
          <Button
            title={'PRÓXIMO'}
            icon="arrow-forward"
            iconPosition="right"
            onPress={handleNext}
            disabled={!selectedGoal}
            size={isSmall ? 'md' : 'lg'}
            style={{ width: '100%' }}
          />
        </View>
      </OnboardingLayout>
    </ErrorBoundary>
  );
}

