// app/player.tsx
// Tela de Player de Treino com novos componentes - NOVAIX FITNESS

import React, { useCallback, Suspense, lazy } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, Modal, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { COLORS } from '../src/constants/colors'
import { useTheme } from '../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS, ICON_SIZES } from '../src/constants/spacing';
import { EXERCISE, COMPLETION } from '../src/data/workoutTexts';
import {
  WorkoutTimer, ExerciseProgress, WorkoutControls,
  TutorialOverlay, XPFloating, ErrorBoundary, ExerciseVideo,
  ProgressRing, AnimatedCounter, GlassCard, GradientButton, Skeleton
} from '../src/components';
import useWorkoutPlayer from '../src/hooks/useWorkoutPlayer';
import { useResponsive } from '../src/hooks/useResponsive';
import { layout, typography } from '../src/styles';
import { usePlayerStyles } from '../src/styles/playerStyles';

// Lazy-loaded workout components (only shown during active workout)
const LazyRestOverlay = lazy(() => import('../src/components/workout/RestOverlay'));
const LazyRatingModal = lazy(() => import('../src/components/workout/RatingModal'));
const LazyWorkoutShare = lazy(() => import('../src/components/social/WorkoutShare'));
const LazySmartRestTimer = lazy(() => import('../src/components/workout/SmartRestTimer'));

const TimerDisplay = React.memo(({ timeRemaining, totalTime, phase, exerciseName, setInfo, currentSet, totalSets, logs, styles }: {
  timeRemaining: number; totalTime: number; phase: string; exerciseName?: string;
  setInfo: string; currentSet: number; totalSets: number; logs: any[]; styles: any;
}) => (
  <View style={styles.timerSection}>
    <WorkoutTimer timeRemaining={timeRemaining} totalTime={totalTime} phase={phase}
      exerciseName={exerciseName} setInfo={setInfo} currentSet={currentSet}
      totalSets={totalSets} logs={logs} />
  </View>
));

// Loading fallback for lazy components
function LazyFallback() {
  const { colors } = useTheme();
  return <ActivityIndicator size="small" color={colors.primary} />;
}

function LoadingSkeleton({ styles }) {
  return (
    <View style={[layout.screen, styles.centered]}>
      <Skeleton width={120} height={120} borderRadius={60} />
      <View style={{ height: 24 }} />
      <Skeleton width={200} height={24} borderRadius={6} />
      <View style={{ height: 8 }} />
      <Skeleton width={150} height={16} borderRadius={4} />
    </View>
  );
}

export default function PlayerScreen() {
  const styles = usePlayerStyles();
  const router = useRouter();
  const { isSmall, horizontalPadding } = useResponsive();
  const {
    workout, loading, showRating, voiceEnabled, showXP, xpAmount,
    tutorialVisible, tutorialSteps, handleComplete, handleSkip,
    timer, handleRatingSubmit, handleFinish, toggleVoiceCoach, dismissRating, setShowXP,
    showCompletion, setShowCompletion,
  } = useWorkoutPlayer();

  const onBack = useCallback(() => router.back(), [router]);
  const onStartWorkout = useCallback(() => timer.startWorkout(), [timer.startWorkout]);
  const onCompletionClose = useCallback(() => {
    setShowCompletion(false);
    timer.stopWorkout();
    router.back();
  }, [timer, router, setShowCompletion]);

  if (loading) return <LoadingSkeleton styles={styles} />;

  // Tela de selecao (idle)
  if (timer.phase === 'idle') {
    return (
      <View style={layout.screen}>
        <TutorialOverlay visible={tutorialVisible} steps={tutorialSteps} onComplete={handleComplete} onSkip={handleSkip} />
        <ScrollView contentContainerStyle={styles.scroll} showsVerticalScrollIndicator={false}>
          <View style={styles.header}>
            <Text style={[typography.h2, { fontSize: isSmall ? 22 : 28 }]}>{workout?.name || 'Treino'}</Text>
            <TouchableOpacity onPress={toggleVoiceCoach} style={styles.voiceToggle}>
              <Ionicons name={voiceEnabled ? 'volume-high' : 'volume-mute'} size={20} color={voiceEnabled ? colors.primary : colors.textMuted} />
            </TouchableOpacity>
          </View>

          {/* Resumo do treino com ProgressRing */}
          <GlassCard style={styles.summaryCard}>
            <View style={styles.summaryRow}>
              <ProgressRing progress={0} size={64} strokeWidth={6} label="0%" />
              <View style={styles.summaryInfo}>
                <Text style={typography.h3}>{workout?.exercises?.length || 0}</Text>
                <Text style={typography.caption}>{EXERCISE.label}</Text>
                <View style={styles.summaryDivider} />
                <Text style={typography.h3}>{workout?.duration || 30}</Text>
                <Text style={typography.caption}>{COMPLETION.minutesUnit}</Text>
              </View>
            </View>
          </GlassCard>

          {/* Lista de exercicios */}
          <View style={styles.exerciseList}>
            <Text style={typography.label}>EXERCÍCIOS ({workout?.exercises?.length || 0})</Text>
            {(workout?.exercises || []).map((ex, i) => (
              <View key={i} style={styles.exerciseItem}>
                <View style={styles.exerciseNumber}>
                  <Text style={styles.exerciseNum}>{i + 1}</Text>
                </View>
                <View style={styles.exerciseInfo}>
                  <Text style={typography.h5}>{ex.name}</Text>
                  <Text style={typography.caption}>{ex.sets || 4}x{ex.reps || 10} · {ex.rest || 60}s descanso</Text>
                </View>
                <Ionicons name="chevron-forward" size={18} color={colors.textMuted} />
              </View>
            ))}
          </View>
          <View style={styles.bottomSpacer} />
        </ScrollView>
        <View style={layout.footer}>
          <GradientButton
            title="INICIAR TREINO"
            icon="play"
            onPress={onStartWorkout}
            size={isSmall ? 'sm' : 'md'}
          />
        </View>
      </View>
    );
  }

  // Tela do treino ativo
  return (
    <ErrorBoundary screenName="Player">
    <View style={layout.screen}>
      <XPFloating amount={xpAmount} visible={showXP} onComplete={() => setShowXP(false)} />
      {timer.phase === 'resting' && (
        <Suspense fallback={<LazyFallback />}>
          <LazyRestOverlay timeRemaining={timer.timeRemaining} nextExercise={timer.currentExercise} onSkip={timer.skipRest} nextSet={timer.currentSet} nextIndex={timer.currentExerciseIndex} totalExercises={timer.totalExercises} />
        </Suspense>
      )}
      <ScrollView contentContainerStyle={styles.scroll} showsVerticalScrollIndicator={false}>
        <ExerciseProgress exercises={workout.exercises} currentIndex={timer.currentExerciseIndex} currentSet={timer.currentSet} totalSets={timer.totalSets} />

        {timer.currentExercise && (
          <View style={styles.videoSection}>
            <ExerciseVideo
              exerciseName={timer.currentExercise.name}
              videoId={timer.currentExercise.video_id}
              thumbnailUrl={timer.currentExercise.thumbnail_url}
            />
          </View>
        )}

        <TimerDisplay
          timeRemaining={timer.timeRemaining}
          totalTime={timer.totalTime}
          phase={timer.phase}
          exerciseName={timer.currentExercise?.name}
          setInfo={`Série ${timer.currentSet} de ${timer.totalSets}`}
          currentSet={timer.currentSet}
          totalSets={timer.totalSets}
          logs={timer.logs}
          styles={styles}
        />

        {/* Stats do treino ativo */}
        <View style={styles.activeStats}>
          <View style={styles.activeStatItem}>
            <Ionicons name="time" size={ICON_SIZES.xs} color={colors.primary} />
            <AnimatedCounter value={Math.floor(timer.elapsed / 60)} style={styles.activeStatValue} />
            <Text style={styles.activeStatLabel}>min</Text>
          </View>
          <View style={styles.activeStatDivider} />
          <View style={styles.activeStatItem}>
            <Ionicons name="flame" size={ICON_SIZES.xs} color={colors.secondary} />
            <AnimatedCounter value={timer.totalXP} style={styles.activeStatValue} />
            <Text style={styles.activeStatLabel}>XP</Text>
          </View>
          <View style={styles.activeStatDivider} />
          <View style={styles.activeStatItem}>
            <Ionicons name="barbell" size={ICON_SIZES.xs} color={colors.success} />
            <AnimatedCounter value={timer.logs.length} style={styles.activeStatValue} />
            <Text style={styles.activeStatLabel}>Séries</Text>
          </View>
        </View>

        <WorkoutControls 
          phase={timer.phase} 
          onPause={timer.pauseWorkout} 
          onResume={timer.resumeWorkout} 
          onSkip={timer.phase === 'resting' ? timer.skipRest : timer.skipExercise} 
          onStop={handleFinish} 
          onMarkComplete={timer.markSetComplete} 
        />
      </ScrollView>
      <Suspense fallback={<LazyFallback />}>
        <LazyRatingModal visible={showRating} onClose={dismissRating} onSubmit={handleRatingSubmit} />
      </Suspense>

      {/* Celebration Modal Overlay */}
      {showCompletion && (
        <Modal visible={showCompletion} animationType="slide" transparent>
          <Suspense fallback={<LazyFallback />}>
            <LazyWorkoutShare
              workout={workout}
              xp={xpAmount}
              duration={Math.floor(timer.elapsed / 60) || workout?.duration || 30}
              exercises={timer.logs.length || workout?.exercises?.length || 5}
              onClose={onCompletionClose}
            />
          </Suspense>
        </Modal>
      )}
    </View>
    </ErrorBoundary>
  );
}

