// app/settings/language.tsx
// Seleção de idioma com download on-demand

import { useState, useEffect } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, Platform, Alert, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../src/constants/colors'
import { useTheme } from '../../src/context/ThemeContext';;
import { SPACING, BORDER_RADIUS } from '../../src/constants/spacing';
import { ErrorBoundary } from '../../src/components';
import { useTranslation, SUPPORTED_LANGUAGES, getModelConfig, ensureModel, isModelCached } from '../../src/ml';
import { Language } from '../../src/ml/languages';

const makeStyles = (colors: any) => StyleSheet.create({
  screen: { flex: 1, backgroundColor: colors.background },
  scroll: { padding: SPACING.xl, paddingTop: Platform.OS === 'ios' ? 54 : 40 },
  title: { fontFamily: 'Montserrat_700Bold', fontSize: 22, color: colors.textTitle, marginBottom: SPACING.sm },
  subtitle: { fontFamily: 'Inter_400Regular', fontSize: 14, color: colors.textMuted, marginBottom: SPACING.xl },
  option: {
    flexDirection: 'row', alignItems: 'center', gap: SPACING.md,
    padding: SPACING.lg, borderRadius: BORDER_RADIUS.md,
    marginBottom: SPACING.sm, borderWidth: 1, borderColor: colors.border,
  },
  optionActive: { borderColor: colors.primary, backgroundColor: colors.primary + '10' },
  flag: { fontSize: 28 },
  optionInfo: { flex: 1 },
  optionLabel: { fontFamily: 'Montserrat_600SemiBold', fontSize: 15, color: colors.textTitle },
  optionNative: { fontFamily: 'Inter_400Regular', fontSize: 12, color: colors.textMuted },
  downloadInfo: { flexDirection: 'row', alignItems: 'center', gap: SPACING.xs },
  baseLabel: { fontFamily: 'Inter_500Medium', fontSize: 12, color: colors.primary },
  infoCard: {
    flexDirection: 'row', gap: SPACING.sm, marginTop: SPACING.xl,
    padding: SPACING.md, backgroundColor: colors.info + '15',
    borderRadius: BORDER_RADIUS.md, borderWidth: 1, borderColor: colors.info + '30',
  },
  infoText: { flex: 1, fontFamily: 'Inter_400Regular', fontSize: 12, color: colors.info },
});

export default function LanguageScreen() {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  const { locale, setLocale, isModelLoaded, isLoadingModel, downloadProgress } = useTranslation();
  const [downloading, setDownloading] = useState<string | null>(null);
  const [downloadedModels, setDownloadedModels] = useState<Set<string>>(new Set());

  // Verificar modelos já baixados
  useEffect(() => {
    checkDownloadedModels();
  }, []);

  const checkDownloadedModels = async () => {
    const downloaded = new Set<string>();
    for (const lang of SUPPORTED_LANGUAGES) {
      if (lang.code === 'pt') continue;
      const config = getModelConfig('pt', lang.code);
      if (config) {
        const cached = await isModelCached(config);
        if (cached) downloaded.add(lang.code);
      }
    }
    setDownloadedModels(downloaded);
  };

  const handleSelect = async (lang: Language) => {
    if (lang.code === locale) return;

    // PT é o idioma base
    if (lang.code === 'pt') {
      await setLocale('pt');
      return;
    }

    // Verificar se modelo está disponível
    const config = getModelConfig('pt', lang.code);
    if (!config) {
      Alert.alert(
        'Indisponível',
        `O modelo de tradução para ${lang.label} ainda não está disponível.`
      );
      return;
    }

    // Verificar se já está baixado
    const isCached = downloadedModels.has(lang.code);
    if (isCached) {
      await setLocale(lang.code);
      return;
    }

    // Perguntar se quer baixar
    const sizeMB = Math.round((config.encoderSize + config.decoderSize) / 1024 / 1024);
    Alert.alert(
      'Baixar Modelo',
      `O modelo de tradução PT→${lang.label} tem ~${sizeMB}MB. Deseja baixar?`,
      [
        { text: 'Cancelar', style: 'cancel' },
        {
          text: 'Baixar',
          onPress: () => downloadModel(lang, config),
        },
      ]
    );
  };

  const downloadModel = async (lang: Language, config: any) => {
    setDownloading(lang.code);

    try {
      await ensureModel(config, (progress) => {
        // Progresso visual
      });

      setDownloadedModels(prev => new Set([...prev, lang.code]));
      await setLocale(lang.code);

      Alert.alert('Sucesso', `${lang.label} ativado!`);
    } catch (error) {
      Alert.alert('Erro', 'Falha ao baixar modelo. Tente novamente.');
    } finally {
      setDownloading(null);
    }
  };

  const renderLanguage = (lang: Language) => {
    const isActive = locale === lang.code;
    const isDownloading = downloading === lang.code;
    const isDownloaded = downloadedModels.has(lang.code);
    const isBase = lang.code === 'pt';

    return (
      <TouchableOpacity
        key={lang.code}
        style={[styles.option, isActive && styles.optionActive]}
        onPress={() => handleSelect(lang)}
        disabled={isDownloading}
      >
        <Text style={styles.flag}>{lang.flag}</Text>

        <View style={styles.optionInfo}>
          <Text style={styles.optionLabel}>{lang.label}</Text>
          <Text style={styles.optionNative}>{lang.native}</Text>
        </View>

        {isDownloading ? (
          <View style={styles.downloadInfo}>
            <ActivityIndicator size="small" color={colors.primary} />
          </View>
        ) : isActive ? (
          <Ionicons name="checkmark-circle" size={22} color={colors.primary} />
        ) : isBase ? (
          <Text style={styles.baseLabel}>Base</Text>
        ) : isDownloaded ? (
          <Ionicons name="checkmark-circle" size={20} color={colors.success} />
        ) : lang.available ? (
          <Ionicons name="download-outline" size={20} color={colors.textMuted} />
        ) : (
          <Ionicons name="lock-closed-outline" size={20} color={colors.border} />
        )}
      </TouchableOpacity>
    );
  };

  return (
    <ErrorBoundary screenName="Language">
      <ScrollView style={styles.screen} contentContainerStyle={styles.scroll}>
        <Text style={styles.title}>IDIOMA</Text>
        <Text style={styles.subtitle}>Selecione o idioma do app</Text>

        {SUPPORTED_LANGUAGES.map(renderLanguage)}

        <View style={styles.infoCard}>
          <Ionicons name="information-circle" size={20} color={colors.info} />
          <Text style={styles.infoText}>
            Modelos são baixados sob demanda e ficam salvos no dispositivo. Tradução funciona offline.
          </Text>
        </View>
      </ScrollView>
    </ErrorBoundary>
  );
}

