  historySection: { marginHorizontal: SPACING.lg, marginBottom: SPACING.xl },
  historyTitle: { fontFamily: 'Montserrat_700Bold', fontSize: 16, color: colors.textTitle, marginBottom: SPACING.md },
  historyItem: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', backgroundColor: colors.surface, borderRadius: BORDER_RADIUS.md, padding: SPACING.md, marginBottom: SPACING.sm, borderWidth: 1, borderColor: colors.border },
  historyInfo: { flex: 1 },
  historyDate: { fontFamily: 'Inter_400Regular', fontSize: 12, color: colors.textMuted },
  historyAmount: { fontFamily: 'Montserrat_700Bold', fontSize: 14, color: colors.textTitle, marginTop: 2 },
  historyStatus: { paddingHorizontal: SPACING.sm, paddingVertical: 4, borderRadius: BORDER_RADIUS.sm },
  historyStatusText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 11 },
});

export default function SubscriptionScreen() {
  const { colors } = useTheme();
  const styles = makeStyles(colors);
  const router = useRouter();
  const { isSmall } = useResponsive();
  const {
    payments, loading, status,
    currentPlan, isSubscribed, handleCancel,
  } = useSubscription();

  // Animacoes
  const fadeAnim = useMemo(() => new Animated.Value(0), []);
  const slideAnim = useMemo(() => new Animated.Value(20), []);
  const scaleAnim = useMemo(() => new Animated.Value(0.95), []);

  useEffect(() => {
    if (!loading) {
      Animated.parallel([
        Animated.timing(fadeAnim, { toValue: 1, duration: 500, useNativeDriver: true }),
        Animated.spring(slideAnim, { toValue: 0, friction: 8, tension: 55, useNativeDriver: true }),
        Animated.spring(scaleAnim, { toValue: 1, friction: 5, useNativeDriver: true }),
      ]).start();
    }
  }, [loading]);

  if (loading) {
    return (
      <View style={[layout.screen, styles.loadingContainer]}>
        <Loading variant="pulse" />
      </View>
    );
  }

  return (
    <ErrorBoundary screenName="Subscription">
      <ScrollView style={layout.screen} contentContainerStyle={layout.scroll} showsVerticalScrollIndicator={false}>
        {/* Header */}
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()}>
            <Ionicons name="arrow-back" size={24} color={colors.textTitle} />
          </TouchableOpacity>
          <Text style={[typography.h2, { fontSize: isSmall ? 20 : 24 }]}>Minha Assinatura</Text>
          <View style={{ width: 24 }} />
        </View>

        <Animated.View style={{ opacity: fadeAnim, transform: [{ translateY: slideAnim }, { scale: scaleAnim }] }}>
          {/* Status card */}
          <View style={[styles.statusCard, { borderColor: status.color + '40', backgroundColor: status.color + '08' }]}>
            <View style={[styles.statusIcon, { backgroundColor: status.color + '20' }]}>
              <Ionicons name={status.icon} size={32} color={status.color} />
            </View>
            <View style={styles.statusInfo}>
              <Text style={[styles.statusLabel, { color: status.color }]}>{status.label}</Text>
              {currentPlan && (
                <Text style={styles.statusPlan}>{currentPlan.name} - {currentPlan.priceText}{currentPlan.period}</Text>
              )}
              {!isSubscribed && !currentPlan && (
                <Text style={styles.statusHint}>Ative um plano para acessar todo o conteúdo</Text>
              )}
            </View>
          </View>

          {/* Plano ativo */}
          {isSubscribed && currentPlan && (
            <View style={styles.planCard}>
              <Text style={styles.planTitle}>PLANO ATUAL</Text>
              <Text style={styles.planName}>{currentPlan.name}</Text>
              <View style={styles.planFeatures}>
                {currentPlan.features.filter(f => f.included).map((feature, i) => (
                  <View key={i} style={styles.featureRow}>
                    <Ionicons name="checkmark-circle" size={16} color={colors.success} />
                    <Text style={styles.featureText}>{feature.text}</Text>
                  </View>
                ))}
              </View>
            </View>
          )}

          {/* Upgrade button */}
          {!isSubscribed && (
            <GradientButton
              title="ASSINAR AGORA"
              icon="rocket"
              onPress={() => router.push('/paywall')}
              size={isSmall ? 'md' : 'lg'}
            />
          )}

          {/* Info items */}
          <View style={styles.infoSection}>
            <Text style={styles.infoTitle}>Por que assinar?</Text>
            {INFO_ITEMS.map((item, i) => (
              <View key={i} style={styles.infoRow}>
                <View style={[styles.infoIcon, { backgroundColor: item.color + '15' }]}>
                  <Ionicons name={item.icon} size={18} color={item.color} />
                </View>
                <View style={styles.infoContent}>
                  <Text style={styles.infoLabel}>{item.label}</Text>
                  <Text style={styles.infoDesc}>{item.description}</Text>
                </View>
              </View>
            ))}
          </View>

          {/* Historico */}
          {payments && payments.length > 0 && (
            <View style={styles.historySection}>
              <Text style={styles.historyTitle}>Historico de Pagamentos</Text>
              {payments.slice(0, 5).map((payment, i) => (
                <View key={i} style={[styles.historyItem, { opacity: Math.min(1, 0.5 + i * 0.1) }]}>
                  <View style={styles.historyInfo}>
                    <Text style={styles.historyDate}>{new Date(payment.created_at).toLocaleDateString('pt-BR')}</Text>
                    <Text style={styles.historyAmount}>R$ {payment.amount?.toFixed(2)}</Text>
                  </View>
                  <View style={[styles.historyStatus, { backgroundColor: payment.status === 'paid' ? colors.success + '15' : colors.attention + '15' }]}>
                    <Text style={[styles.historyStatusText, { color: payment.status === 'paid' ? colors.success : colors.attention }]}>
                      {payment.status === 'paid' ? 'Pago' : 'Pendente'}
                    </Text>
                  </View>
                </View>
              ))}
            </View>
          )}
        </Animated.View>
      </ScrollView>
    </ErrorBoundary>
  );
}

