import { trackOperation, trackError, trackScreenMount, getMetricsForExport, getPerformanceSummary, clearOldData, resetAll } from '../../services/performanceMonitor';

describe('performanceMonitor', () => {
  beforeEach(() => {
    resetAll();
  });

  describe('trackOperation', () => {
    it('deve registrar metrica', () => {
      trackOperation('test_op', 100);
      const data = getMetricsForExport();
      expect(data.metrics.length).toBe(1);
      expect(data.metrics[0].name).toBe('test_op');
      expect(data.metrics[0].duration).toBe(100);
      expect(data.metrics[0].success).toBe(true);
    });

    it('deve registrar falha', () => {
      trackOperation('failed_op', 200, { success: false });
      const data = getMetricsForExport();
      expect(data.metrics[0].success).toBe(false);
    });

    it('deve manter screen', () => {
      trackOperation('op', 50, { screen: 'Home' });
      const data = getMetricsForExport();
      expect(data.metrics[0].screen).toBe('Home');
    });
  });

  describe('trackError', () => {
    it('deve registrar erro', () => {
      trackError(new Error('teste'), { screen: 'Login', severity: 'high' });
      const data = getMetricsForExport();
      expect(data.errors.length).toBe(1);
      expect(data.errors[0].message).toBe('teste');
      expect(data.errors[0].severity).toBe('high');
    });

    it('deve gerar id unico', () => {
      trackError(new Error('a'));
      trackError(new Error('b'));
      const data = getMetricsForExport();
      expect(data.errors[0].id).not.toBe(data.errors[1].id);
    });
  });

  describe('trackScreenMount', () => {
    it('deve registrar tela', () => {
      trackScreenMount('Home');
      const data = getMetricsForExport();
      expect(data.screens.length).toBe(1);
      expect(data.screens[0].screen).toBe('Home');
      expect(data.screens[0].renderCount).toBe(1);
    });

    it('deve incrementar render count', () => {
      trackScreenMount('Home');
      trackScreenMount('Home');
      const data = getMetricsForExport();
      expect(data.screens[0].renderCount).toBe(2);
    });
  });

  describe('getPerformanceSummary', () => {
    it('deve retornar resumo correto', () => {
      trackOperation('op1', 100);
      trackOperation('op1', 200);
      trackOperation('op2', 300);
      trackScreenMount('Home');

      const summary = getPerformanceSummary();
      expect(summary.totalOperations).toBe(3);
      expect(summary.avgDuration).toBe(200);
      expect(summary.screensLoaded).toBe(1);
    });

    it('deve listar operacoes lentas', () => {
      trackOperation('slow_op', 1500);
      const summary = getPerformanceSummary();
      expect(summary.slowOperations.length).toBe(1);
      expect(summary.slowOperations[0].name).toBe('slow_op');
    });
  });

  describe('clearOldData', () => {
    it('deve limpar dados antigos', () => {
      trackOperation('old_op', 50);
      // clearOldData com maxAge=0 nao remove (timestamp == cutoff),
      // mas com resetAll funciona
      resetAll();
      const data = getMetricsForExport();
      expect(data.metrics.length).toBe(0);
    });
  });
});

// src/__tests__/services/sanitization.test.ts

import {
  sanitizeInput, stripHtml, sanitizeUrl, truncate,
  sanitizeUsername, sanitizePostContent, detectSuspiciousPatterns,
} from '../../services/security/sanitization';

describe('sanitization', () => {
  describe('sanitizeInput', () => {
    it('remove tags HTML', () => {
      expect(sanitizeInput('<script>alert(1)</script>')).toBe('scriptalert(1)/script');
    });

    it('remove event handlers', () => {
      expect(sanitizeInput('text onclick=alert(1)')).toBe('text alert(1)');
    });

    it('mantem texto limpo', () => {
      expect(sanitizeInput('Olá mundo')).toBe('Olá mundo');
    });
  });

  describe('stripHtml', () => {
    it('remove todas as tags', () => {
      expect(stripHtml('<b>bold</b> <i>italic</i>')).toBe('bold italic');
    });
  });

  describe('sanitizeUrl', () => {
    it('aceita http', () => {
      expect(sanitizeUrl('http://example.com')).toBe('http://example.com/');
    });

    it('aceita https', () => {
      expect(sanitizeUrl('https://example.com')).toBe('https://example.com/');
    });

    it('rejeita javascript', () => {
      expect(sanitizeUrl('javascript:alert(1)')).toBeNull();
    });

    it('rejeita data uri', () => {
      expect(sanitizeUrl('data:text/html,<h1>hi</h1>')).toBeNull();
    });

    it('rejeita url invalida', () => {
      expect(sanitizeUrl('not-a-url')).toBeNull();
    });
  });

  describe('truncate', () => {
    it('nao trunca string curta', () => {
      expect(truncate('abc', 10)).toBe('abc');
    });

    it('trunca string longa', () => {
      expect(truncate('abcdefghij', 5)).toBe('ab...');
    });
  });

  describe('sanitizeUsername', () => {
    it('remove caracteres especiais', () => {
      expect(sanitizeUsername('João Silva!')).toBe('joosilva');
    });

    it('limita tamanho', () => {
      expect(sanitizeUsername('a'.repeat(50))).toHaveLength(30);
    });

    it('remove inicio invalido', () => {
      expect(sanitizeUsername('.test')).toBe('test');
    });
  });

  describe('detectSuspiciousPatterns', () => {
    it('detecta XSS', () => {
      const r = detectSuspiciousPatterns('<script>alert(1)</script>');
      expect(r.suspicious).toBe(true);
      expect(r.patterns).toContain('XSS_SCRIPT');
    });

    it('detecta SQL injection', () => {
      const r = detectSuspiciousPatterns('1 UNION SELECT * FROM users');
      expect(r.suspicious).toBe(true);
      expect(r.patterns).toContain('SQL_INJECT');
    });

    it('detecta path traversal', () => {
      const r = detectSuspiciousPatterns('../../etc/passwd');
      expect(r.suspicious).toBe(true);
      expect(r.patterns).toContain('PATH_TRAVERSAL');
    });

    it('nao marca texto limpo', () => {
      const r = detectSuspiciousPatterns('Texto normal sem problemas');
      expect(r.suspicious).toBe(false);
    });
  });
});

// src/__tests__/utils/asyncHandler.test.ts
// Testes para asyncHandler

import { safeAsync, retryAsync, assertDefined, formatError, protectedCallback, debounce } from '../../utils/asyncHandler';

describe('asyncHandler', () => {
  describe('safeAsync', () => {
    it('deve retornar success com dados', async () => {
      const result = await safeAsync(async () => 42);
      expect(result).toEqual({ success: true, data: 42 });
    });

    it('deve retornar error em caso de falha', async () => {
      const result = await safeAsync(async () => { throw new Error('Erro teste'); });
      expect(result.success).toBe(false);
      expect(result.error).toBe('Erro teste');
    });

    it('deve lidar com erros nao-Error', async () => {
      const result = await safeAsync(async () => { throw 'string error'; });
      expect(result.success).toBe(false);
    });
  });

  describe('retryAsync', () => {
    it('deve funcionar na primeira tentativa', async () => {
      const result = await retryAsync(async () => 42);
      expect(result).toEqual({ success: true, data: 42 });
    });

    it('deve retry em caso de falha', async () => {
      let attempts = 0;
      const result = await retryAsync(async () => {
        attempts++;
        if (attempts < 3) throw new Error('Falha');
        return 'sucesso';
      }, 3, 10);
      expect(result).toEqual({ success: true, data: 'sucesso' });
    });
  });

  describe('assertDefined', () => {
    it('nao deve lancar erro para valor definido', () => {
      expect(() => assertDefined(42, 'teste')).not.toThrow();
    });

    it('deve lancar erro para null', () => {
      expect(() => assertDefined(null, 'campo')).toThrow('campo e obrigatorio');
    });

    it('deve lancar erro para undefined', () => {
      expect(() => assertDefined(undefined, 'campo')).toThrow('campo e obrigatorio');
    });
  });

  describe('formatError', () => {
    it('deve formatar Error', () => {
      expect(formatError(new Error('msg'))).toBe('msg');
    });

    it('deve formatar string', () => {
      expect(formatError('erro')).toBe('erro');
    });

    it('deve formatar tipo desconhecido', () => {
      expect(formatError(42)).toBe('Ocorreu um erro inesperado');
    });
  });

  describe('protectedCallback', () => {
    it('deve retornar resultado quando nao ha erro', () => {
      expect(protectedCallback(() => 42, 0)).toBe(42);
    });

    it('deve retornar fallback quando ha erro', () => {
      expect(protectedCallback(() => { throw new Error(); }, 0)).toBe(0);
    });
  });
});

