// Prompt de verificação 2FA - NOVAIX FITNESS

import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, Alert, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING } from '../../constants/spacing';
import { verify2FA } from '../../services/totp';
import { typography } from '../../styles';

export default function TwoFactorPrompt({ userId, onVerified }) {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);

  const handleVerify = async () => {
    if (code.length !== 6) {
      Alert.alert('Erro', 'Digite o código de 6 dígitos.');
      return;
    }
    setLoading(true);
    try {
      const valid = await verify2FA(userId, code);
      if (valid) {
        onVerified();
      } else {
        Alert.alert('Erro', 'Código inválido ou expirado. Tente novamente.');
        setCode('');
      }
    } catch (err) {
      Alert.alert('Erro', 'Falha ao verificar código.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <Ionicons name="lock-closed" size={48} color={COLORS.primary} />
      <Text style={typography.h3}>VERIFICAÇÃO 2FA</Text>
      <Text style={typography.bodyMuted}>Digite o código do Google Authenticator</Text>

      <TextInput
        style={styles.input}
        value={code}
        onChangeText={setCode}
        placeholder="000000"
        placeholderTextColor={COLORS.textMuted}
        keyboardType="number-pad"
        maxLength={6}
        autoFocus
        accessibilityLabel="Código de verificação 2FA"
      />

      <TouchableOpacity style={[styles.btn, loading && styles.btnDisabled]} onPress={handleVerify} disabled={loading} accessibilityLabel="Verificar código" accessibilityRole="button" accessibilityHint="Verifica o código 2FA e libera o acesso">
        {loading ? (
          <ActivityIndicator size="small" color={COLORS.background} />
        ) : (
          <>
            <Ionicons name="log-in" size={20} color={COLORS.background} />
            <Text style={styles.btnText}>VERIFICAR</Text>
          </>
        )}
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: SPACING.xl, gap: SPACING.md },
  input: { backgroundColor: COLORS.surface, borderRadius: 8, padding: SPACING.lg, borderWidth: 1, borderColor: COLORS.border, color: COLORS.textTitle, fontSize: 28, fontFamily: 'Montserrat_700Bold', textAlign: 'center', letterSpacing: 10, width: '100%', marginTop: SPACING.lg },
  btn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: SPACING.sm, backgroundColor: COLORS.primary, borderRadius: 8, paddingVertical: SPACING.lg, width: '100%', marginTop: SPACING.lg },
  btnDisabled: { opacity: 0.6 },
  btnText: { fontFamily: 'Montserrat_700Bold', fontSize: 14, color: COLORS.background, letterSpacing: 1 },
});

// src/components/admin/TwoFactorSetup.js
// Configuração inicial de 2FA - NOVAIX FITNESS

import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, Alert, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { setup2FA, confirm2FA } from '../../services/totp';
import { layout, typography } from '../../styles';

export default function TwoFactorSetup({ userId, onComplete }) {
  const [secret, setSecret] = useState('');
  const [uri, setUri] = useState('');
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState('loading');

  useEffect(() => {
    async function init() {
      try {
        const result = await setup2FA(userId);
        setSecret(result.secret);
        setUri(result.uri);
        setStep('show_secret');
      } catch (err) {
        Alert.alert('Erro', 'Falha ao iniciar configuração 2FA.');
      }
    }
    init();
  }, [userId]);

  const handleConfirm = async () => {
    if (code.length !== 6) {
      Alert.alert('Erro', 'Digite o código de 6 dígitos.');
      return;
    }
    setLoading(true);
    try {
      await confirm2FA(userId, code);
      Alert.alert('Sucesso', '2FA configurado com sucesso!', [
        { text: 'OK', onPress: onComplete },
      ]);
    } catch (err) {
      Alert.alert('Erro', err.message || 'Código inválido.');
    } finally {
      setLoading(false);
    }
  };

  if (step === 'loading') {
    return (
      <View style={styles.center}>
        <ActivityIndicator size="large" color={COLORS.primary} />
        <Text style={[typography.bodyMuted, { marginTop: SPACING.md }]}>Gerando chave secreta...</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="shield-checkmark" size={48} color={COLORS.primary} />
        <Text style={typography.h3}>CONFIGURAR 2FA</Text>
        <Text style={typography.bodyMuted}>Proteja o painel admin com autenticação em dois fatores</Text>
      </View>

      <View style={styles.step}>
        <Text style={typography.h5}>Passo 1: Copie a chave secreta</Text>
        <Text style={typography.bodySmall}>{`Abra o Google Authenticator e escolha "Inserir chave"`}</Text>
        <TouchableOpacity style={styles.secretBox} onPress={() => {
          try {
            const Clipboard = require('expo-clipboard');
            Clipboard.setStringAsync(secret);
            Alert.alert('Copiado!', 'Chave copiada para a área de transferência.');
          } catch { Alert.alert('Copiar', 'Selecione e copie a chave manualmente.'); }
        }} accessibilityLabel="Copiar chave secreta" accessibilityRole="button" accessibilityHint="Copia a chave 2FA para a área de transferência">
          <Text style={styles.secretText} selectable>{secret}</Text>
          <Ionicons name="copy" size={20} color={COLORS.primary} />
        </TouchableOpacity>
      </View>

      <View style={styles.step}>
        <Text style={typography.h5}>Passo 2: Digite o código</Text>
        <Text style={typography.bodySmall}>Cole o código de 6 dígitos do Authenticator</Text>
        <TextInput
          style={styles.input}
          value={code}
          onChangeText={setCode}
          placeholder="000000"
          placeholderTextColor={COLORS.textMuted}
          keyboardType="number-pad"
          maxLength={6}
          accessibilityLabel="Código de verificação 2FA"
        />
      </View>

      <TouchableOpacity style={[styles.btn, loading && styles.btnDisabled]} onPress={handleConfirm} disabled={loading} accessibilityLabel="Confirmar e ativar 2FA" accessibilityRole="button" accessibilityHint="Verifica o código e ativa a autenticação em dois fatores">
        {loading ? (
          <ActivityIndicator size="small" color={COLORS.background} />
        ) : (
          <>
            <Ionicons name="checkmark-circle" size={20} color={COLORS.background} />
            <Text style={styles.btnText}>CONFIRMAR E ATIVAR</Text>
          </>
        )}
      </TouchableOpacity>
    </View>
  );
