import React, { useState, useEffect, useRef, useMemo } from 'react';
import { View, Text, StyleSheet, Animated, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { MOCK_BENCHMARK_DATA, BenchmarkData } from '../../data/analyticsMock';

interface MetricBarProps {
  label: string;
  userValue: number;
  peerValue: number;
  unit: string;
  higherIsBetter?: boolean;
}

function MetricBar({ label, userValue, peerValue, unit, higherIsBetter = true }: MetricBarProps) {
  const [] = useState(() => new Animated.Value());
  const isAbove = higherIsBetter ? userValue > peerValue : userValue < peerValue;
  const isBelow = higherIsBetter ? userValue < peerValue : userValue > peerValue;
  const diff = peerValue === 0 ? 0 : Math.round(((userValue - peerValue) / peerValue) * 100);

  useEffect(() => {
    Animated.spring(animatedValue, { toValue: 1, tension: 30, friction: 8, useNativeDriver: false }).start();
  }, [animatedValue]);

  const maxVal = Math.max(userValue, peerValue) * 1.2 || 1;

  return (
    <View style={styles.metricContainer}>
      <View style={styles.metricHeader}>
        <Text style={styles.metricLabel}>{label}</Text>
        <View style={[styles.statusBadge, { backgroundColor: (isAbove ? COLORS.success : isBelow ? COLORS.error : COLORS.textMuted) + '20' }]}>
          <Ionicons
            name={isAbove ? 'arrow-up' : isBelow ? 'arrow-down' : 'remove'}
            size={10}
            color={isAbove ? COLORS.success : isBelow ? COLORS.error : COLORS.textMuted}
          />
          <Text style={[styles.statusText, { color: isAbove ? COLORS.success : isBelow ? COLORS.error : COLORS.textMuted }]}>
            {diff > 0 ? '+' : ''}{diff}%
          </Text>
        </View>
      </View>
      <View style={styles.barsContainer}>
        <View style={styles.barRow}>
          <Text style={styles.barLabel}>Voce</Text>
          <View style={styles.barTrack}>
            <Animated.View style={[styles.barFill, styles.barUser, { width: animatedValue.interpolate({ inputRange: [0, 1], outputRange: ['0%', `${(userValue / maxVal) * 100}%`] }) }]} />
          </View>
          <Text style={styles.barValue}>{userValue}{unit}</Text>
        </View>
        <View style={styles.barRow}>
          <Text style={styles.barLabel}>Media</Text>
          <View style={styles.barTrack}>
            <Animated.View style={[styles.barFill, styles.barPeer, { width: animatedValue.interpolate({ inputRange: [0, 1], outputRange: ['0%', `${(peerValue / maxVal) * 100}%`] }) }]} />
          </View>
          <Text style={styles.barValue}>{peerValue}{unit}</Text>
        </View>
      </View>
    </View>
  );
}

function PercentileRing({ percentile }: { percentile: number }) {
  const [] = useState(() => new Animated.Value());
  const circumference = 2 * Math.PI * 36;

  useEffect(() => {
    Animated.timing(animatedValue, { toValue: percentile, duration: 1500, useNativeDriver: false }).start();
  }, [percentile, animatedValue]);

  const strokeDashoffset = circumference - (percentile / 100) * circumference;
  const color = percentile >= 70 ? COLORS.success : percentile >= 40 ? COLORS.primary : COLORS.attention;
  const label = percentile >= 90 ? 'Top' : percentile >= 70 ? 'Acima' : percentile >= 40 ? 'Medio' : 'Abaixo';

  return (
    <View style={styles.percentileContainer}>
      <View style={styles.percentileRingOuter}>
        <View style={[styles.percentileRing, { borderColor: COLORS.border }]}>
          <View style={[styles.percentileRingFill, { borderColor: color, borderWidth: 4 }]} />
        </View>
        <View style={styles.percentileCenter}>
          <Text style={[styles.percentileValue, { color }]}>{percentile}</Text>
          <Text style={styles.percentileLabel}>percentil</Text>
        </View>
      </View>
      <View style={[styles.percentileBadge, { backgroundColor: color + '20' }]}>
        <Text style={[styles.percentileBadgeText, { color }]}>TOP {100 - percentile}%</Text>
      </View>
    </View>
  );
}

export default function BenchmarkComparison({ data }: { data?: BenchmarkData }) {
  const benchmarkData = data || MOCK_BENCHMARK_DATA;
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 500, useNativeDriver: true }).start();
  }, [fadeAnim]);

  const metrics: MetricBarProps[] = useMemo(() => [
    { label: 'Frequencia semanal', userValue: benchmarkData.userStats.workoutsPerWeek, peerValue: benchmarkData.peerStats.workoutsPerWeek, unit: 'x' },
    { label: 'Duracao media', userValue: benchmarkData.userStats.avgDuration, peerValue: benchmarkData.peerStats.avgDuration, unit: 'min' },
    { label: 'Streak atual', userValue: benchmarkData.userStats.streak, peerValue: benchmarkData.peerStats.streak, unit: 'dias' },
    { label: 'Total minutos', userValue: benchmarkData.userStats.totalMinutes, peerValue: benchmarkData.peerStats.totalMinutes, unit: 'min' },
    { label: 'IMC', userValue: benchmarkData.userStats.bmi, peerValue: benchmarkData.peerStats.bmi, unit: '', higherIsBetter: false },
  ], [benchmarkData]);

  const aboveAverage = metrics.filter(m => m.higherIsBetter ? m.userValue > m.peerValue : m.userValue < m.peerValue).length;

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <Ionicons name="people" size={18} color={COLORS.purple} />
          <Text style={styles.title}>BENCHMARK</Text>
        </View>
        <View style={styles.peerBadge}>
          <Ionicons name="person" size={10} color={COLORS.textMuted} />
          <Text style={styles.peerText}>{benchmarkData.ageRange} | {benchmarkData.goal} | {benchmarkData.experience}</Text>
        </View>
      </View>

      <View style={styles.topSection}>
        <PercentileRing percentile={benchmarkData.percentile} />
        <View style={styles.topInfo}>
          <Text style={styles.topTitle}>Voce esta a frente de</Text>
          <Text style={styles.topValue}>{benchmarkData.percentile}%</Text>
          <Text style={styles.topSubtitle}>dos usuarios do seu perfil</Text>
          <View style={styles.aboveAverageBadge}>
            <Ionicons name="checkmark-circle" size={14} color={COLORS.success} />
            <Text style={styles.aboveAverageText}>Acima da media em {aboveAverage}/{metrics.length} metricas</Text>
          </View>
        </View>
      </View>

      <View style={styles.metricsContainer}>
        {metrics.map((metric, index) => (
          <MetricBar key={index} {...metric} />
        ))}
      </View>

      <TouchableOpacity style={styles.infoRow}>
        <Ionicons name="information-circle-outline" size={12} color={COLORS.textMuted} />
        <Text style={styles.infoText}>Comparado com usuarios de {benchmarkData.ageRange}, meta {benchmarkData.goal.toLowerCase()} e experiencia {benchmarkData.experience.toLowerCase()}</Text>
      </TouchableOpacity>
    </Animated.View>
  );
}

