const { width: SCREEN_WIDTH } = Dimensions.get('window');

const CATEGORY_COLORS = {
  'Musculação': COLORS.primary, 'Cardio': COLORS.secondary, 'Calistenia': COLORS.success,
  'Flexibilidade': COLORS.attention, 'HIIT': COLORS.error, 'Yoga': COLORS.info,
};

const chartConfig = {
  backgroundColor: COLORS.surface,
  backgroundGradientFrom: COLORS.surface,
  backgroundGradientTo: COLORS.surface,
  decimalPlaces: 0,
  color: (opacity = 1) => `rgba(204, 255, 0, ${opacity})`,
  labelColor: () => COLORS.textMuted,
  style: { borderRadius: 12 },
  propsForDots: { r: '4', strokeWidth: '2', stroke: COLORS.primary },
};

function ChartCard({ title, subtitle, children, onPress, icon }) {
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 400, useNativeDriver: true }).start();
  }, []);

  return (
    <TouchableOpacity style={[styles.chartCard, { opacity: fadeAnim }]} onPress={onPress} activeOpacity={onPress ? 0.8 : 1} accessibilityLabel={title} accessibilityRole={onPress ? 'button' : undefined} accessibilityHint={onPress ? 'Expande o gráfico' : undefined}>
      <View style={styles.chartHeader}>
        <View style={styles.chartHeaderLeft}>
          {icon && <Ionicons name={icon} size={16} color={COLORS.primary} />}
          <Text style={styles.chartTitle}>{title}</Text>
        </View>
        {subtitle && <Text style={styles.chartSubtitle}>{subtitle}</Text>}
        {onPress && <Ionicons name="expand-outline" size={16} color={COLORS.textMuted} />}
      </View>
      {children}
    </TouchableOpacity>
  );
}

export function FrequencyChart({ data, onPress }) {
  if (!data || data.length === 0) return null;
  return (
    <ChartCard title="FREQÜÊNCIA SEMANAL" subtitle="Treinos por semana" icon="calendar" onPress={onPress}>
      <BarChart data={{ labels: data.map(f => f.week), datasets: [{ data: data.map(f => f.count || 0) }] }} width={SCREEN_WIDTH - 80} height={180} chartConfig={chartConfig} showValuesOnTopOfBars fromZero />
