const PERIODS = [
  { key: 'week', label: '7 dias', icon: 'calendar' },
  { key: 'month', label: '1 mês', icon: 'calendar-outline' },
  { key: 'quarter', label: '3 meses', icon: 'calendar-outline' },
  { key: 'year', label: '1 ano', icon: 'calendar-outline' },
