import React, { useState, useEffect, useRef, useMemo } from 'react';
import { View, Text, StyleSheet, Animated, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { MOCK_PROGRESS_PREDICTION, ProgressPredictionData } from '../../data/analyticsMock';

interface Prediction {
  days: number;
  predictedWeight: number;
  change: number;
  confidence: number;
}

function linearRegression(data: number[]): { slope: number; intercept: number; r2: number } {
  const n = data.length;
  if (n < 2) return { slope: 0, intercept: data[0] || 0, r2: 0 };
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0, sumY2 = 0;
  for (let i = 0; i < n; i++) {
    sumX += i; sumY += data[i]; sumXY += i * data[i]; sumX2 += i * i; sumY2 += data[i] * data[i];
  }
  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  const intercept = (sumY - slope * sumX) / n;
  const ssRes = data.reduce((s, y, i) => s + Math.pow(y - (slope * i + intercept), 2), 0);
  const ssTot = data.reduce((s, y) => s + Math.pow(y - sumY / n, 2), 0);
  const r2 = ssTot === 0 ? 0 : 1 - ssRes / ssTot;
  return { slope, intercept, r2 };
}

function AnimatedCounter({ value, duration = 1200, suffix = 'kg', decimals = 1 }: {
  value: number; duration?: number; suffix?: string; decimals?: number;
}) {
  const [] = useState(() => new Animated.Value());
  const [display, setDisplay] = useState('0');

  useEffect(() => {
    animatedValue.setValue(0);
    Animated.timing(animatedValue, { toValue: value, duration, useNativeDriver: false }).start();
    const listener = animatedValue.addListener(({ v }) => {
      setDisplay(v.toFixed(decimals));
    });
    return () => animatedValue.removeListener(listener);
  }, [value, duration, decimals, animatedValue]);

  return (
    <Text style={styles.counterValue}>
      {display}<Text style={styles.counterSuffix}> {suffix}</Text>
    </Text>
  );
}

function ConfidenceBar({ confidence }: { confidence: number }) {
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    Animated.spring(width, { toValue: confidence, tension: 40, friction: 8, useNativeDriver: false }).start();
  }, [confidence, width]);

  const color = confidence >= 70 ? COLORS.success : confidence >= 40 ? COLORS.attention : COLORS.error;
  const label = confidence >= 70 ? 'Alta' : confidence >= 40 ? 'Media' : 'Baixa';

  return (
    <View style={styles.confidenceContainer}>
      <View style={styles.confidenceHeader}>
        <Text style={styles.confidenceLabel}>Confianca da previsao</Text>
        <View style={[styles.confidenceBadge, { backgroundColor: color + '20' }]}>
          <View style={[styles.confidenceDot, { backgroundColor: color }]} />
          <Text style={[styles.confidenceBadgeText, { color }]}>{label} ({Math.round(confidence)}%)</Text>
        </View>
      </View>
      <View style={styles.confidenceTrack}>
        <Animated.View style={[styles.confidenceFill, { width: width.interpolate({ inputRange: [0, 100], outputRange: ['0%', '100%'] }), backgroundColor: color }]} />
      </View>
    </View>
  );
}

export default function ProgressPrediction({ data }: { data?: ProgressPredictionData }) {
  const predictionData = data || MOCK_PROGRESS_PREDICTION;
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 500, useNativeDriver: true }).start();
  }, [fadeAnim]);

  const predictions = useMemo(() => {
    const { weightHistory, goal } = predictionData;
    const regression = linearRegression(weightHistory);
    const monthlyRate = regression.slope * 30;
    const dailyRate = regression.slope;

    return [30, 60, 90].map(days => {
      const predictedWeight = weightHistory[weightHistory.length - 1] + dailyRate * days;
      const change = predictedWeight - weightHistory[weightHistory.length - 1];
      const confidence = Math.max(20, Math.min(95, regression.r2 * 100 - days * 0.3));
      const goalAdjusted = goal === 'perder_peso' ? Math.abs(change) : change;
      return {
        days,
        predictedWeight: Math.max(40, predictedWeight),
        change: Math.round(goalAdjusted * 10) / 10,
        confidence,
      };
    });
  }, [predictionData]);

  const getGoalIcon = () => {
    switch (predictionData.goal) {
      case 'perder_peso': return 'trending-down';
      case 'ganhar_massa': return 'trending-up';
      default: return 'remove';
    }
  };

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <Ionicons name="sparkles" size={18} color={COLORS.primary} />
          <Text style={styles.title}>PREVISAO IA</Text>
        </View>
        <View style={styles.goalBadge}>
          <Ionicons name={getGoalIcon()} size={12} color={COLORS.primary} />
          <Text style={styles.goalText}>{predictionData.goal.replace('_', ' ').toUpperCase()}</Text>
        </View>
      </View>

      <Text style={styles.subtitle}>Projecao baseada no seu historico de {predictionData.monthsActive} meses</Text>

      <View style={styles.predictionsRow}>
        {predictions.map((pred) => (
          <View key={pred.days} style={styles.predictionCard}>
            <Text style={styles.predictionDays}>{pred.days} dias</Text>
            <AnimatedCounter value={pred.predictedWeight} />
            <View style={[styles.changeBadge, { backgroundColor: pred.change <= 0 ? COLORS.successBg : COLORS.errorBg }]}>
              <Ionicons name={pred.change <= 0 ? 'arrow-down' : 'arrow-up'} size={10} color={pred.change <= 0 ? COLORS.success : COLORS.error} />
              <Text style={[styles.changeText, { color: pred.change <= 0 ? COLORS.success : COLORS.error }]}>
                {pred.change <= 0 ? '' : '+'}{pred.change}kg
              </Text>
            </View>
          </View>
        ))}
      </View>

      <ConfidenceBar confidence={predictions[0].confidence} />

      <View style={styles.insightsRow}>
        <View style={styles.insightItem}>
          <Ionicons name="barbell" size={14} color={COLORS.primary} />
          <Text style={styles.insightLabel}>Treinos/sem</Text>
          <Text style={styles.insightValue}>{predictionData.workoutsPerWeek}</Text>
        </View>
        <View style={styles.insightDivider} />
        <View style={styles.insightItem}>
          <Ionicons name="time" size={14} color={COLORS.primary} />
          <Text style={styles.insightLabel}>Media</Text>
          <Text style={styles.insightValue}>{predictionData.avgDuration}min</Text>
        </View>
        <View style={styles.insightDivider} />
        <View style={styles.insightItem}>
          <Ionicons name="speedometer" size={14} color={COLORS.primary} />
          <Text style={styles.insightLabel}>Peso atual</Text>
          <Text style={styles.insightValue}>{predictionData.currentWeight}kg</Text>
        </View>
      </View>

      <TouchableOpacity style={styles.disclaimer}>
        <Ionicons name="information-circle-outline" size={12} color={COLORS.textMuted} />
        <Text style={styles.disclaimerText}>Previsoes baseadas em projecao linear. Resultados reais podem variar.</Text>
      </TouchableOpacity>
    </Animated.View>
  );
}

