// Correlacao sono x treino - NOVAIX FITNESS

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { View, Text, StyleSheet, Animated, Dimensions, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { MOCK_SLEEP_DATA, SleepEntry } from '../../data/analyticsMock';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const CHART_WIDTH = SCREEN_WIDTH - SPACING.lg * 2 - SPACING.lg * 2;

interface Insight {
  icon: string;
  text: string;
  color: string;
}

export default function SleepCorrelation({ data }: { data?: SleepEntry[] }) {
  const sleepData = data || MOCK_SLEEP_DATA;
  const [] = useState(() => new Animated.Value());
  const [selectedPoint, setSelectedPoint] = useState<number | null>(null);

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 500, useNativeDriver: true }).start();
  }, [fadeAnim]);

  const stats = useMemo(() => {
    const avgSleep = sleepData.reduce((s, d) => s + d.sleepHours, 0) / sleepData.length;
    const avgPerformance = sleepData.reduce((s, d) => s + d.workoutPerformance, 0) / sleepData.length;
    const goodSleepDays = sleepData.filter(d => d.sleepHours >= 7);
    const avgPerformanceGoodSleep = goodSleepDays.length > 0
      ? goodSleepDays.reduce((s, d) => s + d.workoutPerformance, 0) / goodSleepDays.length
      : 0;
    const poorSleepDays = sleepData.filter(d => d.sleepHours < 6);
    const avgPerformancePoorSleep = poorSleepDays.length > 0
      ? poorSleepDays.reduce((s, d) => s + d.workoutPerformance, 0) / poorSleepDays.length
      : 0;
    const correlation = Math.round((avgPerformanceGoodSleep - avgPerformancePoorSleep) / avgPerformancePoorSleep * 100);
    return { avgSleep, avgPerformance, avgPerformanceGoodSleep, avgPerformancePoorSleep, correlation };
  }, [sleepData]);

  const insights: Insight[] = useMemo(() => [
    {
      icon: 'moon',
      text: `Treinos ${stats.correlation > 0 ? 'melhores' : 'piores'} apos 7+ horas de sono`,
      color: COLORS.info,
    },
    {
      icon: 'flash',
      text: `Performance media com bom sono: ${Math.round(stats.avgPerformanceGoodSleep)}%`,
      color: COLORS.success,
    },
    {
      icon: 'warning',
      text: `Performance com pouco sono: ${Math.round(stats.avgPerformancePoorSleep)}%`,
      color: stats.correlation > 20 ? COLORS.attention : COLORS.textMuted,
    },
  ], [stats]);

  const maxPerformance = 100;
  const maxSleep = 10;

  const barWidth = (CHART_WIDTH - SPACING.sm * (sleepData.length - 1)) / sleepData.length;

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <Ionicons name="moon" size={18} color={COLORS.info} />
          <Text style={styles.title}>CORRELACAO SONO X TREINO</Text>
        </View>
        <View style={styles.correlationBadge}>
          <Text style={styles.correlationText}>+{stats.correlation}%</Text>
        </View>
      </View>

      {/* Bar chart */}
      <View style={styles.chartContainer}>
        <View style={styles.chartHeader}>
          <Text style={styles.chartLabel}>Horas de sono</Text>
          <Text style={styles.chartLabel}>Performance (%)</Text>
        </View>
        <View style={styles.chart}>
          {sleepData.map((entry, index) => {
            const barHeight = (entry.workoutPerformance / maxPerformance) * 120;
            const sleepColor = entry.sleepHours >= 7 ? COLORS.info : entry.sleepHours >= 6 ? COLORS.attention : COLORS.error;
            const isSelected = selectedPoint === index;
            return (
              <TouchableOpacity
                key={index}
                style={styles.barWrapper}
                onPress={() => setSelectedPoint(isSelected ? null : index)}
                activeOpacity={0.7}
              >
                <Text style={styles.barValue}>{entry.workoutPerformance}</Text>
                <View style={styles.barColumn}>
                  <View style={[
                    styles.bar,
                    { height: barHeight, backgroundColor: isSelected ? COLORS.primary : sleepColor },
                  ]} />
                  <View style={[styles.barHeightIndicator, { height: (entry.sleepHours / maxSleep) * 120, backgroundColor: sleepColor + '30' }]} />
                </View>
