export default function AchievementPopup({ achievement, visible, onDone }) {
  const [opacity] = useState(() => new Animated.Value(0));
  const [scale] = useState(() => new Animated.Value(0.5));

  useEffect(() => {
    if (visible && achievement) {
      Animated.sequence([
        Animated.parallel([
          Animated.spring(scale, { toValue: 1, friction: 6, tension: 80, useNativeDriver: true }),
          Animated.timing(opacity, { toValue: 1, duration: 300, useNativeDriver: true }),
        ]),
        Animated.delay(2500),
        Animated.parallel([
          Animated.timing(scale, { toValue: 0.5, duration: 200, useNativeDriver: true }),
          Animated.timing(opacity, { toValue: 0, duration: 200, useNativeDriver: true }),
        ]),
      ]).start(() => onDone?.());
    }
  }, [visible, achievement]);

  if (!achievement) return null;

  return (
    <Animated.View style={[styles.overlay, { opacity }]} accessibilityRole="alert" accessibilityLiveRegion="assertive" accessible>
      <Animated.View style={[styles.card, { transform: [{ scale }] }]}>
        <View style={[styles.icon, { backgroundColor: achievement.color + '20' }]}>
