        </View>
        <Text style={styles.title}>CONQUISTA DESBLOQUEADA!</Text>
        <Text style={styles.name}>{achievement.name}</Text>
        <Text style={styles.description}>{achievement.description}</Text>
      </Animated.View>
    </Animated.View>
  );
}

