// Progresso de Treinos da Semana - NOVAIX FITNESS

import React, { useState, useEffect, useCallback, memo } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { Card } from '../ui/Card';
import ProgressBar from '../ui/ProgressBar';
import { supabase } from '../../config/supabase';
import { useAuth } from '../../context/AuthContext';
import { typography } from '../../styles';

export default memo(function WeeklyProgress() {
  const { user } = useAuth();
  const [completedThisWeek, setCompletedThisWeek] = useState(0);
  const [targetWeekly, setTargetWeekly] = useState(3);
  const [loading, setLoading] = useState(true);

  const fetchWeeklyStats = useCallback(async () => {
    if (!user?.id) { setLoading(false); return; }
    try {
      // Obter o início da semana (segunda-feira)
      const now = new Date();
      const day = now.getDay();
      const diff = now.getDate() - day + (day === 0 ? -6 : 1);
      const startOfWeek = new Date(now.setDate(diff));
      startOfWeek.setHours(0, 0, 0, 0);

      const [workoutsRes, profileRes] = await Promise.all([
        supabase
          .from('user_workouts')
          .select('id')
          .eq('user_id', user.id)
          .eq('completed', true)
          .gte('completed_at', startOfWeek.toISOString()),
        supabase
          .from('profiles')
          .select('onboarding')
          .eq('id', user.id)
          .single()
      ]);

      if (workoutsRes.data) {
        setCompletedThisWeek(workoutsRes.data.length);
      }

      if (profileRes.data?.onboarding) {
        // Mapeia frequência para número se for String, ex: "3 a 4 dias" -> 3
        const freqText = profileRes.data.onboarding.frequency || '';
        const parsed = parseInt(freqText.replace(/[^0-9]/g, ''), 10);
        if (!isNaN(parsed) && parsed > 0) {
          setTargetWeekly(parsed);
        }
      }
    } catch (err) {
      console.error('Erro ao buscar metas semanais:', err);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  useEffect(() => {
    fetchWeeklyStats();
  }, [fetchWeeklyStats]);

  if (loading) {
    return (
      <Card variant="surface" style={styles.card}>
        <ActivityIndicator size="small" color={COLORS.primary} />
      </Card>
    );
  }

  const progressText = `${completedThisWeek} DE ${targetWeekly} TREINOS CONCLUÍDOS`;
  const isGoalAchieved = completedThisWeek >= targetWeekly;

  return (
    <Card variant="surface" style={styles.card}>
      <View style={styles.header}>
        <View style={styles.titleContainer}>
          <Ionicons
            name={isGoalAchieved ? 'trophy' : 'calendar-outline'}
            size={22}
            color={isGoalAchieved ? COLORS.attention : COLORS.primary}
          />
          <Text style={typography.h4}>META DA SEMANA</Text>
        </View>
        {isGoalAchieved && (
          <Text style={[typography.caption, { color: COLORS.success }]}>META ATINGIDA! 🎉</Text>
        )}
      </View>

      <ProgressBar value={completedThisWeek} max={targetWeekly} label={progressText} />
    </Card>
  );
});

const styles = StyleSheet.create({
  card: { padding: SPACING.lg, marginBottom: SPACING.md },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: SPACING.md },
  titleContainer: { flexDirection: 'row', alignItems: 'center', gap: SPACING.xs },
});

import React, { useEffect, useRef, memo } from 'react';
import { View, Animated, StyleSheet } from 'react-native';
import { COLORS } from '../../constants/colors';

export default memo(function DotIndicator({ total, currentIndex }) {
  const animatedWidths = useRef(
    Array.from({ length: total }, () => new Animated.Value(0))
  ).current;

  useEffect(() => {
    animatedWidths.forEach((anim, i) => {
      Animated.timing(anim, {
        toValue: i === currentIndex ? 1 : 0,
        duration: 300,
        useNativeDriver: false,
      }).start();
    });
  }, [currentIndex]);

  return (
    <View style={styles.container} accessibilityRole="tablist" accessibilityLabel={`Slide ${currentIndex + 1} de ${total}`}>
      {animatedWidths.map((anim, i) => (
        <Animated.View
          key={i}
          style={[
            styles.dot,
            {
              width: anim.interpolate({
                inputRange: [0, 1],
                outputRange: [8, 24],
              }),
              backgroundColor: anim.interpolate({
                inputRange: [0, 1],
                outputRange: [COLORS.textMuted, COLORS.primary],
              }),
            },
          ]}
          accessibilityRole="tab"
          accessibilityState={{ selected: i === currentIndex }}
          accessibilityLabel={`Slide ${i + 1}`}
        />
      ))}
    </View>
  );
});

