// src/components/nutrition/NutritionCoach.js
// Chat IA de nutrição - NOVAIX FITNESS

import React, { useState, useRef } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, FlatList, KeyboardAvoidingView, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { supabase } from '../../config/supabase';
import NutritionMessageBubble from './NutritionMessageBubble';

const QUICK_QUESTIONS = [
  'Quanta proteína devo comer por dia?',
  'O que comer antes do treino?',
  'Como calcular minhas calorias?',
  'Melhores alimentos para ganhar massa',
];

export default function NutritionCoach({ userId, userWeight = 70, userGoal = 'manter' }) {
  const [messages, setMessages] = useState([
    { id: 'welcome', text: 'Olá! Sou seu assistente de nutrição. Como posso ajudar?', isUser: false },
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const flatListRef = useRef(null);

  const handleSend = async (text) => {
    const msg = (text || input).trim();
    if (!msg || loading) return;

    setInput('');
    const userMsg = { id: Date.now().toString(), text: msg, isUser: true };
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);

    try {
      const apiKey = process.env.EXPO_PUBLIC_GEMINI_API_KEY || '';
      let reply;

      if (apiKey) {
        const prompt = `Você é um nutricionista IA do NOVAIX Fitness. Responda em português, de forma direta e prática. Máximo 3 parágrafos. Contexto: usuário tem ${userWeight}kg, objetivo: ${userGoal}. Pergunta: ${msg}`;

        const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`;
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: prompt }] }] }),
        });

        const result = await response.json();
        reply = result.candidates?.[0]?.content?.parts?.[0]?.text;
      }

      if (!reply) {
        const lower = msg.toLowerCase();
        if (lower.includes('proteína') || lower.includes('protein')) {
          reply = `Com ${userWeight}kg, seu ideal é ${(userWeight * 1.8).toFixed(0)}-${(userWeight * 2.2).toFixed(0)}g de proteína por dia. Divida em 3-4 refeições. Boas fontes: frango, ovos, peixe, whey.`;
        } else if (lower.includes('treino') || lower.includes('pré')) {
          reply = 'Pré-treino: coma carboidratos complexos (banana, aveia) 1-2h antes. Pós-treino: proteína + carboidrato dentro de 2h para recuperação.';
        } else if (lower.includes('caloria') || lower.includes('calorias')) {
          reply = `TDEE estimado: ~${Math.round(userWeight * 33)} kcal/dia. Para ${userGoal === 'emagrecer' ? 'emagrecer, reduza 300-500 kcal' : userGoal === 'ganhar' ? 'ganhar massa, aumente 300-500 kcal' : 'manter, mantenha estável'}.`;
        } else {
          reply = `Baseado no seu perfil (${userWeight}kg, ${userGoal}): foque em proteína em cada refeição, beba 2.5L de água, e durma 7-9h. Qual sua dúvida específica?`;
        }
      }

      const aiMsg = { id: (Date.now() + 1).toString(), text: reply, isUser: false };
      setMessages(prev => [...prev, aiMsg]);
    } catch (err) {
      const errorMsg = { id: (Date.now() + 1).toString(), text: 'Desculpe, não consegui processar sua pergunta. Tente novamente.', isUser: false };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView style={styles.container} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
      <View style={styles.header}>
        <Ionicons name="nutrition" size={18} color={COLORS.primary} />
        <Text style={styles.title}>COACH DE NUTRIÇÃO</Text>
      </View>

      <FlatList
          removeClippedSubviews={true}
          maxToRenderPerBatch={10}
          windowSize={5}
        ref={flatListRef}
        data={messages}
        keyExtractor={item => item.id}
        renderItem={({ item }) => <NutritionMessageBubble message={item} />}
        contentContainerStyle={styles.list}
        onContentSizeChange={() => flatListRef.current?.scrollToEnd({ animated: true })}
      />

      {messages.length <= 1 && (
        <View style={styles.quickRow}>
          {QUICK_QUESTIONS.map((q, i) => (
            <TouchableOpacity key={i} style={styles.quickBtn} onPress={() => handleSend(q)}>
              <Text style={styles.quickText}>{q}</Text>
            </TouchableOpacity>
          ))}
        </View>
      )}

      <View style={styles.inputRow}>
        <TextInput
          style={styles.input}
          value={input}
          onChangeText={setInput}
          placeholder="Pergunte sobre nutrição..."
          placeholderTextColor={COLORS.textMuted}
        />
        <TouchableOpacity style={[styles.sendBtn, !input.trim() && styles.sendBtnDisabled]} onPress={() => handleSend()} disabled={!input.trim() || loading}>
          <Ionicons name={loading ? 'sync' : 'send'} size={18} color={COLORS.background} />
        </TouchableOpacity>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, borderWidth: 1, borderColor: COLORS.border, overflow: 'hidden' },
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, padding: SPACING.lg, borderBottomWidth: 1, borderBottomColor: COLORS.border },
  title: { fontFamily: 'Montserrat_700Bold', fontSize: 12, color: COLORS.textMuted, letterSpacing: 1 },
  list: { padding: SPACING.md, gap: SPACING.sm, minHeight: 200 },
  bubble: { flexDirection: 'row', gap: SPACING.sm, maxWidth: '85%' },
  bubbleUser: { alignSelf: 'flex-end', flexDirection: 'row-reverse' },
  bubbleAI: { alignSelf: 'flex-start' },
  aiAvatar: { width: 28, height: 28, borderRadius: 14, backgroundColor: COLORS.primary + '20', justifyContent: 'center', alignItems: 'center' },
  bubbleContent: { paddingHorizontal: SPACING.md, paddingVertical: SPACING.sm, borderRadius: BORDER_RADIUS.md },
  bubbleContentUser: { backgroundColor: COLORS.primary },
  bubbleContentAI: { backgroundColor: COLORS.background },
  bubbleText: { fontFamily: 'Inter_400Regular', fontSize: 13, color: COLORS.textTitle, lineHeight: 18 },
  bubbleTextUser: { color: COLORS.background },
  quickRow: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.xs, paddingHorizontal: SPACING.md, paddingBottom: SPACING.sm },
  quickBtn: { paddingHorizontal: SPACING.sm, paddingVertical: SPACING.xs, backgroundColor: COLORS.background, borderRadius: BORDER_RADIUS.full, borderWidth: 1, borderColor: COLORS.border },
  quickText: { fontFamily: 'Inter_400Regular', fontSize: 10, color: COLORS.textMuted },
  inputRow: { flexDirection: 'row', gap: SPACING.sm, padding: SPACING.md, borderTopWidth: 1, borderTopColor: COLORS.border },
  input: { flex: 1, height: 40, backgroundColor: COLORS.background, borderRadius: BORDER_RADIUS.md, paddingHorizontal: SPACING.md, color: COLORS.textTitle, fontFamily: 'Inter_400Regular', fontSize: 14 },
  sendBtn: { width: 40, height: 40, borderRadius: 20, backgroundColor: COLORS.primary, justifyContent: 'center', alignItems: 'center' },
  sendBtnDisabled: { opacity: 0.5 },
});

// src/components/nutrition/NutritionReports.js
// Relatórios de nutrição - NOVAIX FITNESS

import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { getMealLogs, getDailySummary } from '../../services/mealAnalyzer';

const REPORT_TYPES = [
  { id: 'daily', title: 'Relatório Diário', icon: 'calendar', color: COLORS.primary, desc: 'Resumo de hoje' },
  { id: 'weekly', title: 'Relatório Semanal', icon: 'bar-chart', color: COLORS.success, desc: 'Últimos 7 dias' },
  { id: 'monthly', title: 'Relatório Mensal', icon: 'trending-up', color: COLORS.info, desc: 'Últimos 30 dias' },
];

function formatDate(date: any) {
  return new Date(date).toLocaleDateString('pt-BR');
}

function generateReportHTML(type, data: any) {
  const title = type === 'daily' ? 'Diário' : type === 'weekly' ? 'Semanal' : 'Mensal';

  const mealsHTML = data.meals.map(m => `
    <tr>
      <td>${formatDate(m.logged_at)}</td>
      <td>${m.description || 'Refeição'}</td>
      <td>${m.calories || 0} kcal</td>
      <td>${m.protein || 0}g</td>
      <td>${m.carbs || 0}g</td>
      <td>${m.fat || 0}g</td>
    </tr>
  `).join('');

  return `
    <!DOCTYPE html>
    <html><head><meta charset="utf-8"><style>
      body { font-family: Arial, sans-serif; padding: 20px; color: #333; }
      h1 { color: #CCFF00; background: #12161A; padding: 15px; text-align: center; border-radius: 8px; }
      h2 { color: #12161A; margin-top: 20px; }
      .summary { background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 20px; }
      .stat { display: inline-block; text-align: center; padding: 10px 20px; margin: 5px; background: white; border-radius: 8px; border: 1px solid #eee; }
      .statValue { font-size: 24px; font-weight: bold; color: #CCFF00; }
      .statLabel { font-size: 11px; color: #666; }
      table { width: 100%; border-collapse: collapse; margin-top: 10px; }
      th { background: #12161A; color: white; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 12px; }
      .footer { text-align: center; color: #999; margin-top: 30px; font-size: 11px; }
    </style></head><body>
      <h1>📊 RELATÓRIO DE NUTRIÇÃO ${title.toUpperCase()}</h1>
      <div class="summary">
        <div class="stat"><div class="statValue">${data.totalMeals}</div><div class="statLabel">Refeições</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.totalCalories)}</div><div class="statLabel">kcal Totais</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.avgCalories)}</div><div class="statLabel">kcal Média/Dia</div></div>
        <div class="stat"><div class="statValue">${Math.round(data.avgProtein)}g</div><div class="statLabel">Proteína Média</div></div>
      </div>
      <h2>Detalhes das Refeições</h2>
      <table>
        <tr><th>Data</th><th>Refeição</th><th>Calorias</th><th>Proteína</th><th>Carbos</th><th>Gordura</th></tr>
        ${mealsHTML}
      </table>
      <p class="footer">Gerado por NOVAIX Fitness • ${formatDate(new Date())}</p>
    </body></html>
  `;
}

export default function NutritionReports({ userId }) {
  const [loading, setLoading] = useState(false);

  const generateReport = async (type) => {
    setLoading(true);
    try {
      const now = new Date();
      let startDate;

      if (type === 'daily') {
        startDate = new Date(now);
        startDate.setHours(0, 0, 0, 0);
      } else if (type === 'weekly') {
        startDate = new Date(now.getTime() - 7 * 86400000);
      } else {
        startDate = new Date(now.getTime() - 30 * 86400000);
      }

      const allLogs = await getMealLogs(userId);
      const filtered = allLogs.filter(l => new Date(l.logged_at) >= startDate);

      const data = {
        meals: filtered,
        totalMeals: filtered.length,
        totalCalories: filtered.reduce((s, m) => s + (m.calories || 0), 0),
        avgCalories: filtered.length > 0 ? filtered.reduce((s, m) => s + (m.calories || 0), 0) / (type === 'daily' ? 1 : type === 'weekly' ? 7 : 30) : 0,
        avgProtein: filtered.length > 0 ? filtered.reduce((s, m) => s + (m.protein || 0), 0) / (type === 'daily' ? 1 : type === 'weekly' ? 7 : 30) : 0,
      };

      const html = generateReportHTML(type, data);
      const { uri } = await Print.printToFileAsync({ html, base64: false });
      await Sharing.shareAsync(uri, { mimeType: 'application/pdf', dialogTitle: `Relatório ${type}` });
    } catch (err) {
      console.error('Erro ao gerar relatório:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="document-text" size={18} color={COLORS.primary} />
        <Text style={styles.title}>RELATÓRIOS</Text>
      </View>

      <View style={styles.list}>
        {REPORT_TYPES.map(report => (
          <TouchableOpacity key={report.id} style={styles.reportCard} onPress={() => generateReport(report.id)} disabled={loading}>
            <View style={[styles.reportIcon, { backgroundColor: report.color + '20' }]}>
              <Ionicons name={report.icon} size={20} color={report.color} />
            </View>
            <View style={styles.reportInfo}>
              <Text style={styles.reportTitle}>{report.title}</Text>
              <Text style={styles.reportDesc}>{report.desc}</Text>
            </View>
            <Ionicons name="download-outline" size={20} color={COLORS.textMuted} />
          </TouchableOpacity>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.lg, borderWidth: 1, borderColor: COLORS.border },
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, marginBottom: SPACING.md },
  title: { fontFamily: 'Montserrat_700Bold', fontSize: 12, color: COLORS.textMuted, letterSpacing: 1 },
  list: { gap: SPACING.sm },
  reportCard: { flexDirection: 'row', alignItems: 'center', gap: SPACING.md, padding: SPACING.md, backgroundColor: COLORS.background, borderRadius: BORDER_RADIUS.sm },
  reportIcon: { width: 40, height: 40, borderRadius: 20, justifyContent: 'center', alignItems: 'center' },
  reportInfo: { flex: 1 },
  reportTitle: { fontFamily: 'Montserrat_600SemiBold', fontSize: 13, color: COLORS.textTitle },
  reportDesc: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted },
});

// src/components/nutrition/NutritionStreak.js
// Sequência de dias atingindo metas - NOVAIX FITNESS

import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { supabase } from '../../config/supabase';
import NutritionProgress from './NutritionProgress';

const STREAK_BADGES = [
  { days: 3, label: 'Iniciante', icon: 'flame', color: COLORS.attention },
  { days: 7, label: 'Consistente', icon: 'flame', color: COLORS.secondary },
  { days: 14, label: 'Dedicado', icon: 'flame', color: COLORS.primary },
  { days: 30, label: 'Mestre', icon: 'trophy', color: COLORS.success },
  { days: 60, label: 'Lenda', icon: 'star', color: COLORS.primary },
];

export default function NutritionStreak({ userId }) {
  const [currentStreak, setCurrentStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [weekDots, setWeekDots] = useState([]);

  useEffect(() => { loadStreak(); }, [userId]);

  const loadStreak = async () => {
    if (!userId) return;
    try {
      const logs = await supabase.from('meal_logs')
        .select('logged_at')
        .eq('user_id', userId)
        .order('logged_at', { ascending: false })
        .limit(60);

      if (!logs.data || logs.data.length === 0) return;

      const uniqueDays = [...new Set(logs.data.map(l => new Date(l.logged_at).toDateString()))];

      let streak = 0;
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      for (let i = 0; i < 60; i++) {
        const checkDate = new Date(today);
        checkDate.setDate(checkDate.getDate() - i);
        if (uniqueDays.includes(checkDate.toDateString())) {
          streak++;
        } else if (i > 0) {
          break;
        }
      }

      setCurrentStreak(streak);

      let best = 0;
      let current = 0;
      for (let i = uniqueDays.length - 1; i >= 0; i--) {
        if (i === uniqueDays.length - 1) {
          current = 1;
        } else {
          const curr = new Date(uniqueDays[i]);
          const prev = new Date(uniqueDays[i + 1]);
          const diff = (prev - curr) / 86400000;
          if (diff === 1) {
            current++;
          } else {
            best = Math.max(best, current);
            current = 1;
          }
        }
      }
      best = Math.max(best, current);
      setBestStreak(best);

      const last7 = [];
      for (let i = 6; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        last7.push({
          day: d.toLocaleDateString('pt-BR', { weekday: 'short' }),
          active: uniqueDays.includes(d.toDateString()),
          isToday: i === 0,
        });
      }
      setWeekDots(last7);
    } catch (err) {
      console.error('Erro ao carregar streak:', err);
    }
  };

  const currentBadge = STREAK_BADGES.slice().reverse().find(b => currentStreak >= b.days);
  const nextBadge = STREAK_BADGES.find(b => currentStreak < b.days);
  const progressToNext = nextBadge ? (currentStreak / nextBadge.days) * 100 : 100;

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Ionicons name="flame" size={18} color={COLORS.primary} />
        <Text style={styles.title}>SEQUÊNCIA</Text>
      </View>

      <View style={styles.streakCard}>
        <View style={styles.streakMain}>
          {currentBadge && (
            <View style={[styles.badgeIcon, { backgroundColor: currentBadge.color + '20' }]}>
              <Ionicons name={currentBadge.icon} size={28} color={currentBadge.color} />
            </View>
          )}
          <View style={styles.streakInfo}>
            <Text style={styles.streakNumber}>{currentStreak}</Text>
            <Text style={styles.streakLabel}>dias seguidos</Text>
            {currentBadge && (
              <View style={[styles.badgeTag, { backgroundColor: currentBadge.color + '20' }]}>
                <Text style={[styles.badgeText, { color: currentBadge.color }]}>{currentBadge.label}</Text>
              </View>
            )}
          </View>
        </View>

        <View style={styles.statsRow}>
          <View style={styles.statItem}>
            <Text style={styles.statValue}>{bestStreak}</Text>
            <Text style={styles.statLabel}>Recorde</Text>
          </View>
          <View style={styles.statDivider} />
          <View style={styles.statItem}>
            <Text style={[styles.statValue, { color: COLORS.primary }]}>{currentStreak}</Text>
            <Text style={styles.statLabel}>Atual</Text>
          </View>
        </View>
      </View>

      <View style={styles.weekRow}>
        {weekDots.map((d, i) => (
          <View key={i} style={styles.dayCol}>
            <Text style={[styles.dayLabel, d.isToday && styles.dayLabelToday]}>{d.day}</Text>
            <View style={[styles.dayDot, d.active && styles.dayDotActive, d.isToday && styles.dayDotToday]} />
          </View>
        ))}
      </View>

      {nextBadge && <NutritionProgress streak={currentStreak} nextBadge={nextBadge} />}
    </View>
  );
}

