import { SPACING, BORDER_RADIUS } from '../../constants/spacing';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const PHOTO_SIZE = (SCREEN_WIDTH - SPACING.xl * 2 - SPACING.sm * 2) / 3;

interface Photo {
  id: string;
  image_url: string;
  recorded_at: string;
}

interface PhotoItemProps {
  photo: Photo;
  selected: boolean;
  onPress: (photo: Photo) => void;
  onLongPress?: (photo: Photo) => void;
  index: number;
}

function formatDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
}

function PhotoItem({ photo, selected, onPress, onLongPress, index }: PhotoItemProps): React.JSX.Element {
  const [] = useState(() => new Animated.Value());
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    Animated.parallel([
      Animated.spring(scaleAnim, { toValue: 1, tension: 30, friction: 8, delay: index * 50, useNativeDriver: true }),
      Animated.timing(fadeAnim, { toValue: 1, duration: 200, delay: index * 50, useNativeDriver: true }),
    ]).start();
  }, []);

  return (
    <Animated.View style={{ opacity: fadeAnim, transform: [{ scale: scaleAnim }] }}>
      <TouchableOpacity
        style={[styles.item, selected && styles.itemSelected]}
        onPress={() => onPress(photo)}
        onLongPress={() => onLongPress?.(photo)}
        activeOpacity={0.8}
      >
        <Image source={{ uri: photo.image_url }} style={styles.thumb} />
        <View style={styles.dateOverlay}>
          <Text style={styles.dateText}>{formatDate(photo.recorded_at)}</Text>
        </View>
        {selected && (
          <View style={styles.checkBadge}>
            <Ionicons name="checkmark-circle" size={22} color={COLORS.primary} />
          </View>
        )}
      </TouchableOpacity>
    </Animated.View>
  );
}

interface PhotoGridProps {
  photos: Photo[];
  selectedIds?: Photo[];
  onSelect: (photo: Photo) => void;
  onLongPress?: (photo: Photo) => void;
  compareMode?: boolean;
}

function PhotoGrid({ photos, selectedIds, onSelect, onLongPress, compareMode }: PhotoGridProps): React.JSX.Element {
  if (photos.length === 0) {
    return (
      <View style={styles.empty}>
        <View style={styles.emptyIcon}>
          <Ionicons name="camera-outline" size={40} color={COLORS.textMuted} />
        </View>
        <Text style={styles.emptyTitle}>Nenhuma foto</Text>
        <Text style={styles.emptyText}>Adicione fotos para acompanhar seu progresso</Text>
      </View>
    );
  }

  return (
    <View style={styles.grid}>
      {photos.map((photo: Photo, i: number) => (
        <PhotoItem
          key={photo.id}
          photo={photo}
          selected={selectedIds?.some((p: Photo) => p.id === photo.id) || false}
          onPress={onSelect}
          onLongPress={onLongPress}
          index={i}
        />
      ))}
    </View>
  );
}

export default memo(PhotoGrid);

const styles = StyleSheet.create({
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.sm },
  empty: { alignItems: 'center', paddingVertical: SPACING.xxxl, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, borderWidth: 1, borderColor: COLORS.border },
  emptyIcon: { width: 72, height: 72, borderRadius: 36, backgroundColor: COLORS.surfaceOverlay, justifyContent: 'center', alignItems: 'center', marginBottom: SPACING.md },
  emptyTitle: { fontFamily: 'Montserrat_600SemiBold', fontSize: 16, color: COLORS.textTitle },
  emptyText: { fontFamily: 'Inter_400Regular', fontSize: 13, color: COLORS.textMuted, marginTop: SPACING.xs },
  item: { width: PHOTO_SIZE, borderRadius: 8, overflow: 'hidden' },
  itemSelected: { borderWidth: 2, borderColor: COLORS.primary },
  thumb: { width: PHOTO_SIZE, height: PHOTO_SIZE * 1.33, backgroundColor: COLORS.surface },
  dateOverlay: { position: 'absolute', bottom: 0, left: 0, right: 0, backgroundColor: 'rgba(0,0,0,0.6)', paddingVertical: 4, paddingHorizontal: SPACING.xs },
  dateText: { fontFamily: 'Inter_400Regular', fontSize: 10, color: COLORS.background, textAlign: 'center' },
  checkBadge: { position: 'absolute', top: SPACING.xs, right: SPACING.xs },
});

import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, Alert, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { typography } from '../../styles';
import { MeasurementForm, BMICard, MeasurementChart, MeasurementHistory } from '../index';
import { saveMeasurement, getMeasurements, getLatestMeasurement, getMeasurementHistory, deleteMeasurement, calculateBMI, getBMICategory } from '../../services/body-measurements';
import { supabase } from '../../config/supabase';

interface Form {
  weight: string;
  chest: string;
  waist: string;
  hips: string;
  arms: string;
  thighs: string;
  body_fat: string;
  notes: string;
}

interface Measurement {
  id?: string;
  weight?: number;
  [key: string]: any;
}

interface ProgressMeasurementsProps {
  userId?: string;
}

export default function ProgressMeasurements({ userId }: ProgressMeasurementsProps): React.JSX.Element {
  const [latest, setLatest] = useState<Measurement | null>(null);
  const [history, setHistory] = useState<Measurement[]>([]);
  const [showForm, setShowForm] = useState<boolean>(false);
  const [selectedChart, setSelectedChart] = useState<string>('weight');
  const [chartData, setChartData] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [form, setForm] = useState<Form>({ weight: '', chest: '', waist: '', hips: '', arms: '', thighs: '', body_fat: '', notes: '' });
  const [physicalData, setPhysicalData] = useState<any>({});

  useEffect(() => {
    async function load(): Promise<void> {
      if (!userId) return;
      try {
        const [lat, hist, profile] = await Promise.all([
          getLatestMeasurement(userId),
          getMeasurements(userId),
          supabase.from('profiles').select('physical_data, onboarding').eq('id', userId).single(),
        ]);
        setLatest(lat);
        setHistory(hist);
        setPhysicalData(profile.data?.physical_data || profile.data?.onboarding || {});
      } catch (err) {
        if (__DEV__) console.error('Erro ao carregar:', err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [userId]);

  useEffect(() => {
    async function loadChart(): Promise<void> {
      if (!userId) return;
      const data = await getMeasurementHistory(userId, selectedChart);
      setChartData(data);
    }
    loadChart();
  }, [userId, selectedChart]);

  const handleSave = async (): Promise<void> => {
    setSaving(true);
    try {
      const measurement: any = {};
      Object.entries(form).forEach(([key, val]: [string, string]) => {
        if (val && key !== 'notes') measurement[key] = parseFloat(val.replace(',', '.'));
      });
      measurement.notes = form.notes;
      if (Object.keys(measurement).filter((k: string) => k !== 'notes').length === 0) {
        Alert.alert('Erro', 'Preencha pelo menos uma medida.'); return;
      }
      await saveMeasurement(userId, measurement);
      Alert.alert('Sucesso', 'Medidas salvas!');
      setShowForm(false);
      setForm({ weight: '', chest: '', waist: '', hips: '', arms: '', thighs: '', body_fat: '', notes: '' });
      const [lat, hist] = await Promise.all([getLatestMeasurement(userId), getMeasurements(userId)]);
      setLatest(lat); setHistory(hist);
    } catch { Alert.alert('Erro', 'Nao foi possivel salvar.'); }
    finally { setSaving(false); }
  };

  const handleDelete = (id: string): void => {
    Alert.alert('Deletar', 'Remover esta medição?', [
      { text: 'Cancelar', style: 'cancel' },
      { text: 'Deletar', style: 'destructive', onPress: async () => {
        await deleteMeasurement(id, userId);
        setHistory(await getMeasurements(userId));
      }},
    ]);
  };

  const bmi = calculateBMI(latest?.weight, physicalData?.height);
  const bmiCategory = getBMICategory(bmi);

  return (
    <View>
      <View style={styles.header}>
        <Text style={typography.label}>MEDIDAS CORPORAIS</Text>
        <TouchableOpacity onPress={() => setShowForm(!showForm)}>
          <Ionicons name={showForm ? 'close' : 'add'} size={24} color={COLORS.primary} />
        </TouchableOpacity>
      </View>

      {showForm ? (
        <MeasurementForm form={form} onChangeForm={setForm} onSave={handleSave} saving={saving} />
      ) : latest ? (
        <>
          <BMICard bmi={bmi} bmiCategory={bmiCategory} latest={latest} />
          <MeasurementChart selectedChart={selectedChart} onSelectChart={setSelectedChart} chartData={chartData} />
        </>
      ) : (
        <View style={styles.emptyCard}>
          <Ionicons name="body-outline" size={48} color={COLORS.textMuted} />
          <Text style={typography.h5}>Nenhuma medida registrada</Text>
          <Text style={typography.bodyMuted}>Adicione suas primeiras medidas</Text>
        </View>
      )}

      <MeasurementHistory history={history} onDelete={handleDelete} />
    </View>
  );
}

const styles = StyleSheet.create({
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: SPACING.md },
  emptyCard: { alignItems: 'center', paddingVertical: SPACING.xl * 2, gap: SPACING.md, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, marginBottom: SPACING.xl, borderWidth: 1, borderColor: COLORS.border },
});

