// Challenge a Friend - User search, challenge type, duration, stakes

import { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Modal, ScrollView, TextInput, Image, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';

interface Friend {
  id: string;
  name: string;
  avatar: string;
  xp: number;
}

interface ChallengeFriendProps {
  visible: boolean;
  onClose: () => void;
  onSendChallenge: (challenge: ChallengeData) => void;
  currentUserId: string;
  friends: Friend[];
}

interface ChallengeData {
  friendId: string;
  friendName: string;
  type: 'reps' | 'duration' | 'distance';
  duration: '1day' | '3days' | '1week';
  stake: number;
  workoutName?: string;
}

const CHALLENGE_TYPES = [
  { key: 'reps', label: 'Repetições', icon: 'repeat', color: COLORS.primary },
  { key: 'duration', label: 'Duração', icon: 'time', color: COLORS.info },
  { key: 'distance', label: 'Distância', icon: 'navigate', color: COLORS.success },
];

const DURATION_OPTIONS = [
  { key: '1day', label: '1 Dia', icon: 'calendar' },
  { key: '3days', label: '3 Dias', icon: 'calendar' },
  { key: '1week', label: '1 Semana', icon: 'calendar' },
];

const STAKE_OPTIONS = [0, 10, 25, 50, 100];

export default function ChallengeFriend({ visible, onClose, onSendChallenge, currentUserId, friends }: ChallengeFriendProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedFriend, setSelectedFriend] = useState<Friend | null>(null);
  const [challengeType, setChallengeType] = useState<'reps' | 'duration' | 'distance'>('reps');
  const [duration, setDuration] = useState<'1day' | '3days' | '1week'>('3days');
  const [stake, setStake] = useState(0);
  const [step, setStep] = useState(1); // 1: select friend, 2: configure challenge, 3: confirm
  const slideAnim = useState(new Animated.Value(300))[0];

  useEffect(() => {
    if (visible) {
      Animated.spring(slideAnim, { toValue: 0, tension: 30, friction: 8, useNativeDriver: true }).start();
    } else {
      slideAnim.setValue(300);
    }
  }, [visible]);

  const filteredFriends = friends.filter(f =>
    f.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSendChallenge = () => {
    if (!selectedFriend) return;

    onSendChallenge({
      friendId: selectedFriend.id,
      friendName: selectedFriend.name,
      type: challengeType,
      duration,
      stake,
    });

    handleClose();
  };

  const handleClose = () => {
    setSelectedFriend(null);
    setSearchQuery('');
    setChallengeType('reps');
    setDuration('3days');
    setStake(0);
    setStep(1);
    onClose();
  };

  const renderStep1 = () => (
    <View style={styles.stepContainer}>
      <Text style={styles.stepTitle}>Escolha um Amigo</Text>
      <Text style={styles.stepSubtitle}>Quem você quer desafiar?</Text>

      <View style={styles.searchContainer}>
        <Ionicons name="search" size={18} color={COLORS.textMuted} />
        <TextInput
          style={styles.searchInput}
          placeholder="Buscar amigo..."
          placeholderTextColor={COLORS.textMuted}
          value={searchQuery}
          onChangeText={setSearchQuery}
        />
      </View>

      <ScrollView style={styles.friendsList} showsVerticalScrollIndicator={false}>
        {filteredFriends.map(friend => (
          <TouchableOpacity
            key={friend.id}
            style={[styles.friendItem, selectedFriend?.id === friend.id && styles.friendItemSelected]}
            onPress={() => {
              setSelectedFriend(friend);
              setStep(2);
            }}
          >
            <Image source={{ uri: friend.avatar }} style={styles.friendAvatar} />
            <View style={styles.friendInfo}>
              <Text style={styles.friendName}>{friend.name}</Text>
              <Text style={styles.friendXP}>{friend.xp} XP</Text>
            </View>
            <Ionicons name="chevron-forward" size={18} color={COLORS.textMuted} />
          </TouchableOpacity>
        ))}
      </ScrollView>
    </View>
  );

  const renderStep2 = () => (
    <View style={styles.stepContainer}>
      <Text style={styles.stepTitle}>Configure o Desafio</Text>
      <Text style={styles.stepSubtitle}>Desafiando {selectedFriend?.name}</Text>

      {/* Challenge Type */}
      <Text style={styles.sectionLabel}>Tipo de Desafio</Text>
      <View style={styles.typeGrid}>
        {CHALLENGE_TYPES.map(type => (
          <TouchableOpacity
            key={type.key}
            style={[styles.typeCard, challengeType === type.key && styles.typeCardSelected]}
            onPress={() => setChallengeType(type.key as any)}
          >
            <View style={[styles.typeIcon, { backgroundColor: type.color + '20' }]}>
              <Ionicons name={type.icon as any} size={24} color={type.color} />
            </View>
            <Text style={[styles.typeLabel, challengeType === type.key && styles.typeLabelSelected]}>
              {type.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Duration */}
      <Text style={styles.sectionLabel}>Duração</Text>
      <View style={styles.durationRow}>
        {DURATION_OPTIONS.map(option => (
          <TouchableOpacity
            key={option.key}
            style={[styles.durationBtn, duration === option.key && styles.durationBtnSelected]}
            onPress={() => setDuration(option.key as any)}
          >
            <Ionicons name={option.icon as any} size={16} color={duration === option.key ? COLORS.background : COLORS.textMuted} />
            <Text style={[styles.durationText, duration === option.key && styles.durationTextSelected]}>
              {option.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Stakes */}
      <Text style={styles.sectionLabel}>Apostar XP (Opcional)</Text>
      <View style={styles.stakeRow}>
        {STAKE_OPTIONS.map(amount => (
          <TouchableOpacity
            key={amount}
            style={[styles.stakeBtn, stake === amount && styles.stakeBtnSelected]}
            onPress={() => setStake(amount)}
          >
            <Text style={[styles.stakeText, stake === amount && styles.stakeTextSelected]}>
              {amount === 0 ? 'Nenhum' : `${amount} XP`}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Navigation */}
      <View style={styles.navRow}>
        <TouchableOpacity style={styles.backBtn} onPress={() => setStep(1)}>
          <Ionicons name="arrow-back" size={18} color={COLORS.textMuted} />
          <Text style={styles.backBtnText}>Voltar</Text>
        </TouchableOpacity>
        <TouchableOpacity style={styles.nextBtn} onPress={() => setStep(3)}>
          <Text style={styles.nextBtnText}>Continuar</Text>
          <Ionicons name="arrow-forward" size={18} color={COLORS.background} />
        </TouchableOpacity>
      </View>
    </View>
  );

  const renderStep3 = () => (
    <View style={styles.stepContainer}>
      <Text style={styles.stepTitle}>Confirmar Desafio</Text>

      <View style={styles.confirmCard}>
        <Image source={{ uri: selectedFriend?.avatar }} style={styles.confirmAvatar} />
        <Text style={styles.confirmFriendName}>{selectedFriend?.name}</Text>

        <View style={styles.confirmDetails}>
          <View style={styles.confirmRow}>
            <Ionicons name={CHALLENGE_TYPES.find(t => t.key === challengeType)?.icon as any} size={20} color={COLORS.primary} />
            <Text style={styles.confirmLabel}>Tipo:</Text>
            <Text style={styles.confirmValue}>{CHALLENGE_TYPES.find(t => t.key === challengeType)?.label}</Text>
          </View>
          <View style={styles.confirmRow}>
            <Ionicons name="time" size={20} color={COLORS.info} />
            <Text style={styles.confirmLabel}>Duração:</Text>
            <Text style={styles.confirmValue}>{DURATION_OPTIONS.find(d => d.key === duration)?.label}</Text>
          </View>
          {stake > 0 && (
            <View style={styles.confirmRow}>
              <Ionicons name="trophy" size={20} color={COLORS.attention} />
              <Text style={styles.confirmLabel}>Aposta:</Text>
              <Text style={styles.confirmValue}>{stake} XP</Text>
            </View>
          )}
        </View>
      </View>

      <View style={styles.navRow}>
        <TouchableOpacity style={styles.backBtn} onPress={() => setStep(2)}>
          <Ionicons name="arrow-back" size={18} color={COLORS.textMuted} />
          <Text style={styles.backBtnText}>Voltar</Text>
        </TouchableOpacity>
        <TouchableOpacity style={styles.sendBtn} onPress={handleSendChallenge}>
          <Ionicons name="send" size={18} color={COLORS.background} />
          <Text style={styles.sendBtnText}>ENVIAR DESAFIO</Text>
        </TouchableOpacity>
      </View>
    </View>
  );

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={handleClose}>
      <TouchableOpacity style={styles.overlay} activeOpacity={1} onPress={handleClose}>
        <Animated.View
          style={[styles.content, { transform: [{ translateY: slideAnim }] }]}
          onStartShouldSetResponder={() => true}
        >
          <View style={styles.handle} />

          {/* Progress Steps */}
          <View style={styles.progressSteps}>
            {[1, 2, 3].map(s => (
              <View key={s} style={[styles.stepDot, step >= s && styles.stepDotActive]} />
            ))}
          </View>

          {step === 1 && renderStep1()}
          {step === 2 && renderStep2()}
          {step === 3 && renderStep3()}
        </Animated.View>
      </TouchableOpacity>
    </Modal>
  );
}

