  { key: 'all', label: 'Todos', icon: 'globe' },
  { key: 'global', label: 'Global', icon: 'planet' },
];

const RANK_COLORS = {
  1: COLORS.gold,
  2: COLORS.textMuted,
  3: COLORS.bronze,
};

export default function LiveLeaderboard({
  entries,
  currentUserId,
  onRefresh,
  filter = 'all',
  onFilterChange,
}: LiveLeaderboardProps) {
  const [refreshing, setRefreshing] = useState(false);
  const [selectedFilter, setSelectedFilter] = useState(filter);
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    setSelectedFilter(filter);
  }, [filter]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    await onRefresh();
    setRefreshing(false);
  }, [onRefresh]);

  const handleFilterChange = useCallback((newFilter: 'friends' | 'all' | 'global') => {
    Animated.sequence([
      Animated.timing(fadeAnim, { toValue: 0, duration: 150, useNativeDriver: true }),
      Animated.timing(fadeAnim, { toValue: 1, duration: 150, useNativeDriver: true }),
    ]).start();

    setSelectedFilter(newFilter);
    onFilterChange?.(newFilter);
  }, [onFilterChange, fadeAnim]);

  const getRankIcon = (rank: number) => {
    if (rank === 1) return 'trophy';
    if (rank === 2) return 'medal';
    if (rank === 3) return 'ribbon';
    return null;
  };

  const getRankStyle = (rank: number) => {
    const color = RANK_COLORS[rank as keyof typeof RANK_COLORS];
    return color ? { backgroundColor: color + '20', borderColor: color } : {};
  };

  const renderEntry = useCallback(({ item, index }: { item: LeaderboardEntry; index: number }) => {
    const isCurrentUser = item.userId === currentUserId;
    const rankIcon = getRankIcon(item.rank);
    const rankColor = RANK_COLORS[item.rank as keyof typeof RANK_COLORS] || COLORS.textMuted;

    return (
      <Animated.View
        style={[
          styles.entry,
          isCurrentUser && styles.entryCurrentUser,
          getRankStyle(item.rank),
        ]}
      >
        {/* Rank */}
        <View style={styles.rankContainer}>
          {rankIcon ? (
            <Ionicons name={rankIcon as any} size={20} color={rankColor} />
          ) : (
            <Text style={styles.rankNumber}>{item.rank}</Text>
          )}
        </View>

        {/* Avatar */}
        <Image
          source={{ uri: item.userAvatar }}
          style={[styles.avatar, item.rank <= 3 && styles.avatarTopThree]}
        />

        {/* Info */}
        <View style={styles.info}>
          <Text style={[styles.userName, isCurrentUser && styles.userNameCurrentUser]} numberOfLines={1}>
            {item.userName}
            {isCurrentUser && ' (Você)'}
          </Text>
          <View style={styles.statsRow}>
            <View style={styles.stat}>
              <Ionicons name="flash" size={12} color={COLORS.primary} />
              <Text style={styles.statValue}>{item.xp.toLocaleString()} XP</Text>
            </View>
            <View style={styles.stat}>
              <Ionicons name="barbell" size={12} color={COLORS.secondary} />
              <Text style={styles.statValue}>{item.workouts}</Text>
            </View>
          </View>
        </View>

        {/* Rank Change Indicator */}
        {item.previousRank !== undefined && item.previousRank !== item.rank && (
          <View style={styles.rankChange}>
            <Ionicons
              name={item.rank < item.previousRank ? 'arrow-up' : 'arrow-down'}
              size={14}
              color={item.rank < item.previousRank ? COLORS.success : COLORS.error}
            />
            <Text style={[
              styles.rankChangeText,
              { color: item.rank < item.previousRank ? COLORS.success : COLORS.error },
            ]}>
              {Math.abs(item.rank - item.previousRank)}
            </Text>
          </View>
        )}
      </Animated.View>
    );
  }, [currentUserId]);

  const keyExtractor = useCallback((item: LeaderboardEntry) => item.id, []);

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <Ionicons name="trophy" size={20} color={COLORS.primary} />
          <Text style={styles.title}>RANKING AO VIVO</Text>
        </View>
        <View style={styles.liveIndicator}>
          <View style={styles.liveDot} />
          <Text style={styles.liveText}>AO VIVO</Text>
        </View>
      </View>

      {/* Filter Tabs */}
      <View style={styles.filterContainer}>
        {FILTERS.map(f => (
          <TouchableOpacity
            key={f.key}
            style={[styles.filterBtn, selectedFilter === f.key && styles.filterBtnActive]}
            onPress={() => handleFilterChange(f.key as any)}
          >
            <Ionicons name={f.icon as any} size={14} color={selectedFilter === f.key ? COLORS.background : COLORS.textMuted} />
            <Text style={[styles.filterText, selectedFilter === f.key && styles.filterTextActive]}>
              {f.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Leaderboard List */}
      <Animated.View style={{ opacity: fadeAnim }}>
        <FlatList
          data={entries}
          renderItem={renderEntry}
          keyExtractor={keyExtractor}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={handleRefresh}
              tintColor={COLORS.primary}
              colors={[COLORS.primary]}
            />
          }
          showsVerticalScrollIndicator={false}
          contentContainerStyle={styles.listContent}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
          ListEmptyComponent={
            <View style={styles.empty}>
              <Ionicons name="people-outline" size={48} color={COLORS.textMuted} />
              <Text style={styles.emptyText}>Nenhum participante ainda</Text>
            </View>
          }
        />
      </Animated.View>
    </View>
  );
}

