// src/components/social/LiveReactions.tsx
// Live Reactions - Floating emoji bar during live workouts

import { useState, useEffect, useRef, useCallback } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

interface Reaction {
  id: string;
  emoji: string;
  type: string;
  count: number;
}

interface FloatingReaction {
  id: string;
  emoji: string;
  x: number;
  animY: Animated.Value;
  opacity: Animated.Value;
  scale: Animated.Value;
}

interface LiveReactionsProps {
  liveId: string;
  currentUserId: string;
  onSendReaction: (type: string) => void;
  reactions?: Reaction[];
}

const REACTION_TYPES = [
  { emoji: '🔥', type: 'fire', label: 'Fogo' },
  { emoji: '💪', type: 'muscle', label: 'Músculo' },
  { emoji: '❤️', type: 'heart', label: 'Coração' },
  { emoji: '⚡', type: 'lightning', label: 'Relâmpago' },
  { emoji: '🎯', type: 'target', label: 'Alvo' },
  { emoji: '🏆', type: 'trophy', label: 'Troféu' },
];

export default function LiveReactions({ liveId, currentUserId, onSendReaction, reactions = [] }: LiveReactionsProps) {
  const [floatingReactions, setFloatingReactions] = useState<FloatingReaction[]>([]);
  const [reactionCounts, setReactionCounts] = useState<Record<string, number>>({});
  const animationIdRef = useRef(0);

  useEffect(() => {
    const counts: Record<string, number> = {};
    reactions.forEach(r => {
      counts[r.type] = r.count;
    });
    setReactionCounts(counts);
  }, [reactions]);

  const createFloatingReaction = useCallback((emoji: string) => {
    const id = `reaction-${animationIdRef.current++}`;
    const x = Math.random() * (SCREEN_WIDTH - 100) + 50;
    const animY = new Animated.Value(SCREEN_HEIGHT);
    const opacity = new Animated.Value(1);
    const scale = new Animated.Value(0.5);

    const newReaction: FloatingReaction = {
      id,
      emoji,
      x,
      animY,
      opacity,
      scale,
    };

    setFloatingReactions(prev => [...prev, newReaction]);

    // Animate up and fade out
    Animated.parallel([
      Animated.timing(animY, {
        toValue: SCREEN_HEIGHT * 0.3,
        duration: 2000,
        useNativeDriver: true,
      }),
      Animated.sequence([
        Animated.spring(scale, {
          toValue: 1.2,
          tension: 50,
          friction: 3,
          useNativeDriver: true,
        }),
        Animated.timing(scale, {
          toValue: 1,
          duration: 200,
          useNativeDriver: true,
        }),
      ]),
      Animated.sequence([
        Animated.delay(1500),
        Animated.timing(opacity, {
          toValue: 0,
          duration: 500,
          useNativeDriver: true,
        }),
      ]),
    ]).start(() => {
      setFloatingReactions(prev => prev.filter(r => r.id !== id));
    });
  }, []);

  const handleReaction = useCallback((type: string, emoji: string) => {
    onSendReaction(type);
    createFloatingReaction(emoji);

    // Quick burst animation
    Animated.sequence([
      Animated.delay(100),
      Animated.timing(new Animated.Value(1), {
        toValue: 0,
        duration: 300,
        useNativeDriver: true,
      }),
    ]).start();
  }, [onSendReaction, createFloatingReaction]);

  const getTotalReactions = () => {
    return Object.values(reactionCounts).reduce((sum, count) => sum + count, 0);
  };

  return (
    <View style={styles.container}>
      {/* Floating Reactions Layer */}
      <View style={styles.floatingContainer} pointerEvents="none">
        {floatingReactions.map(reaction => (
          <Animated.Text
            key={reaction.id}
            style={[
              styles.floatingEmoji,
              {
                left: reaction.x,
                transform: [
                  { translateY: reaction.animY },
                  { scale: reaction.scale },
                ],
                opacity: reaction.opacity,
              },
            ]}
          >
            {reaction.emoji}
          </Animated.Text>
        ))}
      </View>

      {/* Reaction Bar */}
      <View style={styles.reactionBar}>
        {/* Total Count */}
        <View style={styles.totalCount}>
          <Ionicons name="heart" size={14} color={COLORS.error} />
          <Text style={styles.totalText}>{getTotalReactions()}</Text>
        </View>

        {/* Reaction Buttons */}
        <View style={styles.reactionButtons}>
          {REACTION_TYPES.map(reaction => {
