// @ts-nocheck
// src/components/social/LiveWorkoutView.js
// Tela completa de live de treino com timer, chat e participantes

import { useState, useEffect, useRef } from 'react';
import { View, Text, ScrollView, TextInput, TouchableOpacity, FlatList, StyleSheet, KeyboardAvoidingView, Platform, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { Avatar } from '../ui/Avatar';
import { styles } from './liveWorkoutViewStyles';
import { useAuth } from '../../context/AuthContext';
import { useSecurity } from '../../hooks/useSecurity';
import { moderateText } from '../../services/contentModeration';
import { subscribeToLive, sendMessage, getLiveMessages, getLiveParticipants, updateWorkoutState, leaveLive } from '../../services/liveWorkouts';

export default function LiveWorkoutView({ live, isHost, onEnd }) {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [participants, setParticipants] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [timer, setTimer] = useState(0);
  const [currentExercise, setCurrentExercise] = useState('');
  const [isResting, setIsResting] = useState(false);
  const [showParticipants, setShowParticipants] = useState(false);
  const flatListRef = useRef(null);
  const timerRef = useRef(null);
  const { checkAndPerform, log, ACTIONS } = useSecurity();

  useEffect(() => {
    loadData();
    const unsub = subscribeToLive(live.id, {
      onMessage: (payload: any) => {
        if (payload.eventType === 'INSERT') {
          setMessages(prev => [...prev, payload.new]);
        }
      },
      onParticipant: (payload: any) => {
        if (payload.eventType === 'INSERT') {
          setParticipants(prev => [...prev, payload.new]);
        } else if (payload.eventType === 'DELETE') {
          setParticipants(prev => prev.filter(p => p.user_id !== payload.old.user_id));
        }
      },
      onState: (payload: any) => {
        if (payload.new) {
          setTimer(payload.new.timer_seconds || 0);
          setCurrentExercise(payload.new.current_exercise || '');
          setIsResting(payload.new.is_resting || false);
        }
      },
      onLiveUpdate: (payload) => {
        if (payload.new?.status === 'ended') onEnd?.();
      },
    });

    if (isHost) {
      timerRef.current = setInterval(() => {
        setTimer(prev => {
          const newTime = prev + 1;
          updateWorkoutState(live.id, { timer_seconds: newTime });
          return newTime;
        });
      }, 1000);
    }

    return () => {
      unsub();
      clearInterval(timerRef.current);
    };
  }, [live.id]);

  const loadData = async () => {
    const [msgs, parts] = await Promise.all([
      getLiveMessages(live.id),
      getLiveParticipants(live.id),
    ]);
    setMessages(msgs);
    setParticipants(parts);
  };

  const handleSend = async () => {
    if (!newMessage.trim()) return;

    // Moderar texto antes de enviar
    const textCheck = moderateText(newMessage, user.id);
    if (textCheck.blocked) {
      Alert.alert('Mensagem Bloqueada', textCheck.message);
      return;
    }

    await checkAndPerform(ACTIONS.LIVE_MESSAGE, 'live', async () => {
      await sendMessage(live.id, user.id, newMessage.trim());
      setNewMessage('');
    }, 'Erro ao enviar mensagem');
  };

  const handleToggleRest = async () => {
    if (!isHost) return;
    const newResting = !isResting;
    setIsResting(newResting);
    await updateWorkoutState(live.id, { is_resting: newResting });
  };

  const handleNextExercise = async (exercise) => {
    if (!isHost) return;
    setCurrentExercise(exercise);
    await updateWorkoutState(live.id, { current_exercise: exercise });
  };

  const formatTime = (seconds) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const renderMessage = ({ item }) => (
    <View style={[styles.message, item.user_id === user.id && styles.messageOwn]}>
      <Avatar name={item.profiles?.name} size="xs" />
      <View style={styles.messageContent}>
        <Text style={styles.messageAuthor}>{item.profiles?.name || 'Atleta'}</Text>
        <Text style={styles.messageText}>{item.message}</Text>
        <Text style={styles.messageTime}>{new Date(item.created_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</Text>
      </View>
    </View>
  );

  return (
    <KeyboardAvoidingView style={styles.container} behavior={Platform.OS === 'ios' ? 'padding' : undefined} keyboardVerticalOffset={90}>
      <View style={styles.timerSection}>
        <Text style={styles.timerLabel}>{isResting ? 'Descanso' : 'Tempo'}</Text>
        <Text style={[styles.timer, isResting && styles.timerRest]}>{formatTime(timer)}</Text>
        {currentExercise ? (
          <Text style={styles.exercise}>Exercício: {currentExercise}</Text>
        ) : null}
        {isHost && (
          <View style={styles.hostControls}>
            <TouchableOpacity style={styles.controlBtn} onPress={handleToggleRest}>
              <Ionicons name={isResting ? 'play' : 'pause'} size={20} color={COLORS.background} />
              <Text style={styles.controlText}>{isResting ? 'Retomar' : 'Descanso'}</Text>
            </TouchableOpacity>
          </View>
        )}
      </View>

      <View style={styles.participantsBar}>
        <TouchableOpacity onPress={() => setShowParticipants(!showParticipants)}>
          <Ionicons name="people" size={18} color={COLORS.textMuted} />
        </TouchableOpacity>
        <Text style={styles.participantCount}>{participants.length} participantes</Text>
        {isHost && (
          <TouchableOpacity style={styles.endBtn} onPress={onEnd}>
            <Ionicons name="stop-circle" size={18} color={COLORS.error} />
            <Text style={styles.endText}>Encerrar</Text>
          </TouchableOpacity>
        )}
      </View>

      {showParticipants && (
        <ScrollView style={styles.participantsList} horizontal showsHorizontalScrollIndicator={false}>
          {participants.map(p => (
            <View key={p.id} style={styles.participantChip}>
              <Avatar name={p.profiles?.name} size="xs" />
              <Text style={styles.participantName} numberOfLines={1}>{p.profiles?.name}</Text>
            </View>
          ))}
        </ScrollView>
      )}

      <FlatList
        ref={flatListRef}
        data={messages}
        keyExtractor={item => item.id}
        renderItem={renderMessage}
        style={styles.chatArea}
        onContentSizeChange={() => flatListRef.current?.scrollToEnd()}
      />

      <View style={styles.inputBar}>
        <TextInput
          style={styles.input}
          placeholder="Mensagem..."
          placeholderTextColor={COLORS.textMuted}
          value={newMessage}
          onChangeText={setNewMessage}
          onSubmitEditing={handleSend}
        />
        <TouchableOpacity style={styles.sendBtn} onPress={handleSend} disabled={!newMessage.trim()}>
          <Ionicons name="send" size={18} color={newMessage.trim() ? COLORS.primary : COLORS.textMuted} />
        </TouchableOpacity>
      </View>
    </KeyboardAvoidingView>
  );
}

import React, { memo, useState, useCallback, useRef } from 'react';
import { View, TextInput, FlatList, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { Avatar } from '../ui/Avatar';
import { supabase } from '../../config/supabase';
import { MENTION_SEARCH_LIMIT } from '../../config/socialConfig';

interface MentionUser { id: string; name: string; avatar_url: string | null }

interface MentionInputProps {
  value: string;
  onChangeText: (text: string) => void;
  onMention: (user: MentionUser) => void;
  userId: string;
  placeholder?: string;
}

function MentionInput({ value, onChangeText, onMention, userId, placeholder }: MentionInputProps) {
  const [suggestions, setSuggestions] = useState<MentionUser[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef<TextInput>(null);

  const searchUsers = useCallback(async (query: string) => {
    if (query.length < 1) { setSuggestions([]); setShowSuggestions(false); return; }
    const { data } = await supabase.from('profiles').select('id, name, avatar_url')
      .ilike('name', `%${query}%`).neq('id', userId).limit(MENTION_SEARCH_LIMIT);
    setSuggestions(data || []);
    setShowSuggestions((data?.length || 0) > 0);
  }, [userId]);

  const handleChangeText = useCallback((text: string) => {
    onChangeText(text);
    const lastAt = text.lastIndexOf('@');
    if (lastAt >= 0 && (lastAt === 0 || text[lastAt - 1] === ' ')) {
      const query = text.slice(lastAt + 1);
      if (!query.includes(' ')) { searchUsers(query); return; }
    }
    setShowSuggestions(false);
  }, [onChangeText, searchUsers]);

  const handleSelect = useCallback((user: MentionUser) => {
    const before = value.slice(0, value.lastIndexOf('@'));
    onChangeText(`${before}@${user.name} `);
    setShowSuggestions(false);
    onMention(user);
    inputRef.current?.focus();
  }, [value, onChangeText, onMention]);

  return (
    <View style={styles.container}>
      <TextInput ref={inputRef} style={styles.input} value={value} onChangeText={handleChangeText}
        placeholder={placeholder || 'Escreva... use @ para mencionar'} placeholderTextColor={COLORS.textMuted} multiline />
      {showSuggestions && suggestions.length > 0 && (
        <FlatList data={suggestions} keyExtractor={(i) => i.id} style={styles.dropdown}
          renderItem={({ item }) => (
            <TouchableOpacity style={styles.suggestionItem} onPress={() => handleSelect(item)}>
              <Avatar name={item.name} size="xs" />
              <Text style={styles.suggestionName}>{item.name}</Text>
            </TouchableOpacity>
          )} />
      )}
    </View>
  );
}

export default memo(MentionInput);

const styles = StyleSheet.create({
  container: { position: 'relative', zIndex: 1 },
  input: { height: 40, backgroundColor: COLORS.background, borderRadius: BORDER_RADIUS.md, paddingHorizontal: SPACING.md, color: COLORS.textTitle, fontFamily: 'Inter_400Regular', fontSize: 14 },
  dropdown: { position: 'absolute', top: 44, left: 0, right: 0, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.md, borderWidth: 1, borderColor: COLORS.border, maxHeight: 180, elevation: 4 },
  suggestionItem: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, padding: SPACING.sm },
  suggestionName: { fontFamily: 'Inter_400Regular', fontSize: 13, color: COLORS.textTitle },
});

