function RecordItem({ record }) {
  const isNew = record.isNew;

  return (
    <View style={[styles.recordItem, isNew && styles.recordItemNew]}>
      <View style={[styles.recordIcon, { backgroundColor: (isNew ? COLORS.primary : COLORS.success) + '20' }]}>
