// Workout Stories - Horizontal scrollable story bubbles with workout thumbnails

import { useState, useEffect, useRef, useCallback } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Image, StyleSheet, Animated, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { SHADOWS } from '../../constants/shadows';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const STORY_DURATION = 5000; // 5 seconds auto-advance

interface WorkoutStory {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  workoutName: string;
  workoutThumbnail: string;
  duration: number;
  exercises: number;
  seen: boolean;
}

interface WorkoutStoriesProps {
  stories: WorkoutStory[];
  currentUserId: string;
  onViewStory: (story: WorkoutStory, index: number) => void;
  onAddStory: () => void;
}

export default function WorkoutStories({ stories, currentUserId, onViewStory, onAddStory }: WorkoutStoriesProps) {
  const [selectedStory, setSelectedStory] = useState<WorkoutStory | null>(null);
  const [showViewer, setShowViewer] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [] = useState(() => new Animated.Value());
  const autoAdvanceTimer = useRef<NodeJS.Timeout | null>(null);

  const startAutoAdvance = useCallback(() => {
    progressAnim.setValue(0);
    if (autoAdvanceTimer.current) {
      clearTimeout(autoAdvanceTimer.current);
    }

    Animated.timing(progressAnim, {
      toValue: 1,
      duration: STORY_DURATION,
      useNativeDriver: false,
    }).start();

    autoAdvanceTimer.current = setTimeout(() => {
      goToNextStory();
    }, STORY_DURATION);
  }, [currentIndex, stories]);

  const goToNextStory = useCallback(() => {
    if (currentIndex < stories.length - 1) {
      const nextIndex = currentIndex + 1;
      setCurrentIndex(nextIndex);
      setSelectedStory(stories[nextIndex]);
      startAutoAdvance();
    } else {
      closeViewer();
    }
  }, [currentIndex, stories]);

  const goToPreviousStory = useCallback(() => {
    if (currentIndex > 0) {
      const prevIndex = currentIndex - 1;
      setCurrentIndex(prevIndex);
      setSelectedStory(stories[prevIndex]);
      startAutoAdvance();
    }
  }, [currentIndex, stories]);

  const closeViewer = useCallback(() => {
    if (autoAdvanceTimer.current) {
      clearTimeout(autoAdvanceTimer.current);
    }
    setShowViewer(false);
    setSelectedStory(null);
    setCurrentIndex(0);
  }, []);

  const handleStoryPress = (story: WorkoutStory, index: number) => {
    setSelectedStory(story);
    setCurrentIndex(index);
    setShowViewer(true);
    startAutoAdvance();
    onViewStory(story, index);
  };

  useEffect(() => {
    return () => {
      if (autoAdvanceTimer.current) {
        clearTimeout(autoAdvanceTimer.current);
      }
    };
  }, []);

  if (stories.length === 0) return null;

  return (
    <>
      <View style={styles.container}>
