import React, { useEffect, useRef } from 'react';
import { View, Animated, StyleSheet } from 'react-native';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';

type SkeletonVariant = 'text' | 'circle' | 'rectangle' | 'card';

interface SkeletonProps {
  width?: number | string;
  height?: number;
  variant?: SkeletonVariant;
  borderRadius?: number;
  style?: any;
}

const VARIANT_DEFAULTS: Record<SkeletonVariant, { width: number | string; height: number; borderRadius: number }> = {
  text: { width: '100%', height: 14, borderRadius: 4 },
  circle: { width: 48, height: 48, borderRadius: 24 },
  rectangle: { width: '100%', height: 120, borderRadius: BORDER_RADIUS.md },
  card: { width: '100%', height: 180, borderRadius: BORDER_RADIUS.lg },
};

export default function Skeleton({ width, height, variant = 'text', borderRadius, style }: SkeletonProps) {
  const defaults = VARIANT_DEFAULTS[variant];
  const [] = useState(() => new Animated.Value());

  useEffect(() => {
    const animation = Animated.loop(
      Animated.timing(translateX, {
        toValue: 200,
        duration: 1200,
        useNativeDriver: false,
      })
    );
    animation.start();
    return () => animation.stop();
  }, [translateX]);

  return (
    <View
      style={[
        styles.skeleton,
        { width: width ?? defaults.width, height: height ?? defaults.height, borderRadius: borderRadius ?? defaults.borderRadius },
        style,
      ]}
    >
      <Animated.View
        style={[
          styles.shimmer,
          { transform: [{ translateX }] },
        ]}
      />
    </View>
  );
}

