// src/components/workout/HistoryCard.tsx
// Card de histórico de treino - NOVAIX FITNESS

import React, { useRef, useEffect, memo } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';
import { isToday, getDaysBetween, formatTimeBR } from '../../helpers/dates';

const CATEGORY_COLORS: Record<string, string> = {
  'Musculação': COLORS.primary,
  'HIIT': COLORS.error,
  'Cardio': COLORS.secondary,
  'Yoga': COLORS.info,
  'Calistenia': COLORS.success,
  'Natação': COLORS.info,
};

interface HistoryItem {
  completed?: boolean;
  workouts?: {
    title?: string;
    category?: string;
    duration_minutes?: number;
  };
  duration?: number;
  rating?: number;
  notes?: string;
  completed_at?: string;
  created_at?: string;
}

interface HistoryCardProps {
  item: HistoryItem;
  onPress: () => void;
  index?: number;
}

function formatDate(dateStr?: string): string {
  if (!dateStr) return '';
  const date = new Date(dateStr);
  if (isToday(dateStr)) return `Hoje, ${formatTimeBR(dateStr)}`;
  if (getDaysBetween(dateStr, new Date()) === 1) return `Ontem, ${formatTimeBR(dateStr)}`;
  return date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
}

function parseNotes(notes?: string): string | null {
  if (!notes) return null;
  try {
    const p = JSON.parse(notes);
    return p.exerciseCount ? `${p.exerciseCount} exercícios` : null;
  } catch { return notes; }
}

export default memo(function HistoryCard({ item, onPress, index = 0 }: HistoryCardProps): React.ReactElement {
  const scaleAnim = useRef(new Animated.Value(0.95)).current;
  const fadeAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.spring(scaleAnim, { toValue: 1, tension: 40, friction: 8, delay: index * 50, useNativeDriver: true }),
      Animated.timing(fadeAnim, { toValue: 1, duration: 200, delay: index * 50, useNativeDriver: true }),
    ]).start();
  }, []);

  const isCompleted = item.completed;
  const categoryColor = CATEGORY_COLORS[item.workouts?.category || ''] || COLORS.primary;
  const duration = item.duration || item.workouts?.duration_minutes || 0;
  const exerciseCount = parseNotes(item.notes);

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim, transform: [{ scale: scaleAnim }] }]}>
      <TouchableOpacity style={styles.card} activeOpacity={0.7} onPress={onPress}>
        <View style={styles.cardHeader}>
          <View style={[styles.statusDot, { backgroundColor: isCompleted ? COLORS.success : COLORS.attention }]} />
          <View style={styles.headerInfo}>
            <Text style={styles.title} numberOfLines={1}>{item.workouts?.title || 'Treino'}</Text>
            <Text style={styles.date}>{formatDate(item.completed_at || item.created_at)}</Text>
          </View>
          {item.workouts?.category && (
            <View style={[styles.categoryBadge, { backgroundColor: categoryColor + '15' }]}>
              <Text style={[styles.categoryText, { color: categoryColor }]}>{item.workouts.category}</Text>
            </View>
          )}
        </View>

        <View style={styles.statsGrid}>
          <View style={styles.statItem}>
            <View style={[styles.statIcon, { backgroundColor: COLORS.primary + '15' }]}>
              <Ionicons name="time" size={14} color={COLORS.primary} />
            </View>
            <View>
              <Text style={styles.statValue}>{duration}</Text>
              <Text style={styles.statLabel}>min</Text>
            </View>
          </View>

          {item.rating && item.rating > 0 && (
            <View style={styles.statItem}>
              <View style={[styles.statIcon, { backgroundColor: COLORS.attention + '15' }]}>
                <Ionicons name="star" size={14} color={COLORS.attention} />
              </View>
              <View>
                <Text style={styles.statValue}>{item.rating}</Text>
                <Text style={styles.statLabel}>/5</Text>
              </View>
            </View>
          )}

          {exerciseCount && (
            <View style={styles.statItem}>
              <View style={[styles.statIcon, { backgroundColor: COLORS.success + '15' }]}>
                <Ionicons name="barbell" size={14} color={COLORS.success} />
              </View>
              <View>
                <Text style={styles.statValue}>{exerciseCount}</Text>
              </View>
            </View>
          )}

          <View style={styles.statItem}>
            <View style={[styles.statIcon, { backgroundColor: isCompleted ? COLORS.success + '15' : COLORS.attention + '15' }]}>
              <Ionicons name={isCompleted ? 'checkmark-circle' : 'play-circle'} size={14} color={isCompleted ? COLORS.success : COLORS.attention} />
            </View>
            <View>
              <Text style={[styles.statValue, { color: isCompleted ? COLORS.success : COLORS.attention }]}>
                {isCompleted ? 'Feito' : 'Andamento'}
              </Text>
            </View>
          </View>
        </View>

        {isCompleted && item.rating && item.rating >= 4 && (
          <View style={styles.excellentBadge}>
            <Ionicons name="trophy" size={12} color={COLORS.primary} />
            <Text style={styles.excellentText}>Treino Excelente!</Text>
          </View>
        )}
      </TouchableOpacity>
    </Animated.View>
  );
});

const styles = StyleSheet.create({
  container: { marginBottom: SPACING.sm },
  card: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.lg, borderWidth: 1, borderColor: COLORS.border },
  cardHeader: { flexDirection: 'row', alignItems: 'center', marginBottom: SPACING.md },
  statusDot: { width: 10, height: 10, borderRadius: 5, marginRight: SPACING.sm },
  headerInfo: { flex: 1 },
  title: { fontFamily: 'Montserrat_600SemiBold', fontSize: 15, color: COLORS.textTitle },
  date: { fontFamily: 'Inter_400Regular', fontSize: 12, color: COLORS.textMuted, marginTop: 2 },
  categoryBadge: { paddingHorizontal: SPACING.sm, paddingVertical: 3, borderRadius: BORDER_RADIUS.sm },
  categoryText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 10, letterSpacing: 0.5 },
  statsGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.md, paddingTop: SPACING.md, borderTopWidth: 1, borderTopColor: COLORS.border },
  statItem: { flexDirection: 'row', alignItems: 'center', gap: SPACING.xs },
  statIcon: { width: 28, height: 28, borderRadius: 14, justifyContent: 'center', alignItems: 'center' },
  statValue: { fontFamily: 'Montserrat_700Bold', fontSize: 13, color: COLORS.textTitle },
  statLabel: { fontFamily: 'Inter_400Regular', fontSize: 10, color: COLORS.textMuted },
  excellentBadge: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: SPACING.xs, marginTop: SPACING.md, backgroundColor: COLORS.primary + '10', paddingVertical: SPACING.xs, borderRadius: BORDER_RADIUS.sm },
  excellentText: { fontFamily: 'Montserrat_600SemiBold', fontSize: 11, color: COLORS.primary },
});

// src/components/workout/LoadHistory.tsx
// Histórico de Carga e Repetições - NOVAIX FITNESS

import { useState, useEffect, useCallback, useRef } from 'react';
import { View, Text, StyleSheet, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../config/supabase';
import { useAuth } from '../../context/AuthContext';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';

interface ExerciseLog {
  id: string;
  set_number: number;
  reps_done: number;
  weight_kg: number;
  created_at: string;
}

interface GroupedSession {
  date: string;
  items: ExerciseLog[];
}

interface LoadHistoryProps {
  exerciseName: string;
}

export default function LoadHistory({ exerciseName }: LoadHistoryProps): React.ReactElement {
  const { user } = useAuth();
  const [loading, setLoading] = useState<boolean>(true);
  const [history, setHistory] = useState<GroupedSession[]>([]);
  const [] = useState(() => new Animated.Value());

  useEffect(() => { fetchLoadHistory(); }, [user?.id, exerciseName]);

  const fetchLoadHistory = useCallback(async () => {
    if (!user?.id || !exerciseName) { setLoading(false); return; }
    setLoading(true);
    try {
      const { data } = await supabase.from('user_exercise_logs')
        .select('id, set_number, reps_done, weight_kg, created_at')
        .eq('exercise_name', exerciseName)
        .order('created_at', { ascending: false })
        .limit(20);
      if (data) setHistory(groupLogsByDate(data));
    } catch (err) { console.error('Erro:', err); }
    finally { setLoading(false); }
  }, [user?.id, exerciseName]);

  useEffect(() => {
    Animated.timing(fadeAnim, { toValue: 1, duration: 300, useNativeDriver: true }).start();
  }, [history]);

  if (loading) return <View style={styles.loading}><Ionicons name="sync" size={16} color={COLORS.textMuted} /></View>;

  if (history.length === 0) {
    return (
      <View style={styles.empty}>
        <Ionicons name="stats-chart-outline" size={18} color={COLORS.textMuted} />
        <Text style={styles.emptyText}>Nenhum histórico. Suas cargas aparecerão aqui após concluir séries.</Text>
      </View>
    );
  }

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      <View style={styles.header}>
        <Ionicons name="trending-up" size={16} color={COLORS.primary} />
        <Text style={styles.title}>HISTÓRICO DE CARGAS</Text>
      </View>

      {history.map((session, i) => (
        <View key={i} style={styles.sessionRow}>
          <View style={styles.dateBadge}>
            <Text style={styles.dateText}>{session.date}</Text>
          </View>
          <View style={styles.setsWrapper}>
            {session.items.map((log) => (
              <View key={log.id} style={styles.setTag}>
                <Text style={styles.setTagText}>
                  S{log.set_number} <Text style={styles.highlight}>{log.reps_done}</Text>x<Text style={styles.highlight}>{log.weight_kg}</Text>kg
                </Text>
              </View>
            ))}
          </View>
        </View>
      ))}
    </Animated.View>
  );
}

function groupLogsByDate(logs: ExerciseLog[]): GroupedSession[] {
  const groups: Record<string, ExerciseLog[]> = {};
  logs.forEach(log => {
    const d = new Date(log.created_at);
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`;
    if (!groups[dateStr]) groups[dateStr] = [];
    groups[dateStr].push(log);
  });
  return Object.entries(groups).map(([date, items]) => ({
    date, items: items.sort((a, b) => a.set_number - b.set_number),
  })).slice(0, 5);
}

const styles = StyleSheet.create({
  container: { marginBottom: SPACING.md, padding: SPACING.md, backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.md, borderWidth: 1, borderColor: COLORS.border },
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, marginBottom: SPACING.md },
  title: { fontFamily: 'Montserrat_600SemiBold', fontSize: 10, color: COLORS.textMuted, letterSpacing: 1 },
  loading: { padding: SPACING.xl, alignItems: 'center' },
  empty: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, backgroundColor: COLORS.background, borderRadius: BORDER_RADIUS.sm, padding: SPACING.md, borderWidth: 1, borderColor: COLORS.border, marginBottom: SPACING.md },
  emptyText: { fontFamily: 'Inter_400Regular', fontSize: 11, color: COLORS.textMuted, flex: 1 },
  sessionRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: SPACING.sm, borderBottomWidth: 1, borderBottomColor: COLORS.border },
  dateBadge: { backgroundColor: COLORS.primary + '15', paddingHorizontal: SPACING.sm, paddingVertical: 3, borderRadius: BORDER_RADIUS.sm, marginRight: SPACING.md },
  dateText: { fontFamily: 'Montserrat_700Bold', fontSize: 10, color: COLORS.primary },
  setsWrapper: { flexDirection: 'row', flexWrap: 'wrap', gap: SPACING.xs, flex: 1, justifyContent: 'flex-end' },
  setTag: { backgroundColor: COLORS.background, paddingHorizontal: SPACING.sm, paddingVertical: 2, borderRadius: BORDER_RADIUS.sm, borderWidth: 1, borderColor: COLORS.border },
  setTagText: { fontFamily: 'Inter_400Regular', fontSize: 10, color: COLORS.textMuted },
  highlight: { fontFamily: 'Montserrat_700Bold', color: COLORS.primary },
});

