// SetsTracker.tsx
import { useState, useEffect, useCallback, useMemo, memo } from 'react';
import { View, StyleSheet } from 'react-native';
import * as Haptics from 'expo-haptics';
import { SPACING } from '../../constants/spacing';
import { Card } from '../ui/Card';
import { supabase } from '../../config/supabase';
import { useNetworkStatus } from '../../hooks/useNetworkStatus';
import { addPendingAction, cacheExerciseLogs, getCachedExerciseLogs } from '../../services/offline';
import { speakNextExercise, speakRestStart, speakRestHalfway, speakRestEnd, speakHalfway, speakMotivation, isVoiceCoachEnabled, setVoiceCoachEnabled } from '../../services/voiceCoach';
import ExerciseSelector from './ExerciseSelector';
import SetInput from './SetInput';
import RestCountdown from './RestCountdown';
import SetLogList from './SetLogList';

interface Exercise {
  name: string;
  reps?: number | string;
  weight?: number | string;
  rest?: number;
  sets?: number;
  muscle?: string;
  [key: string]: unknown;
}

interface Workout {
  exercises?: Exercise[];
  [key: string]: unknown;
}

interface ExerciseLog {
  id: string;
  user_workout_id: string;
  exercise_name: string;
  set_number: number;
  reps_done: number;
  weight_kg: number;
}

interface SetsTrackerProps {
  userWorkoutId: string;
  workout: Workout;
}

export default memo(function SetsTracker({ userWorkoutId, workout }: SetsTrackerProps): React.ReactElement | null {
  const { isConnected } = useNetworkStatus();
  const [selectedEx, setSelectedEx] = useState<string | null>(null);
  const [weight, setWeight] = useState<string>('');
  const [reps, setReps] = useState<string>('');
  const [logs, setLogs] = useState<ExerciseLog[]>([]);
  const [loadingLogs, setLoadingLogs] = useState<boolean>(false);
  const [saving, setSaving] = useState<boolean>(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [voiceEnabled, setVoiceEnabled] = useState<boolean>(isVoiceCoachEnabled());

  const exercises: Exercise[] = useMemo(() => workout?.exercises || [], [workout?.exercises]);

  useEffect((): void => {
    if (exercises.length > 0 && !selectedEx) {
      setSelectedEx(exercises[0].name);
    } else if (selectedEx && exercises.length > 0) {
      const ex = exercises.find((e: Exercise) => e.name === selectedEx);
      const idx = exercises.findIndex((e: Exercise) => e.name === selectedEx) + 1;
      speakNextExercise(selectedEx, ex?.reps, ex?.weight, idx, exercises.length);
    }
  }, [exercises, selectedEx]);

  const fetchLogs = useCallback(async (): Promise<void> => {
    if (!userWorkoutId || !selectedEx) return;
    setLoadingLogs(true);
    try {
      const cached = await getCachedExerciseLogs(userWorkoutId, selectedEx);
      if (cached?.length > 0) setLogs(cached);
      if (isConnected) {
        const { data, error } = await supabase.from('user_exercise_logs').select('*').eq('user_workout_id', userWorkoutId).eq('exercise_name', selectedEx).order('set_number', { ascending: true });
        if (!error && data) { setLogs(data); await cacheExerciseLogs(userWorkoutId, selectedEx, data); }
      }
    } catch (err) { console.error('Erro ao buscar séries:', err); }
    finally { setLoadingLogs(false); }
  }, [userWorkoutId, selectedEx, isConnected]);

  useEffect((): void => { fetchLogs(); }, [fetchLogs]);

  useEffect((): (() => void) | undefined => {
    if (countdown === null) return;
    if (countdown <= 0) {
      setCountdown(null);
      try { Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); } catch {}
      speakRestEnd();
      return;
    }
    const exRest = exercises.find((ex: Exercise) => ex.name === selectedEx)?.rest || 60;
    if (countdown === Math.floor(exRest / 2)) speakRestHalfway();
    const id = setInterval((): void => setCountdown((c: number | null) => c !== null ? c - 1 : null), 1000);
    return (): void => clearInterval(id);
  }, [countdown, exercises, selectedEx]);

  const handleAddSet = async (): Promise<void> => {
    const parsedReps = parseInt(reps);
    if (!userWorkoutId || !selectedEx || isNaN(parsedReps) || parsedReps <= 0) return;
    setSaving(true);
    try {
      const nextSetNumber = logs.length + 1;
      const parsedWeight = parseFloat(weight) || 0;
      const newLog: ExerciseLog = { id: Date.now().toString(), user_workout_id: userWorkoutId, exercise_name: selectedEx, set_number: nextSetNumber, reps_done: parsedReps, weight_kg: parsedWeight };
      const updatedLogs = [...logs, newLog];
      setLogs(updatedLogs);
      await cacheExerciseLogs(userWorkoutId, selectedEx, updatedLogs);
      if (isConnected) {
        await supabase.from('user_exercise_logs').insert({ user_workout_id: userWorkoutId, exercise_name: selectedEx, set_number: nextSetNumber, reps_done: parsedReps, weight_kg: parsedWeight });
      } else {
        await addPendingAction({ type: 'ADD_EXERCISE_LOG', userWorkoutId, exerciseName: selectedEx, setNumber: nextSetNumber, repsDone: parsedReps, weightKg: parsedWeight });
      }
      setReps('');
      const exRest = exercises.find((ex: Exercise) => ex.name === selectedEx)?.rest || 60;
      setCountdown(exRest);
      speakRestStart(exRest);
      const currentIdx = exercises.findIndex((ex: Exercise) => ex.name === selectedEx);
      if (currentIdx === Math.floor(exercises.length / 2) - 1) { speakHalfway(); }
      else if (Math.random() > 0.5) { setTimeout((): void => speakMotivation(), 4000); }
      await fetchLogs();
    } catch (err) { console.error('Erro ao registrar série:', err); }
    finally { setSaving(false); }
  };

  if (!workout || exercises.length === 0) return null;

  return (
    <Card variant="surface" style={styles.card}>
      <ExerciseSelector exercises={exercises} selected={selectedEx} onSelect={setSelectedEx} voiceEnabled={voiceEnabled} onToggleVoice={(): void => { const v = !voiceEnabled; setVoiceCoachEnabled(v); setVoiceEnabled(v); }} />
      {countdown !== null && <RestCountdown countdown={countdown} onAdd={(): void => setCountdown((c: number | null) => c !== null ? c + 15 : null)} onSubtract={(): void => setCountdown((c: number | null) => c !== null ? Math.max(0, c - 15) : null)} onSkip={(): void => setCountdown(null)} />}
      <SetInput weight={weight} setWeight={setWeight} reps={reps} setReps={setReps} onAdd={handleAddSet} saving={saving} />
      <SetLogList logs={logs} loading={loadingLogs} />
    </Card>
  );
});

const styles = StyleSheet.create({
  card: { padding: SPACING.lg, marginTop: SPACING.lg, marginBottom: SPACING.md },
});

// src/components/workout/SmartRestTimer.tsx
// Timer de descanso inteligente com deteccao automatica - NOVAIX FITNESS

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated } from 'react-native';
import type { TextStyle, ViewStyle } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Haptics from 'expo-haptics';
import Svg, { Circle, Defs, LinearGradient, Stop } from 'react-native-svg';
import { COLORS } from '../../constants/colors';
import { SPACING, BORDER_RADIUS } from '../../constants/spacing';

const CIRCLE_SIZE = 180;
const CIRCLE_STROKE = 8;
const CIRCLE_RADIUS = (CIRCLE_SIZE - CIRCLE_STROKE) / 2;
const CIRCLE_CIRCUMFERENCE = 2 * Math.PI * CIRCLE_RADIUS;

const REST_PRESETS: Record<string, number> = {
  compound: 120,
  isolation: 60,
  cardio: 30,
  heavy: 180,
  default: 90,
};

function getRestTime(exerciseType?: string): number {
  const type = (exerciseType || '').toLowerCase();
  if (type.includes('agachamento') || type.includes('deadlift') || type.includes('terra')) return REST_PRESETS.heavy;
  if (type.includes('supino') || type.includes('barra') || type.includes('leg press')) return REST_PRESETS.compound;
  if (type.includes('curl') || type.includes('extensao') || type.includes('fly')) return REST_PRESETS.isolation;
  return REST_PRESETS.default;
}

interface SmartRestTimerProps {
  isResting: boolean;
  totalTime: number;
  exerciseType?: string;
  nextExercise?: { name?: string; sets?: number; reps?: number; muscle?: string };
  restHistory?: number[];
  onSkip: () => void;
  onAddTime: () => void;
  onSubtractTime: () => void;
}

export default function SmartRestTimer({
  isResting, totalTime, exerciseType, nextExercise, restHistory = [], onSkip, onAddTime, onSubtractTime,
}: SmartRestTimerProps): React.ReactElement | null {
  const [elapsed, setElapsed] = useState(0);
  const [] = useState(() => new Animated.Value());
  const [] = useState(() => new Animated.Value());
  const prevTimeRef = useRef(totalTime);

  const timeRemaining = Math.max(0, totalTime - elapsed);
  const progress = totalTime > 0 ? elapsed / totalTime : 0;
  const strokeDashoffset = CIRCLE_CIRCUMFERENCE * (1 - Math.min(progress, 1));
  const isUrgent = timeRemaining <= 5;
  const timerColor = isUrgent ? COLORS.error : COLORS.success;

  const avgRest = restHistory.length > 0
    ? Math.round(restHistory.reduce((a, b) => a + b, 0) / restHistory.length)
    : getRestTime(exerciseType);

  const defaultRest = getRestTime(exerciseType);

  useEffect(() => {
    if (isResting) {
      setElapsed(0);
      Animated.timing(fadeAnim, { toValue: 1, duration: 300, useNativeDriver: true }).start();
    }
  }, [isResting]);

  useEffect(() => {
    if (!isResting) return;
    const interval = setInterval(() => setElapsed(p => p + 1), 1000);
    return () => clearInterval(interval);
  }, [isResting]);

  useEffect(() => {
    if (isUrgent && isResting) {
      Animated.sequence([
        Animated.timing(pulseAnim, { toValue: 1.12, duration: 150, useNativeDriver: true }),
        Animated.timing(pulseAnim, { toValue: 1, duration: 200, useNativeDriver: true }),
      ]).start();
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
    }
    if (timeRemaining === 0 && prevTimeRef.current > 0) {
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
    }
    prevTimeRef.current = timeRemaining;
  }, [timeRemaining, isUrgent, isResting]);

  const formatTime = useCallback((s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  }, []);

  if (!isResting) return null;

  return (
    <Animated.View style={[styles.container, { opacity: fadeAnim }]}>
      <View style={styles.header}>
        <Ionicons name="moon" size={16} color={COLORS.success} />
        <Text style={styles.headerTitle}>DESCANSO</Text>
      </View>

      <View style={styles.timerWrap}>
        <Svg width={CIRCLE_SIZE} height={CIRCLE_SIZE}>
          <Defs>
            <LinearGradient id="smartRestGrad" x1="0" y1="0" x2="1" y2="1">
              <Stop offset="0" stopColor={timerColor} />
              <Stop offset="1" stopColor={timerColor} stopOpacity="0.4" />
            </LinearGradient>
          </Defs>
          <Circle cx={CIRCLE_SIZE / 2} cy={CIRCLE_SIZE / 2} r={CIRCLE_RADIUS}
            stroke={COLORS.surfaceOverlay} strokeWidth={CIRCLE_STROKE} fill="none" />
          <Circle cx={CIRCLE_SIZE / 2} cy={CIRCLE_SIZE / 2} r={CIRCLE_RADIUS}
            stroke="url(#smartRestGrad)" strokeWidth={CIRCLE_STROKE} fill="none"
            strokeDasharray={CIRCLE_CIRCUMFERENCE} strokeDashoffset={strokeDashoffset}
            strokeLinecap="round" transform={`rotate(-90 ${CIRCLE_SIZE / 2} ${CIRCLE_SIZE / 2})`} />
        </Svg>
        <View style={styles.timerOverlay}>
          <Animated.View style={{ transform: [{ scale: pulseAnim }] }}>
            <Text style={[styles.timerText, { color: timerColor }]}>{formatTime(timeRemaining)}</Text>
          </Animated.View>
          <Text style={styles.progressLabel}>{Math.round(progress * 100)}%</Text>
        </View>
      </View>

      <View style={styles.infoRow}>
        <View style={styles.infoChip}>
          <Ionicons name="analytics" size={12} color={COLORS.primary} />
          <Text style={styles.infoText}>Padrao: {formatTime(defaultRest)}</Text>
        </View>
        {restHistory.length > 0 && (
          <View style={styles.infoChip}>
            <Ionicons name="trending-up" size={12} color={COLORS.secondary} />
            <Text style={styles.infoText}>Media: {formatTime(avgRest)}</Text>
          </View>
        )}
      </View>

      <View style={styles.controls}>
        <TouchableOpacity style={styles.ctrlBtn} onPress={onSubtractTime} accessibilityLabel="Menos 15s">
          <Ionicons name="remove-circle" size={22} color={COLORS.textMuted} />
          <Text style={styles.ctrlText}>-15s</Text>
        </TouchableOpacity>
        <TouchableOpacity style={styles.ctrlBtn} onPress={onAddTime} accessibilityLabel="Mais 15s">
          <Ionicons name="add-circle" size={22} color={COLORS.primary} />
          <Text style={[styles.ctrlText, { color: COLORS.primary }]}>+15s</Text>
        </TouchableOpacity>
      </View>

      {nextExercise && (
        <View style={styles.nextCard}>
          <Ionicons name="arrow-forward-circle" size={16} color={COLORS.primary} />
          <Text style={styles.nextLabel}>PROXIMO</Text>
          <Text style={styles.nextName}>{nextExercise.name}</Text>
          <Text style={styles.nextMeta}>{nextExercise.sets || 4}x{nextExercise.reps || 10} · {nextExercise.muscle || ''}</Text>
        </View>
      )}

      <TouchableOpacity style={styles.skipBtn} onPress={onSkip} accessibilityLabel="Pular descanso">
        <Ionicons name="play-skip-forward" size={18} color={COLORS.background} />
        <Text style={styles.skipText}>INICIAR AGORA</Text>
      </TouchableOpacity>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: { backgroundColor: COLORS.surface, borderRadius: BORDER_RADIUS.lg, padding: SPACING.lg, borderWidth: 1, borderColor: COLORS.success + '30', alignItems: 'center' } as ViewStyle,
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACING.sm, marginBottom: SPACING.md } as ViewStyle,
  headerTitle: { fontFamily: 'Montserrat_700Bold', fontSize: 12, color: COLORS.success, letterSpacing: 2 } as TextStyle,
  timerWrap: { position: 'relative', width: CIRCLE_SIZE, height: CIRCLE_SIZE, justifyContent: 'center', alignItems: 'center', marginBottom: SPACING.md } as ViewStyle,
  timerOverlay: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center' } as ViewStyle,
