// Sistema de sombras e elevações NOVAIX FITNESS com tipagem estrita

import { Platform, ViewStyle } from 'react-native';
import { COLORS } from './colors';

const isAndroid = Platform.OS === 'android';

export interface ShadowStyle {
  elevation?: number;
  boxShadow?: string;
}

export interface ShadowsTokens {
  sm: ShadowStyle;
  small: ShadowStyle;
  md: ShadowStyle;
  medium: ShadowStyle;
  lg: ShadowStyle;
  large: ShadowStyle;
  glow: ShadowStyle;
}

export const SHADOWS: ShadowsTokens = {
  sm: isAndroid
    ? { elevation: 2 }
    : { boxShadow: '0px 1px 2px rgba(0, 0, 0, 0.1)' },
  small: isAndroid
    ? { elevation: 2 }
    : { boxShadow: '0px 1px 2px rgba(0, 0, 0, 0.1)' },
  md: isAndroid
    ? { elevation: 4 }
    : { boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.15)' },
  medium: isAndroid
    ? { elevation: 4 }
    : { boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.15)' },
  lg: isAndroid
    ? { elevation: 8 }
    : { boxShadow: '0px 4px 8px rgba(0, 0, 0, 0.2)' },
  large: isAndroid
    ? { elevation: 8 }
    : { boxShadow: '0px 4px 8px rgba(0, 0, 0, 0.2)' },
  glow: isAndroid
    ? { elevation: 12 }
    : { boxShadow: `0px 0px 12px ${COLORS.primary}66` },
};

export function getShadows(isDark: boolean): any {
  if (isDark) return SHADOWS;
  return {
    sm: isAndroid
      ? { elevation: 1 }
      : { boxShadow: '0px 1px 3px rgba(0, 0, 0, 0.06)' },
    md: isAndroid
      ? { elevation: 3 }
      : { boxShadow: '0px 2px 6px rgba(0, 0, 0, 0.08)' },
    lg: isAndroid
      ? { elevation: 6 }
      : { boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.1)' },
    glow: isAndroid
      ? { elevation: 8 }
      : { boxShadow: `0px 0px 16px ${COLORS.primary}44` },
  };
}

// src/context/AuthContext.js
// Context para Autenticação - COM MIDDLEWARES

import { createContext, useContext, useState, useEffect } from 'react';
import { supabase } from '../config/supabase';
import { getClientIp } from '../helpers/auth';
import { validate, sanitizeString } from '../middleware/validation';
import { rateLimit } from '../middleware/rateLimit';
import { handleApiError } from '../middleware/errorHandler';

const AuthContext = createContext({});

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [session, setSession] = useState(null);
  const [onboarding, setOnboarding] = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  const loadProfile = async (userId) => {
    if (!userId) return;
    try {
      const { data } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
      setProfile(data);

      const { data: obv2 } = await supabase
        .from('onboarding_v2')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();

      setOnboarding(obv2 || {});
    } catch (err) {
      console.error('Erro ao carregar perfil:', err);
    }
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      if (session?.user) loadProfile(session.user.id);
      setLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setUser(session?.user ?? null);
      if (session?.user) loadProfile(session.user.id);
      else { setProfile(null); setOnboarding(null); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const signInWithEmail = async (email, password) => {
    const emailCheck = validate('email', email);
    if (!emailCheck.valid) throw new Error(emailCheck.error);
    
    const passCheck = validate('password', password);
    if (!passCheck.valid) throw new Error(passCheck.error);

    const rateCheck = rateLimit('login_' + email, 5, 60000);
    if (!rateCheck.allowed) throw new Error('Muitas tentativas. Aguarde ' + rateCheck.retryAfter + 's');

    const clientIp = await getClientIp();
    try {
      await supabase.rpc('check_login_rate_limit', { client_email: email });
      const { data: isBlocked } = await supabase.rpc('is_ip_blocked');
      if (isBlocked) throw new Error('Acesso bloqueado temporariamente.');
    } catch (e) {
      if (e.message.includes('bloqueado')) throw e;
    }
    try {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password });
      await supabase.from('login_attempts').insert({ ip: clientIp, email, is_successful: !error && !!data.user });
      if (error) throw error;
      return data;
    } catch (loginError) {
      await supabase.from('login_attempts').insert({ ip: clientIp, email, is_successful: false });
      throw loginError;
    }
  };

  const signUpWithEmail = async (email, password, metadata = {}) => {
    const emailCheck = validate('email', email);
    if (!emailCheck.valid) throw new Error(emailCheck.error);
    const passCheck = validate('password', password);
    if (!passCheck.valid) throw new Error(passCheck.error);
    if (metadata.name) {
      const nameCheck = validate('name', sanitizeString(metadata.name));
      if (!nameCheck.valid) throw new Error(nameCheck.error);
    }

    const signupIp = await getClientIp();
    const { data, error } = await supabase.auth.signUp({
      email, password,
      options: { data: { ...metadata, signup_ip: signupIp } },
    });
    if (error) throw error;
    if (data.user) {
      try {
        await supabase.rpc('create_profile', {
          user_id: data.user.id, user_email: data.user.email || '', user_name: sanitizeString(metadata.name || ''),
        });
      } catch (rpcError) {}
    }
    return data;
  };

  const signInWithGoogle = async () => {
    const { data, error } = await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: 'novaix://', skipBrowserRedirect: true } });
    if (error) throw error;
    return data;
  };

  const signInWithApple = async () => {
    const { data, error } = await supabase.auth.signInWithOAuth({ provider: 'apple', options: { redirectTo: 'novaix://', skipBrowserRedirect: true } });
    if (error) throw error;
    return data;
  };

  const resetPassword = async (email) => {
    const emailCheck = validate('email', email);
    if (!emailCheck.valid) throw new Error(emailCheck.error);
    const { error } = await supabase.auth.resetPasswordForEmail(email);
    if (error) throw error;
  };

  const signOut = async () => {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
    setOnboarding(null);
  };

  const saveOnboarding = async (data) => {
    setOnboarding(data);
    if (!user) return;

    const { data: existing } = await supabase
      .from('onboarding_v2')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    const row = {
      user_id: user.id,
      goal: data.goal || data.goal,
      age_range: data.age_range || data.ageRange,
      gender: data.gender,
      weight: data.weight,
      height: data.height,
      cep: data.cep,
      state: data.state,
      city: data.city,
      body_model: data.body_model || data.model,
      level: data.level,
      days_per_week: data.days_per_week || data.daysPerWeek,
      workout_location: data.workout_location || data.location,
      gym_type: data.gym_type || data.gymType,
      injuries: data.injuries || [],
      preferred_time: data.preferred_time || data.preferredTime,
      stress_sleep: data.stress_sleep || data.stressSleep,
      preferred_muscles: data.preferred_muscles || data.preferredMuscles || [],
      dietary_restrictions: data.dietary_restrictions || data.dietaryRestrictions,
      instructor_type: data.instructor_type || data.instructorType,
      notification_channels: data.notification_channels || data.notificationChannels || [],
      notification_types: data.notification_types || data.notificationTypes || [],
      referral_source: data.referral_source || data.referralSource,
      current_step: data.current_step || data.currentStep || 'completed',
      updated_at: new Date().toISOString(),
    };

    if (existing) {
      await supabase.from('onboarding_v2').update(row).eq('id', existing.id);
    } else {
      row.created_at = new Date().toISOString();
      await supabase.from('onboarding_v2').insert(row);
    }

    await supabase.from('profiles').update({ current_step: 'home' }).eq('id', user.id);
    await loadProfile(user.id);
  };

  const updateProfile = async (updates) => {
    if (!user?.id) return;
    const { error } = await supabase.from('profiles').upsert({ id: user.id, ...updates }, { onConflict: 'id' });
    if (error) throw error;
    await loadProfile(user.id);
  };

  return (
    <AuthContext.Provider value={{
      user, session, onboarding, profile, loading,
      signInWithEmail, signUpWithEmail, signInWithGoogle, signInWithApple,
      resetPassword, signOut, saveOnboarding, loadProfile, updateProfile,
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth deve ser usado dentro de um AuthProvider');
  return context;
}

import { createContext, useContext, useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useColorScheme } from 'react-native';
import { COLORS, THEMES, setThemeColors } from '../constants/colors';
import { useAuth } from './AuthContext';
import { supabase } from '../config/supabase';
import { updateWebStyles } from '../components/common/WebStyles';

function getTimeBasedTheme(hour) {
  if (hour >= 0 && hour < 7) return 'dark';
  if (hour >= 7 && hour < 18) return 'light';
  return 'dark';
}

const ThemeContext = createContext({
  colors: COLORS,
  isDark: true,
  themeMode: 'dark',
  setThemeMode: () => {},
  isAutoMode: false,
  toggleAutoMode: () => {},
  nextSwitchHour: 7,
});

export function ThemeProvider({ children }) {
  const { user, profile } = useAuth();
  const systemScheme = useColorScheme();
  const [themeMode, setThemeModeState] = useState('dark');
  const [colors, setColors] = useState({ ...COLORS });
  const [isAutoMode, setIsAutoMode] = useState(false);
  const autoTimerRef = useRef(null);
  const lastAppliedRef = useRef(null);

  const applyAutoTheme = useCallback(() => {
    const hour = new Date().getHours();
    const target = getTimeBasedTheme(hour);
    if (lastAppliedRef.current !== target) {
      lastAppliedRef.current = target;
      setThemeModeState(target);
    }
  }, []);

  const toggleAutoMode = useCallback(async () => {
    setIsAutoMode(prev => {
      const next = !prev;
      if (next) {
        applyAutoTheme();
        autoTimerRef.current = setInterval(applyAutoTheme, 60000);
      } else if (autoTimerRef.current) {
        clearInterval(autoTimerRef.current);
        autoTimerRef.current = null;
      }
      return next;
    });
  }, [applyAutoTheme]);

  useEffect(() => {
    return () => { if (autoTimerRef.current) clearInterval(autoTimerRef.current); };
  }, []);

  const resolvedTheme = useMemo(() => {
    if (isAutoMode) {
      const hour = new Date().getHours();
      return getTimeBasedTheme(hour);
    }
    if (themeMode === 'system') return systemScheme || 'dark';
    return themeMode;
  }, [themeMode, systemScheme, isAutoMode]);

  useEffect(() => {
    const source = THEMES[resolvedTheme] || THEMES.dark;
    setColors({ ...source });
    setThemeColors(resolvedTheme);
    updateWebStyles();
  }, [resolvedTheme]);

  useEffect(() => {
    if (profile?.app_settings?.themeMode) {
      setThemeModeState(profile.app_settings.themeMode);
    } else if (profile?.app_settings?.darkMode === false) {
      setThemeModeState('light');
    }
  }, [profile?.app_settings]);

  const setThemeMode = useCallback(async (mode) => {
    setThemeModeState(mode);
    if (user?.id) {
      await supabase
        .from('profiles')
        .update({ app_settings: { ...profile?.app_settings, themeMode: mode, darkMode: mode === 'dark' } })
        .eq('id', user.id);
    }
  }, [user?.id, profile?.app_settings]);

  const toggleTheme = useCallback(() => {
    const cycle = ['auto', 'dark', 'light'];
    const idx = cycle.indexOf(themeMode);
    const next = cycle[(idx + 1) % cycle.length];
    if (next === 'auto') {
      setIsAutoMode(true);
      applyAutoTheme();
      autoTimerRef.current = setInterval(applyAutoTheme, 60000);
      setThemeMode('dark');
    } else {
      if (autoTimerRef.current) {
        clearInterval(autoTimerRef.current);
        autoTimerRef.current = null;
      }
      setIsAutoMode(false);
      setThemeMode(next);
    }
  }, [themeMode, setThemeMode, applyAutoTheme]);

  const value = useMemo(() => ({
    colors,
    isDark: resolvedTheme === 'dark',
    themeMode,
    setThemeMode,
    toggleTheme,
    isAutoMode,
    toggleAutoMode,
    nextSwitchHour: new Date().getHours() < 7 ? 7 : new Date().getHours() < 18 ? 18 : 7,
  }), [colors, resolvedTheme, themeMode, setThemeMode, toggleTheme, isAutoMode, toggleAutoMode]);

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}

