// Hook para lógica do Coach IA

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Alert } from 'react-native';
import { supabase } from '../config/supabase';
import { askGeminiCoach, saveChatMessage, getChatHistory, clearChatHistory } from '../services/gemini';
import { analyzeMealText, saveMealLog } from '../services/mealAnalyzer';
import { detectMealLog, formatMealSummary } from '../helpers/chatHelpers';
import { buildChatContext, createWelcomeMessage, createCoachMessage, createUserMessage, cleanupLimitExceededMessage } from './helpers/chatHelpers';
import { Profile } from '../types';

interface ChatMsg {
  id: string;
  text: string;
  isUser: boolean;
  timestamp?: string;
  [key: string]: unknown;
}

interface Router {
  back: () => void;
  push: (url: string) => void;
  [key: string]: unknown;
}

interface SupabaseUser {
  id: string;
  [key: string]: unknown;
}

interface UseChatCoachReturn {
  messages: any[];
  inputText: string;
  setInputText: (val: string) => void;
  loading: boolean;
  historyLoaded: boolean;
  flatListRef: React.RefObject<unknown>;
  handleSend: (text?: string) => Promise<void>;
  handleClearChat: () => void;
}

export function useChatCoach(user: SupabaseUser | null, router: Router): UseChatCoachReturn {
  const [messages, setMessages] = useState<any[]>([]);
  const [inputText, setInputText] = useState<string>('');
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [historyLoaded, setHistoryLoaded] = useState<boolean>(false);
  const flatListRef = useRef<unknown>(null);

  useEffect(() => {
    async function init(): Promise<void> {
      if (!user?.id) return;
      try {
        const { data } = await supabase.from('profiles').select('*').eq('id', user.id).single();
        if (data) {
          setProfile(data as Profile);
          const isAllowedPlan = ['intermediate', 'premium', 'ultra'].includes(data.subscription_plan);
          const hasActiveSub = data.subscription_status === 'active';
          if (!isAllowedPlan || !hasActiveSub) {
            Alert.alert(
              'Acesso Restrito',
              'O Coach IA esta disponivel apenas para assinantes dos planos Intermediario, Premium e Ultra Premium com assinatura ativa.',
              [
                { text: 'Voltar', onPress: () => router.back() },
                { text: 'Ver Planos', onPress: () => { router.back(); router.push('/paywall'); } },
              ],
              { cancelable: false },
            );
            return;
          }
        }
        const history = await getChatHistory(user.id);
        if (history.length > 0) {
          setMessages(history);
        } else {
          const welcome = createWelcomeMessage(data?.name || 'Atleta');
          setMessages([welcome]);
          await saveChatMessage(user.id, welcome.text, false);
        }
      } catch (err) {
        if (__DEV__) console.error('Erro ao carregar chat:', err);
      } finally {
        setHistoryLoaded(true);
      }
    }
    init();
  }, [user?.id]);

  const handleSend = useCallback(async (text?: string): Promise<void> => {
    const msg = (text || inputText).trim();
    if (!msg || loading) return;
    setInputText('');
    const userMsg = createUserMessage(msg);
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);
    await saveChatMessage(user.id, msg, true);

    if (detectMealLog(msg)) {
      try {
        const context = buildChatContext(profile);
        (context as any).userId = user.id;
        const mealData = await analyzeMealText(msg, context);
        if (mealData) {
          await saveMealLog(user.id, mealData);
          const summary = formatMealSummary(mealData);
          const coachMsg = createCoachMessage(summary, { isMealCard: true, mealData });
          setMessages(prev => [...prev, coachMsg]);
          await saveChatMessage(user.id, summary, false);
          setLoading(false);
          return;
        }
      } catch (e) { if (__DEV__) console.warn('useChatCoach mealLog:', e); }
    }

    try {
      const context = buildChatContext(profile);
      (context as any).userId = user.id;
      const reply = await askGeminiCoach(msg, context, messages);
      setMessages(prev => [...prev, createCoachMessage(reply)]);
      await saveChatMessage(user.id, reply, false);
    } catch (err) {
      if ((err as Error).message === 'LIMIT_EXCEEDED') {
        setMessages(prev => prev.filter(m => m.id !== userMsg.id));
        await cleanupLimitExceededMessage(user, msg, supabase);
        Alert.alert('Limite Excedido', 'Voce atingiu seu limite diario de mensagens do Coach IA. Faca um upgrade para enviar mais mensagens!', [
          { text: 'OK' },
          { text: 'Ver Planos', onPress: () => router.push('/paywall') },
        ]);
      } else if ((err as Error).message === 'API_KEY_MISSING') {
        setMessages(prev => [...prev, createCoachMessage('Configure a chave de API do Google para usar o Coach IA.')]);
      } else {
        setMessages(prev => [...prev, createCoachMessage('Erro ao conectar com o assistente. Verifique sua conexao e tente novamente.')]);
        if (__DEV__) console.error('Erro ao enviar mensagem:', err);
      }
    } finally {
      setLoading(false);
    }
  }, [user?.id, inputText, loading, profile, messages, router]);

  const handleClearChat = useCallback((): void => {
    Alert.alert('Limpar historico', 'Apagar todas as mensagens?', [
      { text: 'Cancelar', style: 'cancel' },
      {
        text: 'Limpar', style: 'destructive',
        onPress: async () => {
          await clearChatHistory(user.id);
          const welcome = createWelcomeMessage('Historico limpo!');
          welcome.text = 'Historico limpo! Em como posso ajudar?';
          setMessages([welcome]);
          await saveChatMessage(user.id, welcome.text, false);
        },
      },
    ]);
  }, [user?.id]);

  return { messages, inputText, setInputText, loading, historyLoaded, flatListRef, handleSend, handleClearChat };
}

// Hook de gamificação - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import {
  awardXP,
  checkAchievements,
  getRankings,
  getUserRank,
  getUserAchievements,
  calculateLevel,
  getXPForNextLevel,
  getLevelProgress,
  getUserGamificationProfile,
} from '../services/gamification';
import { Achievement } from '../types';

interface GamificationProfile {
  xp: number;
  [key: string]: unknown;
}

interface UserRank {
  rank: number;
  [key: string]: unknown;
}

interface AwardResult {
  xpGained?: number;
  [key: string]: unknown;
}

interface UseGamificationReturn {
  profile: GamificationProfile | null;
  achievements: Achievement[];
  rankings: unknown[];
  userRank: UserRank | null;
  loading: boolean;
  award: (eventType: string, metadata?: Record<string, unknown>) => Promise<AwardResult | null>;
  refresh: () => void;
  level: number;
  xpForNext: number;
  levelProgress: number;
  data?: GamificationProfile | null;
  refreshing?: boolean;
  error?: string | null;
  onRefresh?: () => void;
}

interface UseAchievementsReturn {
  achievements: Achievement[];
  loading: boolean;
}

interface UseRankingsReturn {
  rankings: unknown[];
  loading: boolean;
}

export function useGamification(): UseGamificationReturn {
  const { user } = useAuth();
  const [profile, setProfile] = useState<GamificationProfile | null>(null);
  const [achievements, setAchievements] = useState<Achievement[]>([]);
  const [rankings, setRankings] = useState<unknown[]>([]);
  const [userRank, setUserRank] = useState<UserRank | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (!user?.id) return;
    loadData();
  }, [user?.id]);

  async function loadData(): Promise<void> {
    setLoading(true);
    try {
      const [rankData, achievementsData, rank, profileData] = await Promise.all([
        getRankings('weekly'),
        getUserAchievements(user.id),
        getUserRank(user.id),
        getUserGamificationProfile(user.id),
      ]);
      setRankings(rankData);
      setAchievements(achievementsData as any);
      setUserRank(rank);
      setProfile(profileData);
    } catch (err) {
      if (__DEV__) console.warn('Erro ao carregar gamificacao:', err);
    }
    setLoading(false);
  }

  const award = useCallback(async (eventType: string, metadata: Record<string, unknown> = {}): Promise<AwardResult | null> => {
    if (!user?.id) return null;
    const result = await awardXP(user.id, eventType, metadata);
    const newAchievements = await checkAchievements(user.id);
    if (newAchievements.length > 0) {
      setAchievements(prev => [...prev, ...newAchievements.map((a: any) => ({ ...a, unlocked: true }))]);
    }
    return result;
  }, [user?.id]);

  const refresh = useCallback((): void => { loadData(); }, [user?.id]);

  return {
    profile,
    achievements,
    rankings,
    userRank,
    loading,
    award,
    refresh,
    level: calculateLevel(profile?.xp || 0),
    xpForNext: getXPForNextLevel(profile?.xp || 0),
    levelProgress: getLevelProgress(profile?.xp || 0),
  };
}

export function useAchievements(): UseAchievementsReturn {
  const { user } = useAuth();
  const [achievements, setAchievements] = useState<Achievement[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    if (!user?.id) return;
    getUserAchievements(user.id)
      .then(data => setAchievements(data as any))
      .catch((err) => { if (__DEV__) console.error('Erro ao carregar conquistas:', err); })
      .finally(() => setLoading(false));
  }, [user?.id]);

  return { achievements, loading };
}

export function useRankings(period: string = 'weekly'): UseRankingsReturn {
  const [rankings, setRankings] = useState<unknown[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    setLoading(true);
    getRankings(period)
      .then(setRankings)
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [period]);

  return { rankings, loading };
}

