// Hook com fallback para dados mock - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../config/supabase';

interface Filter {
  column: string;
  value: string | number | boolean;
  op?: 'eq' | 'ilike';
}

interface OrderBy {
  column: string;
  ascending?: boolean;
}

interface SupabaseDataOptions {
  select?: string;
  filters?: Filter[];
  orderBy?: OrderBy | null;
  limit?: number | null;
  mockData?: unknown[];
}

export function useSupabaseData(tableName: string, options: SupabaseDataOptions = {}) {
  const { select = '*', filters = [], orderBy = null, limit = null, mockData = [] } = options;
  const [data, setData] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isConnected, setIsConnected] = useState(false);

  const filtersKey = JSON.stringify(filters);
  const orderByKey = JSON.stringify(orderBy);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const { error: pingError } = await supabase.from(tableName).select('id').limit(1);

      if (pingError) {
        setIsConnected(false);
        setData(mockData);
        return;
      }

      setIsConnected(true);

      let query = supabase.from(tableName).select(select);

      filters.forEach(({ column, value, op = 'eq' }) => {
        query = op === 'eq' ? query.eq(column, value) : query.ilike(column, `%${value}%`);
      });

      if (orderBy) query = query.order(orderBy.column, { ascending: orderBy.ascending ?? false });
      if (limit) query = query.limit(limit);

      const { data: result, error: fetchError } = await query;

      if (fetchError) throw fetchError;
      setData(result || []);
    } catch (err) {
      console.error(`Erro ao buscar ${tableName}:`, err);
      setError(err instanceof Error ? err.message : 'Erro desconhecido');
      setData(mockData);
    } finally {
      setLoading(false);
    }
  }, [tableName, select, filtersKey, orderByKey, limit]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const insert = async (record: Record<string, unknown>) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { data: result, error } = await supabase
        .from(tableName)
        .insert(record)
        .select()
        .single();

      if (error) throw error;
      fetchData();
      return { data: result };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro desconhecido' };
    }
  };

  const update = async (id: string, updates: Record<string, unknown>) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { data: result, error } = await supabase
        .from(tableName)
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      fetchData();
      return { data: result };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro desconhecido' };
    }
  };

  const remove = async (id: string) => {
    if (!isConnected) return { error: 'Sem conexão' };

    try {
      const { error } = await supabase
        .from(tableName)
        .delete()
        .eq('id', id);

      if (error) throw error;
      fetchData();
      return { success: true };
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'Erro desconhecido' };
    }
  };

  return { data, loading, error, isConnected, refetch: fetchData, insert, update, remove };
}

// Hook de lógica para Detalhe do Treino - NOVAIX FITNESS

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Alert } from 'react-native';
import { supabase } from '../config/supabase';
import { useAuth } from '../context/AuthContext';
import { shareWorkout } from '../services/share';
import { cacheWorkoutDetail, getCachedWorkoutDetail, isWorkoutCached } from '../services/offline';
import { queueFavoriteAction } from '../services/offlineManager';
import useNetworkStatus from './useNetworkStatus';
import { fallbackWorkout } from '../data/workouts';
import { Workout, Exercise, Profile } from '../types';

interface Router {
  push: (url: { pathname: string; params?: Record<string, string> }) => void;
  back: () => void;
  [key: string]: unknown;
}

interface UseWorkoutDetailReturn {
  workout: Workout | null;
  profile: Profile | null;
  loading: boolean;
  expanded: number | null;
  setExpanded: (val: number | null) => void;
  showVideo: boolean;
  setShowVideo: (val: boolean) => void;
  isFavorite: boolean;
  showOptions: boolean;
  setShowOptions: (val: boolean) => void;
  showRating: boolean;
  setShowRating: (val: boolean) => void;
  isOffline: boolean;
  isOnline: boolean;
  exercises: Exercise[];
  totalSets: number;
  toggleFavorite: () => Promise<void>;
  handleOption: (opt: string) => Promise<void>;
  handleStart: (router: Router) => Promise<void>;
  handleRating: (data: { rating: number; comment: string }) => Promise<void>;
}

export function useWorkoutDetail(id: string): UseWorkoutDetailReturn {
  const { user } = useAuth();
  const [workout, setWorkout] = useState<Workout | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [expanded, setExpanded] = useState<number | null>(null);
  const [showVideo, setShowVideo] = useState<boolean>(false);
  const [isFavorite, setIsFavorite] = useState<boolean>(false);
  const [showOptions, setShowOptions] = useState<boolean>(false);
  const [showRating, setShowRating] = useState<boolean>(false);
  const [isOffline, setIsOffline] = useState<boolean>(false);
  const { isOnline } = useNetworkStatus();

  useEffect(() => {
    if (!id) return;
    async function loadWorkoutDetail() {
      try {
        const { data, error } = await supabase.from('workouts').select('*').eq('id', id).single();
        const w = error || !data ? null : (data as Workout);
        if (w) {
          setWorkout(w);
          await cacheWorkoutDetail(w);
        } else {
          const cached = await getCachedWorkoutDetail(id);
          if (cached) setWorkout(cached as Workout);
        }
      } catch {
        const cached = await getCachedWorkoutDetail(id);
        if (cached) setWorkout(cached as Workout);
      } finally {
        setLoading(false);
      }
    }
    loadWorkoutDetail();
    isWorkoutCached(id).then(setIsOffline);
  }, [id]);

  useEffect(() => {
    if (!user?.id) return;
    async function loadUserData() {
      try {
        const { data } = await supabase.from('profiles').select('subscription_status').eq('id', user.id!).single();
        if (data) setProfile(data as Profile);
      } catch {}
      
      if (id) {
        try {
          const { data } = await supabase.from('favorites').select('id').eq('user_id', user.id!).eq('workout_id', id).single();
          setIsFavorite(!!data);
        } catch {}
      }
    }
    loadUserData();
  }, [user?.id, id]);

  const toggleFavorite = useCallback(async (): Promise<void> => {
    if (!user?.id || !id) return;
    try {
      if (isOnline) {
        if (isFavorite) await supabase.from('favorites').delete().eq('user_id', user.id).eq('workout_id', id);
        else await supabase.from('favorites').insert({ user_id: user.id, workout_id: id });
      } else {
        await queueFavoriteAction(user.id, id, !isFavorite);
      }
      setIsFavorite(!isFavorite);
    } catch { Alert.alert('Erro', 'Falha ao atualizar favorito'); }
  }, [user?.id, id, isFavorite, isOnline]);

  const handleOption = useCallback(async (opt: string): Promise<void> => {
    setShowOptions(false);
    if (opt === 'share') shareWorkout(workout);
    if (opt === 'rate') return setShowRating(true);
    if (opt === 'save') {
      await cacheWorkoutDetail(workout);
      setIsOffline(true);
      Alert.alert('Salvo', 'Treino disponível offline');
    }
  }, [workout]);

  const handleStart = useCallback(async (router: Router): Promise<void> => {
    if (!user?.id || !id) return;
    const isSubscribed = profile?.subscription_status === 'premium' || profile?.subscription_status === 'active';
    const isLocked = ((workout as any)?.is_premium || false) && !isSubscribed;
    if (isLocked) {
      Alert.alert('Conteúdo Premium 🔒', 'Este treino é exclusivo para assinantes Premium.',
        [{ text: 'Mais tarde', style: 'cancel' }, { text: 'Ver Planos', onPress: () => router.push({ pathname: '/paywall' }) }]);
      return;
    }
    try {
      const { data } = await supabase.from('user_workouts').insert({
        user_id: user.id, workout_id: id, completed: false,
        duration: workout?.duration_minutes || workout?.duration || 0,
      }).select('id').single();
      router.push({ pathname: '/player', params: { id, user_workout_id: data?.id } });
    } catch { router.push({ pathname: '/player', params: { id } }); }
  }, [user?.id, id, workout, profile]);

  const handleRating = useCallback(async ({ rating, comment }: { rating: number; comment: string }): Promise<void> => {
    if (!user?.id || !id) return;
    try {
      await supabase.from('user_workouts').upsert(
        { user_id: user.id, workout_id: id, rating, notes: comment },
        { onConflict: 'user_id,workout_id' }
      );
      Alert.alert('Obrigado!', 'Avaliação registrada.');
    } catch { Alert.alert('Erro', 'Falha ao salvar.'); }
  }, [user?.id, id]);

  const exercises: Exercise[] = workout?.exercises || [];
  const totalSets: number = useMemo(() => exercises.reduce((sum, ex) => sum + (ex.sets || 0), 0), [exercises]);

  return {
    workout, profile, loading, expanded, setExpanded,
    showVideo, setShowVideo, isFavorite, showOptions, setShowOptions,
    showRating, setShowRating, isOffline, isOnline, exercises, totalSets,
    toggleFavorite, handleOption, handleStart, handleRating,
  };
}

// Hook de lógica do player de treino - NOVAIX FITNESS

import { useState, useEffect, useCallback, useRef } from 'react';
import { Alert } from 'react-native';
import { useRouter, useLocalSearchParams } from 'expo-router';
import * as KeepAwake from 'expo-keep-awake';
import { saveCompleteWorkout } from '../services/workoutSaver';
import { shareWorkout } from '../services/share';
import { awardXP } from '../services/gamification';
import { loadSounds, unloadSounds } from '../services/audioService';
import { isVoiceCoachEnabled, setVoiceCoachEnabled } from '../services/voiceCoach';
import { queueWorkoutCompletion } from '../services/offlineManager';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../config/supabase';
import useNetworkStatus from './useNetworkStatus';
import useWorkoutTimer from './useWorkoutTimer';
import { useTutorial } from './useTutorial';
import { DEMO_WORKOUT } from '../data/workouts';
import { Workout } from '../types';

interface RatingData {
  rating: number;
  comment: string;
}

interface GamResult {
  xpGained?: number;
  newAchievements?: { name: string }[];
}

interface UseWorkoutPlayerReturn {
  workout: Workout | null;
  loading: boolean;
  showRating: boolean;
  voiceEnabled: boolean;
  showXP: boolean;
  xpAmount: number;
  tutorialVisible: boolean;
  tutorialSteps: unknown[];
  handleComplete: () => void;
  handleSkip: () => void;
  timer: ReturnType<typeof useWorkoutTimer>;
  handleWorkoutComplete: () => Promise<void>;
  handleRatingSubmit: (data: RatingData) => Promise<void>;
  handleFinish: () => void;
  toggleVoiceCoach: () => void;
  dismissRating: () => void;
  setShowXP: (val: boolean) => void;
  showCompletion: boolean;
  setShowCompletion: (val: boolean) => void;
}

export default function useWorkoutPlayer(): UseWorkoutPlayerReturn {
  const router = useRouter();
  const params = useLocalSearchParams<{ id?: string }>();
  const { user } = useAuth();
  const [workout, setWorkout] = useState<Workout | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [showRating, setShowRating] = useState<boolean>(false);
  const [showCompletion, setShowCompletion] = useState<boolean>(false);
  const [voiceEnabled, setVoiceEnabled] = useState<boolean>(isVoiceCoachEnabled());
  const [showXP, setShowXP] = useState<boolean>(false);
  const [xpAmount, setXpAmount] = useState<number>(0);
  const { visible: tutorialVisible, steps: tutorialSteps, handleComplete, handleSkip } = useTutorial('player', true);
  const { isOnline } = useNetworkStatus();
  const timer = useWorkoutTimer(workout);
  const gamRef = useRef<GamResult | null>(null);

  useEffect(() => {
    KeepAwake.activateKeepAwakeAsync();
    loadSounds();
    return () => { KeepAwake.deactivateKeepAwake(); unloadSounds(); };
  }, []);

  useEffect(() => {
    if (!params.id) { setWorkout(DEMO_WORKOUT as Workout); setLoading(false); return; }
    
    async function fetchWorkout() {
      try {
        const { data } = await supabase.from('workouts').select('*, exercises(*)').eq('id', params.id).single();
        setWorkout(data ? {
          id: data.id, name: data.title || data.name,
          duration: data.duration_minutes || data.duration || 30,
          videoId: data.video_id || 'dQw4w9WgXcQ',
          exercises: data.exercises || DEMO_WORKOUT.exercises,
        } as Workout : DEMO_WORKOUT as Workout);
      } catch {
        setWorkout(DEMO_WORKOUT as Workout);
      } finally {
        setLoading(false);
      }
    }
    
    fetchWorkout();
  }, [params.id]);

  const handleWorkoutComplete = useCallback(async (): Promise<void> => {
    const mappedLogs = timer.logs.map(log => ({
      exercise_name: log.exercise?.name || '',
      sets_done: log.setNumber,
      reps_done: (log.reps as number) || 0,
      weight_kg: (log.weight as number) || 0,
    }));

    if (!isOnline && user?.id && workout?.id) {
      await queueWorkoutCompletion(user.id, workout.id, mappedLogs, timer.elapsed);
      Alert.alert('Salvo offline', 'Treino sera sincronizado quando voce estiver online.');
      timer.stopWorkout();
      router.back();
      return;
    }
    gamRef.current = await saveCompleteWorkout(user?.id, workout, mappedLogs, timer.elapsed);
    if (gamRef.current?.xpGained && gamRef.current.xpGained > 0) { setXpAmount(gamRef.current.xpGained); setShowXP(true); }
    setShowRating(true);
  }, [isOnline, user, workout, timer, router]);

  const handleRatingSubmit = useCallback(async ({ rating, comment }: RatingData): Promise<void> => {
    if (user?.id && workout?.id) {
      try {
        await supabase.from('user_workouts').upsert(
          { user_id: user.id, workout_id: workout.id, rating, notes: comment },
          { onConflict: 'user_id,workout_id' }
        );
      } catch {}
    }
    if (user?.id) await awardXP(user.id, 'WORKOUT_RATED');
    setShowRating(false);
    setShowCompletion(true);
  }, [user, workout]);

  useEffect(() => {
    if (timer.phase === 'completed') handleWorkoutComplete();
  }, [timer.phase, handleWorkoutComplete]);

  const handleFinish = useCallback((): void => {
    Alert.alert('Finalizar', 'Salvar progresso e sair?', [
      { text: 'Cancelar', style: 'cancel' },
      { text: 'Finalizar', style: 'destructive', onPress: handleWorkoutComplete },
    ]);
  }, [handleWorkoutComplete]);

  const toggleVoiceCoach = useCallback((): void => {
    const v = !voiceEnabled;
    setVoiceEnabled(v);
    setVoiceCoachEnabled(v);
  }, [voiceEnabled]);

  const dismissRating = useCallback((): void => {
    setShowRating(false);
    timer.stopWorkout();
    router.back();
  }, [timer, router]);

  return {
    workout, loading, showRating, voiceEnabled, showXP, xpAmount,
    tutorialVisible, tutorialSteps, handleComplete, handleSkip,
    timer, handleWorkoutComplete, handleRatingSubmit, handleFinish,
    toggleVoiceCoach, dismissRating, setShowXP,
    showCompletion, setShowCompletion,
  };
}

// src/hooks/useWorkoutTimer.ts
// Hook de maquina de estados do timer de treino - NOVAIX FITNESS

import { useState, useEffect, useRef, useCallback } from 'react';
import { countdownTick, phaseChange, workoutComplete } from '../services/hapticService';
import { playCountdownTick, playPhaseEnd, playWorkoutComplete } from '../services/audioService';
import { speakWelcome, speakNextExercise, speakRestStart, speakHalfway, speakWorkoutComplete, stopSpeaking } from '../services/voiceCoach';
import { Workout } from '../types';

interface WorkoutLog {
  exerciseIndex: number;
  exerciseName: string;
  set: number;
  reps: number;
  weight: number;
  timestamp: number;
}

export default function useWorkoutTimer(workout: Workout | null) {
  const [phase, setPhase] = useState('idle');
  const [currentExerciseIndex, setCurrentExerciseIndex] = useState(0);
  const [currentSet, setCurrentSet] = useState(1);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [logs, setLogs] = useState<WorkoutLog[]>([]);

  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const phaseRef = useRef(phase);
  const exerciseRef = useRef(currentExerciseIndex);
  const setRef = useRef(currentSet);

  const exercises = workout?.exercises || [];
  const currentExercise = exercises[currentExerciseIndex];
  const totalExercises = exercises.length;
  const totalSets = currentExercise?.sets || 4;

  useEffect(() => {
    phaseRef.current = phase;
    exerciseRef.current = currentExerciseIndex;
    setRef.current = currentSet;
  }, [phase, currentExerciseIndex, currentSet]);

  const completeWorkout = useCallback(async () => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    await playWorkoutComplete();
    await workoutComplete();
    speakWorkoutComplete(workout?.name);
    setPhase('completed');
  }, [workout]);

  const startExercise = useCallback(() => {
    const idx = exerciseRef.current;
    const exercises = workout?.exercises || [];
    const exercise = exercises[idx];
    if (!exercise) { completeWorkout(); return; }
    setTimeRemaining(0);
    setTotalTime(0);
    setPhase('exercising');
    speakNextExercise(exercise.name, exercise.reps, exercise.weight, idx + 1, exercises.length);
  }, [workout, completeWorkout]);

  const handlePhaseComplete = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    if (phaseRef.current === 'resting') {
      playPhaseEnd();
      phaseChange();
      startExercise();
    } else if (phaseRef.current === 'exercising') {
      playPhaseEnd();
      phaseChange();
    }
  }, [startExercise]);

  const startWorkout = useCallback(() => {
    setCurrentExerciseIndex(0);
    setCurrentSet(1);
    setElapsed(0);
    setLogs([]);
    setPhase('exercising');
    setTimeRemaining(0);
    setTotalTime(0);
    speakWelcome(workout?.name);
  }, [workout]);

  const pauseWorkout = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    setPhase('paused');
  }, []);

  const resumeWorkout = useCallback(() => {
    setPhase(phaseRef.current === 'paused' ? 'exercising' : phaseRef.current);
  }, []);

  const markSetComplete = useCallback((setLog: { reps?: number; weight?: number }) => {
    const exercise = exercises[exerciseRef.current];
    const log: WorkoutLog = {
      exerciseIndex: exerciseRef.current,
      exerciseName: exercise?.name || '',
      set: setRef.current,
      reps: setLog?.reps ?? 0,
      weight: setLog?.weight ?? 0,
      timestamp: Date.now(),
    };
    setLogs((prev) => [...prev, log]);
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    const totalSets = exercise?.sets || 4;
    if (setRef.current < totalSets) {
      setCurrentSet((prev) => prev + 1);
      const restTime = exercise?.rest || 60;
      setTimeRemaining(restTime);
      setTotalTime(restTime);
      setPhase('resting');
    } else {
      const nextIndex = exerciseRef.current + 1;
      if (nextIndex < exercises.length) {
        if (nextIndex === Math.floor(exercises.length / 2)) {
          speakHalfway();
        }
        setCurrentExerciseIndex(nextIndex);
        setCurrentSet(1);
        const nextExercise = exercises[nextIndex];
        const restTime = nextExercise?.rest || 60;
        setTimeRemaining(restTime);
        setTotalTime(restTime);
        setPhase('resting');
      } else {
        completeWorkout();
      }
    }
  }, [workout, exercises, completeWorkout]);

  const skipRest = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    startExercise();
  }, [startExercise]);

  const skipExercise = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    const nextIndex = exerciseRef.current + 1;
    if (nextIndex < exercises.length) {
      setCurrentExerciseIndex(nextIndex);
      setCurrentSet(1);
      const nextExercise = exercises[nextIndex];
      const restTime = nextExercise?.rest || 60;
      setTimeRemaining(restTime);
      setTotalTime(restTime);
      setPhase('resting');
    } else {
      completeWorkout();
    }
  }, [workout, exercises, completeWorkout]);

  const stopWorkout = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    stopSpeaking();
    setPhase('idle');
    setCurrentExerciseIndex(0);
    setCurrentSet(1);
    setTimeRemaining(0);
    setTotalTime(0);
  }, []);

  useEffect(() => {
    if (phase === 'exercising' || phase === 'resting') {
      intervalRef.current = setInterval(() => {
        setTimeRemaining((prev) => {
          if (prev <= 1) { handlePhaseComplete(); return 0; }
          if (phaseRef.current === 'resting' && prev <= 4 && prev > 1) {
            countdownTick(prev - 1);
            playCountdownTick();
          }
          return prev - 1;
        });
        setElapsed((prev) => prev + 1);
      }, 1000);
    }
    return () => {
      if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    };
  }, [phase, handlePhaseComplete]);

  const exerciseProgress = totalExercises > 0 ? (currentExerciseIndex / totalExercises) * 100 : 0;
  const setProgress = totalSets > 0 ? ((currentSet - 1) / totalSets) * 100 : 0;
  const timerProgress = totalTime > 0 ? ((totalTime - timeRemaining) / totalTime) * 100 : 0;
  const totalXP = logs.length * 5 + currentExerciseIndex * 10 + Math.floor(elapsed / 60) * 2;

  return {
    phase, currentExercise, currentExerciseIndex, currentSet, totalSets, totalExercises,
    timeRemaining, totalTime, elapsed, logs, exerciseProgress, setProgress, timerProgress, totalXP,
    startWorkout, pauseWorkout, resumeWorkout, markSetComplete, skipRest, skipExercise, stopWorkout, completeWorkout,
  };
}

