// React Context para uso nos componentes

import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { TranslationEngine } from './TranslationEngine';
import { ensureModel, isModelCached } from './ModelManager';
import { getModelConfig } from './models-config';
import { startBatteryMonitoring, getDebounceDelay } from './batteryAware';

const LOCALE_KEY = '@novaix:locale';

interface TranslationContextValue {
  locale: string;
  setLocale: (locale: string) => Promise<void>;
  t: (text: string, params?: Record<string, string | number>) => string;
  translateText: (text: string) => Promise<string>;
  isModelLoaded: boolean;
  isLoadingModel: boolean;
  downloadProgress: number;
  isLowPower: boolean;
}

const TranslationContext = createContext<TranslationContextValue | null>(null);

export function TranslationProvider({ children, initialLocale = 'pt' }: {
  children: React.ReactNode;
  initialLocale?: string;
}) {
  const [locale, setLocaleState] = useState(initialLocale);
  const [isModelLoaded, setIsModelLoaded] = useState(false);
  const [isLoadingModel, setIsLoadingModel] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);
  const [isLowPower, setIsLowPower] = useState(false);
  const engineRef = useRef<TranslationEngine | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Carregar idioma salvo
  useEffect(() => {
    AsyncStorage.getItem(LOCALE_KEY).then(saved => {
      if (saved) setLocaleState(saved);
    });
  }, []);

  // Monitorar bateria
  useEffect(() => {
    const unsub = startBatteryMonitoring((state) => {
      setIsLowPower(state.isLowPowerMode || state.level < 0.05);
    });
    return unsub;
  }, []);

  // Carregar modelo quando idioma muda
  useEffect(() => {
    if (locale === 'pt') {
      // PT é o idioma base, não precisa de modelo
      setIsModelLoaded(true);
      return;
    }

    loadModel(locale);
  }, [locale]);

  const loadModel = async (targetLocale: string) => {
    const config = getModelConfig('pt', targetLocale);
    if (!config) {
      console.warn(`[ML] Modelo pt-${targetLocale} não encontrado`);
      return;
    }

    setIsLoadingModel(true);
    setDownloadProgress(0);

    try {
      // Baixar modelo (encoder + decoder + tokenizer)
      const paths = await ensureModel(config, setDownloadProgress);

      // Inicializar engine
      if (!engineRef.current) {
        engineRef.current = new TranslationEngine();
      }
      await engineRef.current.initialize(paths, config);
      setIsModelLoaded(true);
    } catch (error) {
      console.error('[ML] Erro ao carregar modelo:', error);
    } finally {
      setIsLoadingModel(false);
      setDownloadProgress(0);
    }
  };

  const setLocale = useCallback(async (newLocale: string) => {
    setLocaleState(newLocale);
    await AsyncStorage.setItem(LOCALE_KEY, newLocale);
  }, []);

  // Função t() - traduz texto
  const t = useCallback((text: string, params?: Record<string, string | number>): string => {
    // Se locale é PT, retornar texto original
    if (locale === 'pt') {
      if (params) {
        return Object.entries(params).reduce(
          (str, [key, val]) => str.replace(`{${key}}`, String(val)),
          text
        );
      }
      return text;
    }

    // Em produção, usar cache de traduções para strings estáticas
    // Por agora, retornar texto original (placeholder para ONNX)
    if (params) {
      return Object.entries(params).reduce(
        (str, [key, val]) => str.replace(`{${key}}`, String(val)),
        text
      );
    }
    return text;
  }, [locale]);

  // Tradução de texto livre
  const translateText = useCallback(async (text: string): Promise<string> => {
    if (locale === 'pt' || !engineRef.current) return text;

    try {
      return await engineRef.current.translate(text, 'pt', locale);
    } catch (error) {
      console.error('[ML] Erro na tradução:', error);
      return text;
    }
  }, [locale]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
      engineRef.current?.dispose();
    };
  }, []);

  return (
    <TranslationContext.Provider value={{
      locale,
      setLocale,
      t,
      translateText,
      isModelLoaded,
      isLoadingModel,
      downloadProgress,
      isLowPower,
    }}>
      {children}
    </TranslationContext.Provider>
  );
}

export function useTranslationContext() {
  const context = useContext(TranslationContext);
  if (!context) {
    throw new Error('useTranslationContext must be used within TranslationProvider');
  }
  return context;
}

// src/ml/TranslationEngine.ts
// Motor de tradução MarianMT via ONNX Runtime
// Encoder + Decoder separados, quantizados INT8

import { Platform } from 'react-native';
import {
  shouldBypass,
  splitSentences,
  loadTokenizer,
  tokenize,
  detokenize,
  MarianMTTokenizer,
} from './Tokenizer';
import { ModelConfig } from './models-config';
import { CachedPaths } from './ModelManager';

let ort: any = null;

async function getOnnxRuntime() {
  if (ort) return ort;
  try {
    ort = require('onnxruntime-react-native');
    return ort;
  } catch (e) {
    console.warn('[ML] ONNX Runtime não disponível:', e);
    return null;
  }
}

function getSessionOptions() {
  return {
    intraOpNumThreads: 2,
    interOpNumThreads: 1,
    executionProviders: [
      Platform.OS === 'ios' ? 'coreml' : 'nnapi',
      'cpu',
    ],
    enableMemPattern: true,
    enableCpuMemArena: false,
  };
}

export class TranslationEngine {
  private encoderSession: any = null;
  private decoderSession: any = null;
  private tokenizer: MarianMTTokenizer | null = null;
  private config: ModelConfig | null = null;
  private isWarmedUp = false;
  private abortController: AbortController | null = null;

  async initialize(
    paths: CachedPaths,
    config: ModelConfig
  ): Promise<void> {
    this.config = config;

    // Carregar tokenizer
    try {
      this.tokenizer = await loadTokenizer(paths.tokenizer);
      console.log('[ML] Tokenizer carregado');
    } catch (e) {
      console.warn('[ML] Erro ao carregar tokenizer:', e);
    }

    // Criar sessões ONNX
    const ort = await getOnnxRuntime();
    if (!ort) {
      throw new Error('ONNX Runtime não disponível');
    }

    try {
      this.encoderSession = await ort.InferenceSession.create(
        paths.encoder,
        getSessionOptions()
      );
      this.decoderSession = await ort.InferenceSession.create(
        paths.decoder,
        getSessionOptions()
      );
      console.log('[ML] Sessões ONNX criadas (encoder + decoder)');
    } catch (error) {
      // Fallback CPU
      console.warn('[ML] Fallback para CPU:', error);
      const cpuOptions = { intraOpNumThreads: 2, executionProviders: ['cpu'] };
      this.encoderSession = await ort.InferenceSession.create(paths.encoder, cpuOptions);
      this.decoderSession = await ort.InferenceSession.create(paths.decoder, cpuOptions);
    }

    await this.warmUp();
  }

  private async warmUp(): Promise<void> {
    if (this.isWarmedUp || !this.encoderSession || !this.tokenizer) return;

    try {
      const warmupTokens = tokenize('Olá', this.tokenizer);
      const inputIds = new BigInt64Array(warmupTokens.map(t => BigInt(t)));
      const attentionMask = new BigInt64Array(warmupTokens.map(() => BigInt(1)));

      const encoderOutput = await this.encoderSession.run({
        input_ids: inputIds,
        attention_mask: attentionMask,
      });

      const encoderHidden = encoderOutput.last_hidden_state;
      if (encoderHidden) {
        const decoderInput = new BigInt64Array([BigInt(2)]); // </s> token
        await this.decoderSession.run({
          input_ids: decoderInput,
          encoder_hidden_states: encoderHidden,
        });
      }

      this.isWarmedUp = true;
      console.log('[ML] Warm-up concluído');
    } catch (e) {
      console.warn('[ML] Warm-up falhou (não crítico):', e);
    }
  }

  async translate(text: string, from: string = 'pt', to: string = 'en'): Promise<string> {
    if (shouldBypass(text)) return text;
    if (!this.encoderSession || !this.decoderSession) {
      throw new Error('Sessões ONNX não inicializadas');
    }
    if (!this.tokenizer || !this.config) {
      throw new Error('Tokenizer não inicializado');
    }

    if (this.abortController) this.abortController.abort();
    this.abortController = new AbortController();
    const signal = this.abortController.signal;

    try {
      const chunks = splitSentences(text);
      const results: string[] = [];

      for (const chunk of chunks) {
        if (signal.aborted) throw new Error('Abortado');
        const translated = await this.translateChunk(chunk);
        results.push(translated);
      }

      return results.join(' ');
    } catch (error: any) {
      if (error.message === 'Abortado') {
        console.log('[ML] Tradução cancelada');
        return text;
      }
      throw error;
    }
  }

  private async translateChunk(text: string): Promise<string> {
    if (!this.encoderSession || !this.decoderSession || !this.tokenizer) {
      return text;
    }

    // Tokenizar texto de entrada
    const inputTokenIds = tokenize(text, this.tokenizer);

    const inputIds = new BigInt64Array(inputTokenIds.map(t => BigInt(t)));
    const attentionMask = new BigInt64Array(inputTokenIds.map(() => BigInt(1)));

    // 1. Encoder
    const encoderOutput = await this.encoderSession.run({
      input_ids: inputIds,
      attention_mask: attentionMask,
    });

    const encoderHidden = encoderOutput.last_hidden_state;
    if (!encoderHidden) {
      console.warn('[ML] Encoder não retornou hidden states');
      return text;
    }

    // 2. Decoder (greedy autoregressive)
    const outputIds: number[] = [];
    let decoderInputIds = new BigInt64Array([BigInt(2)]); // </s> token

    const maxLen = 128;
    for (let i = 0; i < maxLen; i++) {
      const decoderOutput = await this.decoderSession.run({
        input_ids: decoderInputIds,
        encoder_hidden_states: encoderHidden,
      });

      const logits = decoderOutput.logits?.data;
      if (!logits) break;

      // Pegar último token
      const vocabSize = logits.length / decoderInputIds.length;
      const lastTokenOffset = (decoderInputIds.length - 1) * vocabSize;

      let maxLogit = -Infinity;
      let maxId = 0;
      for (let j = 0; j < vocabSize; j++) {
        if (logits[lastTokenOffset + j] > maxLogit) {
          maxLogit = logits[lastTokenOffset + j];
          maxId = j;
        }
      }

      // Parar em </s> ou <pad>
      if (maxId === 2 || maxId === 0) break;

      outputIds.push(maxId);

      // Preparar próximo input
      decoderInputIds = new BigInt64Array([...decoderInputIds, BigInt(maxId)]);
    }

    return detokenize(outputIds, this.tokenizer);
  }

  async translateBatch(texts: string[], from: string = 'pt', to: string = 'en'): Promise<string[]> {
    const results: string[] = [];
    for (const text of texts) {
      results.push(await this.translate(text, from, to));
    }
    return results;
  }

  dispose(): void {
    this.encoderSession?.release();
    this.decoderSession?.release();
    this.encoderSession = null;
    this.decoderSession = null;
    this.tokenizer = null;
    this.config = null;
    this.isWarmedUp = false;
  }
}

// src/ml/batteryAware.ts
// Detector de bateria para modo econômico

import { NativeModules, NativeEventEmitter, Platform } from 'react-native';

interface BatteryState {
  level: number; // 0-1
  isLowPowerMode: boolean;
}

let batteryState: BatteryState = { level: 1, isLowPowerMode: false };
let listeners: Array<(state: BatteryState) => void> = [];

// Verifica se está em modo econômico
export function isLowPowerMode(): boolean {
  return batteryState.isLowPowerMode || batteryState.level < 0.05;
}

// Retorna debounce delay baseado no estado da bateria
export function getDebounceDelay(): number {
  return isLowPowerMode() ? 500 : 250;
}

// Observa mudanças na bateria (plataforma específica)
export function startBatteryMonitoring(callback: (state: BatteryState) => void): () => void {
  listeners.push(callback);

  // Em produção, usar expo-battery ou módulo nativo
  // Por agora, simular com Battery API se disponível
  if (Platform.OS === 'web' && typeof navigator !== 'undefined' && 'getBattery' in navigator) {
    (navigator as any).getBattery().then((battery: any) => {
      batteryState = {
        level: battery.level,
        isLowPowerMode: battery.charging === false && battery.level < 0.2,
      };
      callback(batteryState);

      battery.addEventListener('levelchange', () => {
        batteryState.level = battery.level;
        batteryState.isLowPowerMode = battery.charging === false && battery.level < 0.2;
        listeners.forEach(l => l(batteryState));
      });
    });
  }

  return () => {
    listeners = listeners.filter(l => l !== callback);
  };
}

// Estado atual da bateria
export function getBatteryState(): BatteryState {
  return batteryState;
}

