// src/services/gamification.js
// Serviço de gamificação - XP, Níveis, Conquistas - NOVAIX FITNESS

import { supabase } from '../config/supabase';
import { XP_VALUES, getLevelForXP, calculateLevel, getUnlockedAchievements, checkNewAchievements } from '../constants/gamification';

export { calculateLevel };
import { sendPushToUser } from './pushNotifications';
import { APP_CONFIG } from '../config/app';
import { calculateCustomWorkoutXP } from '../config/gamificationConfig';

export async function addXP(userId, type, amount) {
  const xpGain = amount || XP_VALUES[type] || 0;
  if (!userId || xpGain <= 0) return 0;

  try {
    const { data: profile } = await supabase
      .from('profiles')
      .select('total_xp')
      .eq('id', userId)
      .single();

    const currentXP = profile?.total_xp || 0;
    const newXP = currentXP + xpGain;

    await supabase
      .from('profiles')
      .update({ total_xp: newXP })
      .eq('id', userId);

    return newXP;
  } catch (err) {
    console.error('Erro ao adicionar XP:', err);
    return 0;
  }
}

export async function getGamificationData(userId) {
  if (!userId) return null;

  try {
    const { data: profile } = await supabase
      .from('profiles')
      .select('total_xp, total_workouts, total_minutes, max_streak')
      .eq('id', userId)
      .single();

    const { data: userWorkouts } = await supabase
      .from('user_workouts')
      .select('completed, completed_at, duration')
      .eq('user_id', userId);

    const { count: postsCount } = await supabase.from('posts').select('*', { count: 'exact', head: true }).eq('user_id', userId);
    const { count: likesCount } = await supabase.from('post_likes').select('*', { count: 'exact', head: true }).eq('user_id', userId);
    const { count: commentsCount } = await supabase.from('post_comments').select('*', { count: 'exact', head: true }).eq('user_id', userId);

    const totalXP = profile?.total_xp || 0;
    const totalWorkouts = profile?.total_workouts || userWorkouts?.filter(w => w.completed).length || 0;
    const totalMinutes = profile?.total_minutes || userWorkouts?.reduce((s, w) => s + (w.duration || 0), 0) || 0;
    const streak = calculateStreak(userWorkouts || []);
    const maxStreak = Math.max(profile?.max_streak || 0, streak);

    const level = getLevelForXP(totalXP);

    const stats = {
      totalXP,
      totalWorkouts,
      totalMinutes,
      streak,
      maxStreak,
      level: level.level,
      social_first_post_count: postsCount || 0,
      social_10_posts_count: postsCount || 0,
      social_50_likes_count: likesCount || 0,
      social_25_comments_count: commentsCount || 0,
    };

    const achievements = getUnlockedAchievements(stats);

    return {
      ...stats,
      levelData: level,
      achievements,
      recentAchievements: achievements.slice(-5),
    };
  } catch (err) {
    console.error('Erro ao buscar dados de gamificação:', err);
    return null;
  }
}

export async function recordWorkoutCompletion(userId, workoutData, logs = [], duration = 0) {
  if (!userId) return { xpGained: 0, newAchievements: [] };

  try {
    const currentData = await getGamificationData(userId);
    const prevAchievements = currentData?.achievements || [];

    const workoutXP = workoutData?.id?.length === 36
      ? XP_VALUES.WORKOUT_COMPLETED
      : calculateCustomWorkoutXP(logs, workoutData?.exercises?.length || 0, duration);

    await addXP(userId, 'WORKOUT_COMPLETED', workoutXP);

    let streakBonus = 0;
    if (currentData?.streak > 0) {
      streakBonus = XP_VALUES.STREAK_BONUS_PER_DAY * currentData.streak;
      await addXP(userId, 'STREAK_BONUS_PER_DAY', streakBonus);
    }

    const updatedData = await getGamificationData(userId);
    const newAchievements = checkNewAchievements(updatedData, prevAchievements);

    const streakMilestones = Object.keys(APP_CONFIG.notifications.streakMessages).map(Number);
    const newStreak = updatedData?.streak || 0;
    if (streakMilestones.includes(newStreak)) {
      await sendPushToUser(userId, `Streak de ${newStreak} dias!`, APP_CONFIG.notifications.streakMessages[newStreak], { type: 'streak', streak_days: newStreak });
    }

    if (newAchievements.length > 0) {
      await supabase.from('user_achievements').upsert(
        newAchievements.map(a => ({
          user_id: userId,
          achievement_id: a.id,
          unlocked_at: new Date().toISOString(),
        })),
        { onConflict: 'user_id,achievement_id' }
      );

      let achievementXP = 0;
      for (const a of newAchievements) {
        if (a.xpReward) {
          await addXP(userId, 'ACHIEVEMENT_UNLOCKED', a.xpReward);
          achievementXP += a.xpReward;
        }
      }
    }

    return {
      xpGained: workoutXP + streakBonus + (newAchievements?.reduce((sum, a) => sum + (a.xpReward || 0), 0) || 0),
      newAchievements,
      level: updatedData?.levelData,
      streak: updatedData?.streak,
    };
  } catch (err) {
    console.error('Erro ao registrar conclusão:', err);
    return { xpGained: 0, newAchievements: [] };
  }
}

export async function awardActionXP(userId, action) {
  const xpGain = XP_VALUES[action] || 0;
  if (!userId || xpGain <= 0) return 0;
  return addXP(userId, action, xpGain);
}

export async function updateMaxStreak(userId) {
  if (!userId) return;
  try {
    const { data: workouts } = await supabase.from('user_workouts').select('completed, completed_at').eq('user_id', userId);
    const streak = calculateStreak(workouts || []);
    await supabase.from('profiles').update({ max_streak: streak }).eq('id', userId);
  } catch (err) {
    console.error('Erro ao atualizar streak:', err);
  }
}

function calculateStreak(workouts) {
  if (!workouts.length) return 0;

  const dates = [...new Set(
    workouts
      .filter(w => w.completed && w.completed_at)
      .map(w => new Date(w.completed_at).toDateString())
  )].sort((a, b) => new Date(b) - new Date(a));

  if (!dates.length) return 0;

  let streak = 1;
  const today = new Date().toDateString();
  const yesterday = new Date(Date.now() - 86400000).toDateString();

  if (dates[0] !== today && dates[0] !== yesterday) return 0;

  for (let i = 1; i < dates.length; i++) {
    const diff = (new Date(dates[i - 1]) - new Date(dates[i])) / 86400000;
    if (diff === 1) streak++;
    else break;
  }

  return streak;
}

// src/services/gamificationAchievements.ts
// Conquistas do usuario - usa canonical data de constants

import { supabase } from '../config/supabase';
import { TABLES } from '../config/tables';
import { awardXP } from './gamificationLevels';
import {
  ACHIEVEMENTS as CANONICAL_ACHIEVEMENTS,
  type Achievement,
  getUnlockedAchievements,
} from '../constants/gamificationAchievements';

export type { Achievement };

const STAT_KEY_MAP: Record<string, string> = {
  streak: 'maxStreak',
  workout: 'totalWorkouts',
  time: 'totalMinutes',
  level: 'level',
  xp: 'totalXP',
};

function mapStats(stats: Record<string, number>): { [key: string]: number | undefined } {
  const mapped: { [key: string]: number | undefined } = {};
  for (const achievement of CANONICAL_ACHIEVEMENTS) {
    if (achievement.category === 'social' || achievement.category === 'weekly') {
      mapped[`${achievement.id}_count`] = stats[`${achievement.id}_count`]
        ?? stats[achievement.id]
        ?? 0;
    }
  }
  for (const [cat, key] of Object.entries(STAT_KEY_MAP)) {
    mapped[key] = stats[key] ?? stats[cat] ?? 0;
  }
  return mapped;
}

function checkAchievementCondition(achievementId: string, stats: Record<string, number>): boolean {
  const mapped = mapStats(stats);
  const achievement = CANONICAL_ACHIEVEMENTS.find(a => a.id === achievementId);
  if (!achievement) return false;
  const key = STAT_KEY_MAP[achievement.category];
  const value = key ? (mapped[key] ?? 0) : (mapped[`${achievementId}_count`] ?? 0);
  return value >= achievement.requirement;
}

export function getAchievements(): Achievement[] { return CANONICAL_ACHIEVEMENTS; }

export async function getUserAchievements(userId: string): Promise<(Achievement & { unlocked_at: string })[]> {
  const { data } = await supabase.from(TABLES.USER_ACHIEVEMENTS)
    .select('achievement_id, unlocked_at').eq('user_id', userId);
  return (data || []).map(ua => ({
    ...CANONICAL_ACHIEVEMENTS.find(a => a.id === ua.achievement_id)!,
    unlocked_at: ua.unlocked_at, unlocked: true,
  }));
}

export async function checkAchievements(userId: string): Promise<Achievement[]> {
  const { data: stats } = await supabase.rpc('get_user_stats', { p_user_id: userId });
  if (!stats) return [];
  const newAchievements: Achievement[] = [];
  for (const ach of CANONICAL_ACHIEVEMENTS) {
    const { data: existing } = await supabase.from(TABLES.USER_ACHIEVEMENTS)
      .select('id').eq('user_id', userId).eq('achievement_id', ach.id).single();
    if (existing) continue;
    if (checkAchievementCondition(ach.id, stats)) {
      await supabase.from(TABLES.USER_ACHIEVEMENTS).insert({ user_id: userId, achievement_id: ach.id });
      await awardXP(userId, 'achievement_unlocked', { achievement_id: ach.id });
      newAchievements.push(ach);
    }
  }
  return newAchievements;
}

