import { Platform } from 'react-native';
import { supabase } from '../config/supabase';
import { TABLES } from '../config/tables';

let HealthKit = null;
let GoogleFit = null;

if (Platform.OS === 'ios') {
  try { HealthKit = require('expo-health'); } catch (e) { if (__DEV__) console.warn('healthSync:', e); }
} else if (Platform.OS === 'android') {
  try { GoogleFit = require('react-native-google-fit'); } catch (e) { if (__DEV__) console.warn('healthSync:', e); }
}

export function getHealthLibs() {
  return { HealthKit, GoogleFit };
}

export async function syncWeightFromHealth(userId) {
  if (Platform.OS === 'ios' && HealthKit) {
    try {
      const end = new Date();
      const start = new Date(end.getTime() - 30 * 86400000);
      const samples = await HealthKit.getSamplesAsync(HealthKit.HealthkitQuantityTypeIdentifierBodyMass, start, end);
      for (const sample of samples) {
        await supabase.from(TABLES.WEIGHT_LOGS).upsert({
          user_id: userId, weight: sample.quantity, recorded_at: sample.startDate, source: 'apple_health',
        }, { onConflict: 'user_id,recorded_at' });
      }
      return samples.length;
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar peso Apple Health:', err);
      return 0;
    }
  }
  if (Platform.OS === 'android' && GoogleFit) {
    try {
      const opt = { startDate: new Date(Date.now() - 30 * 86400000).toISOString(), endDate: new Date().toISOString() };
      const data = await GoogleFit.getWeightSamples(opt);
      for (const sample of data) {
        await supabase.from(TABLES.WEIGHT_LOGS).upsert({
          user_id: userId, weight: sample.value, recorded_at: sample.date, source: 'google_fit',
        }, { onConflict: 'user_id,recorded_at' });
      }
      return data.length;
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar peso Google Fit:', err);
      return 0;
    }
  }
  return 0;
}

export async function syncStepsFromHealth(userId) {
  if (Platform.OS === 'ios' && HealthKit) {
    try {
      const end = new Date();
      const start = new Date(end.getTime() - 7 * 86400000);
      const samples = await HealthKit.getSamplesAsync(HealthKit.HealthkitQuantityTypeIdentifierStepCount, start, end);
      const dailySteps: Record<string, number> = {};
      for (const sample of samples) {
        const date = new Date(sample.startDate).toDateString();
        dailySteps[date] = (dailySteps[date] || 0) + (sample.quantity as number);
      }
      for (const [date, steps] of Object.entries(dailySteps)) {
        await supabase.from(TABLES.STEP_LOGS).upsert({
          user_id: userId, steps, recorded_at: new Date(date).toISOString(), source: 'apple_health',
        }, { onConflict: 'user_id,recorded_at' });
      }
      return Object.values(dailySteps).reduce((a, b) => a + b, 0);
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar passos Apple Health:', err);
      return 0;
    }
  }
  if (Platform.OS === 'android' && GoogleFit) {
    try {
      const opt = { startDate: new Date(Date.now() - 7 * 86400000).toISOString(), endDate: new Date().toISOString() };
      const data = await GoogleFit.getDailyStepCountSamples(opt);
      let totalSteps = 0;
      for (const source of data) {
        if (source.steps) {
          for (const step of source.steps) {
            totalSteps += step.value;
            await supabase.from(TABLES.STEP_LOGS).upsert({
              user_id: userId, steps: step.value, recorded_at: step.date, source: 'google_fit',
            }, { onConflict: 'user_id,recorded_at' });
          }
        }
      }
      return totalSteps;
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar passos Google Fit:', err);
      return 0;
    }
  }
  return 0;
}

export async function syncCaloriesFromHealth(userId) {
  if (Platform.OS === 'ios' && HealthKit) {
    try {
      const end = new Date();
      const start = new Date(end.getTime() - 7 * 86400000);
      const samples = await HealthKit.getSamplesAsync(HealthKit.HealthkitQuantityTypeIdentifierActiveEnergyBurned, start, end);
      const dailyCalories: Record<string, number> = {};
      for (const sample of samples) {
        const date = new Date(sample.startDate).toDateString();
        dailyCalories[date] = (dailyCalories[date] || 0) + (sample.quantity as number);
      }
      for (const [date, calories] of Object.entries(dailyCalories)) {
        await supabase.from(TABLES.CALORIE_LOGS).upsert({
          user_id: userId, calories: Math.round(calories), recorded_at: new Date(date).toISOString(), source: 'apple_health',
        }, { onConflict: 'user_id,recorded_at' });
      }
      return Object.values(dailyCalories).reduce((a, b) => a + b, 0);
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar calorias Apple Health:', err);
      return 0;
    }
  }
  if (Platform.OS === 'android' && GoogleFit) {
    try {
      const opt = { startDate: new Date(Date.now() - 7 * 86400000).toISOString(), endDate: new Date().toISOString() };
      const data = await GoogleFit.getDailyCalorieSamples(opt);
      let totalCalories = 0;
      for (const sample of data) {
        totalCalories += Math.abs(sample.calorie);
        await supabase.from(TABLES.CALORIE_LOGS).upsert({
          user_id: userId, calories: Math.round(Math.abs(sample.calorie)), recorded_at: sample.date, source: 'google_fit',
        }, { onConflict: 'user_id,recorded_at' });
      }
      return totalCalories;
    } catch (err) {
      if (__DEV__) console.warn('Erro ao sincronizar calorias Google Fit:', err);
      return 0;
    }
  }
  return 0;
}

// src/services/liveWorkouts.ts
// Serviço de lives de treino

import { supabase } from '../config/supabase';
import { TABLES } from '../config/tables';
import type { LiveWorkout, LiveParticipant, LiveMessage, LiveWorkoutState, LiveStatus } from '../types';

type RealtimePayload = { new: Record<string, unknown> };

interface LiveCallbacks {
  onMessage: (payload: RealtimePayload) => void;
  onParticipant: (payload: RealtimePayload) => void;
  onState: (payload: RealtimePayload) => void;
  onLiveUpdate: (payload: RealtimePayload) => void;
}

interface CreateLiveParams {
  title: string;
  description?: string;
  workoutType?: string;
  isPublic?: boolean;
}

export async function createLive(hostId: string, { title, description, workoutType, isPublic }: CreateLiveParams): Promise<LiveWorkout> {
  const { data, error } = await supabase
    .from(TABLES.LIVE_WORKOUTS)
    .insert({
      host_id: hostId,
      title,
      description: description || null,
      workout_type: workoutType || 'general',
      is_public: isPublic !== false,
    })
    .select()
    .single();

  if (error) throw error;

  await supabase.from(TABLES.LIVE_PARTICIPANTS).insert({
    live_id: data.id,
    user_id: hostId,
    role: 'host',
  });

  await supabase.from(TABLES.LIVE_WORKOUT_STATE).insert({
    live_id: data.id,
    timer_seconds: 0,
  });

  return data as LiveWorkout;
}

export async function startLive(liveId: string): Promise<void> {
  const { error } = await supabase
    .from(TABLES.LIVE_WORKOUTS)
    .update({ status: 'live', started_at: new Date().toISOString() })
    .eq('id', liveId);

  if (error) throw error;
}

export async function endLive(liveId: string): Promise<void> {
  const { error } = await supabase
    .from(TABLES.LIVE_WORKOUTS)
    .update({ status: 'ended', ended_at: new Date().toISOString() })
    .eq('id', liveId);

  if (error) throw error;
}

export async function joinLive(liveId: string, userId: string): Promise<LiveParticipant> {
  const { data: existing } = await supabase
    .from(TABLES.LIVE_PARTICIPANTS)
    .select('id')
    .eq('live_id', liveId)
    .eq('user_id', userId)
    .single();

  if (existing) return existing as LiveParticipant;

  const { data, error } = await supabase
    .from(TABLES.LIVE_PARTICIPANTS)
    .insert({ live_id: liveId, user_id: userId, role: 'participant' })
    .select()
    .single();

  if (error) throw error;

  await supabase.rpc('increment_column', {
    table_name: 'live_workouts',
    column_name: 'participant_count',
    row_id: liveId,
  });

  return data as LiveParticipant;
}

export async function leaveLive(liveId: string, userId: string): Promise<void> {
  await supabase
    .from(TABLES.LIVE_PARTICIPANTS)
    .update({ left_at: new Date().toISOString() })
    .eq('live_id', liveId)
    .eq('user_id', userId);

  await supabase.rpc('decrement_column', {
    table_name: 'live_workouts',
    column_name: 'participant_count',
    row_id: liveId,
  });
}

export async function getActiveLives(): Promise<LiveWorkout[]> {
  const { data } = await supabase
    .from(TABLES.LIVE_WORKOUTS)
    .select('*, profiles:host_id(name, avatar_url), live_participants(count)')
    .in('status', ['live', 'scheduled'])
    .order('created_at', { ascending: false });

  return (data || []) as LiveWorkout[];
}

export async function getLiveById(liveId: string): Promise<LiveWorkout | null> {
  const { data } = await supabase
    .from(TABLES.LIVE_WORKOUTS)
    .select('*, profiles:host_id(name, avatar_url)')
    .eq('id', liveId)
    .single();

  return data as LiveWorkout | null;
}

export async function getLiveParticipants(liveId: string): Promise<LiveParticipant[]> {
  const { data } = await supabase
    .from(TABLES.LIVE_PARTICIPANTS)
    .select('*, profiles:user_id(name, avatar_url)')
    .eq('live_id', liveId)
    .is('left_at', null)
    .order('joined_at', { ascending: true });

  return (data || []) as LiveParticipant[];
}

export async function sendMessage(liveId: string, userId: string, message: string, type: string = 'chat'): Promise<LiveMessage> {
  const { data, error } = await supabase
    .from(TABLES.LIVE_MESSAGES)
    .insert({ live_id: liveId, user_id: userId, message, type })
    .select('*, profiles:user_id(name, avatar_url)')
    .single();

  if (error) throw error;
  return data as LiveMessage;
}

export async function getLiveMessages(liveId: string, limit: number = 50): Promise<LiveMessage[]> {
  const { data } = await supabase
    .from(TABLES.LIVE_MESSAGES)
    .select('*, profiles:user_id(name, avatar_url)')
    .eq('live_id', liveId)
    .order('created_at', { ascending: true })
    .limit(limit);

  return (data || []) as LiveMessage[];
}

export async function updateWorkoutState(liveId: string, state: Partial<LiveWorkoutState>): Promise<void> {
  const { error } = await supabase
    .from(TABLES.LIVE_WORKOUT_STATE)
    .update({ ...state, updated_at: new Date().toISOString() })
    .eq('live_id', liveId);

  if (error) throw error;
}

export async function getWorkoutState(liveId: string): Promise<LiveWorkoutState | null> {
  const { data } = await supabase
    .from(TABLES.LIVE_WORKOUT_STATE)
    .select('*')
    .eq('live_id', liveId)
    .single();

  return data as LiveWorkoutState | null;
}

export function subscribeToLive(liveId: string, callbacks: LiveCallbacks): () => void {
  const channel = supabase
    .channel(`live-${liveId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: TABLES.LIVE_MESSAGES, filter: `live_id=eq.${liveId}` }, callbacks.onMessage)
    .on('postgres_changes', { event: '*', schema: 'public', table: TABLES.LIVE_PARTICIPANTS, filter: `live_id=eq.${liveId}` }, callbacks.onParticipant)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: TABLES.LIVE_WORKOUT_STATE, filter: `live_id=eq.${liveId}` }, callbacks.onState)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: TABLES.LIVE_WORKOUTS, filter: `id=eq.${liveId}` }, callbacks.onLiveUpdate)
    .subscribe();

  return () => supabase.removeChannel(channel);
}

// src/services/monetizationSubscription.ts
// Gerenciamento de assinaturas

import { supabase } from '../config/supabase';
import { TABLES } from '../config/tables';
import { createServiceGuard } from '../utils/serviceGuard';
import { trackEvent, EVENT_TYPES } from './eventTracker';
import { PLANS, type Plan, type Subscription } from './monetizationPlans';

const guard = createServiceGuard({ serviceName: 'monetizationSubscription' });

export async function getUserPlan(userId: string): Promise<Plan & { subscription?: Subscription }> {
  const { data: subscription } = await supabase
    .from(TABLES.SUBSCRIPTIONS)
    .select('*')
    .eq('user_id', userId)
    .eq('status', 'active')
    .single();

  if (!subscription) return PLANS.free;
  const plan = PLANS[subscription.plan_id];
  if (!plan) return PLANS.free;
  if (subscription.expires_at && new Date(subscription.expires_at) < new Date()) return PLANS.free;
  return { ...plan, subscription };
}

export async function checkFeatureAccess(userId: string, feature: string): Promise<boolean> {
  const plan = await getUserPlan(userId);
  const limit = plan.limits?.[feature as keyof Plan['limits']];
  if (limit === undefined || limit === Infinity) return true;
  if (limit === false || limit === 0) return false;
  return true;
}

export async function getUsageStats(userId: string): Promise<{ workoutsThisWeek: number; aiChatsToday: number; customWorkouts: number }> {
  const now = new Date();
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - now.getDay());
  weekStart.setHours(0, 0, 0, 0);
  const todayStart = new Date(now);
  todayStart.setHours(0, 0, 0, 0);

  const [{ count: workoutsThisWeek }, { count: aiChatsToday }, { count: customWorkouts }] = await Promise.all([
    supabase.from(TABLES.USER_WORKOUTS).select('id', { count: 'exact', head: true })
      .eq('user_id', userId).eq('completed', true).gte('completed_at', weekStart.toISOString()),
    supabase.from(TABLES.AI_CHAT_LOGS).select('id', { count: 'exact', head: true })
      .eq('user_id', userId).gte('created_at', todayStart.toISOString()),
    supabase.from(TABLES.CUSTOM_WORKOUTS).select('id', { count: 'exact', head: true })
      .eq('user_id', userId),
  ]);

  return {
    workoutsThisWeek: workoutsThisWeek || 0,
    aiChatsToday: aiChatsToday || 0,
    customWorkouts: customWorkouts || 0,
  };
}

export async function createSubscription(userId: string, planId: string, paymentMethod: string): Promise<Subscription> {
  const plan = PLANS[planId];
  if (!plan || plan.price === 0) throw new Error('Invalid plan');

  const expiresAt = new Date();
  expiresAt.setMonth(expiresAt.getMonth() + 1);

  const { data, error } = await supabase
    .from(TABLES.SUBSCRIPTIONS)
    .insert({
      user_id: userId, plan_id: planId, status: 'active',
      payment_method: paymentMethod, price: plan.price, expires_at: expiresAt.toISOString(),
    }).select().single();

  if (error) throw error;
  await supabase.from(TABLES.PROFILES).update({ subscription_plan: planId }).eq('id', userId);
  trackEvent(EVENT_TYPES.SUBSCRIPTION_STARTED, { plan_id: planId, price: plan.price }, userId);
  return data as Subscription;
}

export async function cancelSubscription(userId: string): Promise<void> {
  const { error } = await supabase.from(TABLES.SUBSCRIPTIONS)
    .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
    .eq('user_id', userId).eq('status', 'active');
  if (error) throw error;
  await supabase.from(TABLES.PROFILES).update({ subscription_plan: 'free' }).eq('id', userId);
  trackEvent(EVENT_TYPES.SUBSCRIPTION_CANCELLED, {}, userId);
}

export async function getSubscriptionHistory(userId: string): Promise<Subscription[]> {
  const { data } = await supabase.from(TABLES.SUBSCRIPTIONS)
    .select('*').eq('user_id', userId).order('created_at', { ascending: false });
  return (data || []) as Subscription[];
}

// src/services/offlineSync.ts
// Sincronizacao offline com fila de acoes pendentes e deteccao de conexao
// Service worker equivalente para React Native

import AsyncStorage from '@react-native-async-storage/async-storage';
import { supabase } from '../config/supabase';

const QUEUE_KEY = '@novaix:sync_queue';
const LAST_SYNC_KEY = '@novaix:last_full_sync';
const PENDING_KEY = '@novaix:pending_actions';

type PendingAction = {
  id: string;
  type: string;
  table: string;
  data: Record<string, unknown>;
  timestamp: number;
  retries: number;
  status: 'pending' | 'syncing' | 'failed';
};

type SyncResult = {
  synced: number;
  failed: number;
  pending: number;
};

let isSyncing = false;

// Adiciona acao a fila de sincronizacao
export async function queueAction(type: string, table: string, data: Record<string, unknown>): Promise<string> {
  const action: PendingAction = {
    id: `action_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    type,
    table,
    data,
    timestamp: Date.now(),
    retries: 0,
    status: 'pending',
  };

  try {
    const raw = await AsyncStorage.getItem(PENDING_KEY);
    const queue: PendingAction[] = raw ? JSON.parse(raw) : [];
    queue.push(action);
    await AsyncStorage.setItem(PENDING_KEY, JSON.stringify(queue));
    return action.id;
  } catch {
    return action.id;
  }
}

// Obtem acoes pendentes
export async function getPendingActions(): Promise<PendingAction[]> {
  try {
    const raw = await AsyncStorage.getItem(PENDING_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

// Sincroniza acoes pendentes com o servidor
export async function syncPendingActions(): Promise<SyncResult> {
  if (isSyncing) return { synced: 0, failed: 0, pending: 0 };
  isSyncing = true;

  let synced = 0;
  let failed = 0;

  try {
    const queue = await getPendingActions();
    const pending = queue.filter(a => a.status === 'pending');

    for (const action of pending) {
      try {
        action.status = 'syncing';
        await saveQueue(queue);

        const { error } = await supabase.from(action.table).upsert(action.data);

        if (error) throw error;

        action.status = 'synced';
        synced++;
      } catch (err) {
        action.retries++;
        action.status = action.retries >= 3 ? 'failed' : 'pending';
        failed++;

        if (__DEV__) console.warn(`[sync] Falha ao sincronizar ${action.id}:`, err);
      }
    }

    await saveQueue(queue);
    await AsyncStorage.setItem(LAST_SYNC_KEY, Date.now().toString());

    return { synced, failed, pending: queue.filter(a => a.status === 'pending').length };
  } catch (err) {
    if (__DEV__) console.error('[sync] Erro geral na sincronizacao:', err);
    return { synced, failed, pending: 0 };
  } finally {
    isSyncing = false;
  }
}

// Remove acoes sincronizadas da fila
export async function cleanupSyncedActions(): Promise<number> {
  try {
    const queue = await getPendingActions();
    const before = queue.length;
    const remaining = queue.filter(a => a.status !== 'synced');
    await saveQueue(remaining);
    return before - remaining.length;
  } catch {
    return 0;
  }
}

// Remove todas as acoes pendentes
export async function clearPendingActions(): Promise<void> {
  try {
    await AsyncStorage.removeItem(PENDING_KEY);
  } catch {}
}

// Obtem timestamp do ultimo sync completo
export async function getLastSyncTime(): Promise<number | null> {
  try {
    const raw = await AsyncStorage.getItem(LAST_SYNC_KEY);
    return raw ? parseInt(raw, 10) : null;
  } catch {
    return null;
  }
}

// Verifica se ha acoes pendentes
export async function hasPendingActions(): Promise<boolean> {
  const queue = await getPendingActions();
  return queue.some(a => a.status === 'pending');
}

// Conta acoes por status
export async function getQueueStats(): Promise<{ pending: number; syncing: number; failed: number; total: number }> {
  const queue = await getPendingActions();
  return {
    pending: queue.filter(a => a.status === 'pending').length,
    syncing: queue.filter(a => a.status === 'syncing').length,
    failed: queue.filter(a => a.status === 'failed').length,
    total: queue.length,
  };
}

async function saveQueue(queue: PendingAction[]): Promise<void> {
  await AsyncStorage.setItem(PENDING_KEY, JSON.stringify(queue));
}

// Retry de acoes que falharam
export async function retryFailedActions(): Promise<SyncResult> {
  try {
    const queue = await getPendingActions();
    for (const action of queue) {
      if (action.status === 'failed') {
        action.status = 'pending';
        action.retries = 0;
      }
    }
    await saveQueue(queue);
    return syncPendingActions();
  } catch {
    return { synced: 0, failed: 0, pending: 0 };
  }
}

