// src/services/security/anomalyDetection.ts
// Deteccao de comportamento anomalo do usuario - NOVAIX FITNESS

type EventEntry = {
  action: string;
  timestamp: number;
  metadata?: Record<string, unknown>;
};

const eventLog: EventEntry[] = [];
const MAX_LOG_SIZE = 200;

// Registra evento para analise
export function trackAction(action: string, metadata?: Record<string, unknown>) {
  eventLog.push({ action, timestamp: Date.now(), metadata });
  if (eventLog.length > MAX_LOG_SIZE) eventLog.shift();
}

// Detecta atividade incomum (muitas acoes em pouco tempo)
export function detectBurst(action: string, windowMs: number = 60000, maxCount: number = 20): {
  burst: boolean;
  count: number;
} {
  const now = Date.now();
  const count = eventLog.filter(
    e => e.action === action && now - e.timestamp < windowMs
  ).length;
  return { burst: count > maxCount, count };
}

// Detecta mudanca de padrao horario (conta ativa em horario incomum)
export function detectUnusualTime(userId?: string): boolean {
  const hour = new Date().getHours();
  return hour >= 1 && hour < 5;
}

// Detecta tentativas repetidas da mesma acao
export function detectRepetition(action: string, maxRepeats: number = 5, windowMs: number = 10000): boolean {
  const now = Date.now();
  const recent = eventLog.filter(
    e => e.action === action && now - e.timestamp < windowMs
  );
  return recent.length >= maxRepeats;
}

// Obtem estatisticas de atividade
export function getActivityStats(windowMs: number = 3600000): {
  totalActions: number;
  uniqueActions: number;
  topActions: Array<{ action: string; count: number }>;
  timeline: Array<{ minute: string; count: number }>;
} {
  const now = Date.now();
  const recent = eventLog.filter(e => now - e.timestamp < windowMs);

  const actionCounts = new Map<string, number>();
  const minuteCounts = new Map<string, number>();

  for (const entry of recent) {
    actionCounts.set(entry.action, (actionCounts.get(entry.action) || 0) + 1);
    const minute = new Date(entry.timestamp).toISOString().slice(0, 16);
    minuteCounts.set(minute, (minuteCounts.get(minute) || 0) + 1);
  }

  return {
    totalActions: recent.length,
    uniqueActions: actionCounts.size,
    topActions: [...actionCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([action, count]) => ({ action, count })),
    timeline: [...minuteCounts.entries()]
      .map(([minute, count]) => ({ minute, count })),
  };
}

// Limpa log antigo
export function clearEventLog() {
  eventLog.length = 0;
}

// Score de risco baseado em comportamento
export function calculateRiskScore(): {
  score: number;
  level: 'low' | 'medium' | 'high';
  reasons: string[];
} {
  let score = 0;
  const reasons: string[] = [];

  const burstResult = detectBurst('api_call', 60000, 30);
  if (burstResult.burst) {
    score += 30;
    reasons.push(`Burst de ${burstResult.count} chamadas API`);
  }

  if (detectUnusualTime()) {
    score += 10;
    reasons.push('Atividade em horario incomum');
  }

  const recentFailures = eventLog.filter(
    e => e.action === 'auth_failure' && Date.now() - e.timestamp < 900000
  ).length;
  if (recentFailures > 3) {
    score += recentFailures * 10;
    reasons.push(`${recentFailures} falhas de autenticacao recentes`);
  }

  const level = score >= 50 ? 'high' : score >= 20 ? 'medium' : 'low';
  return { score: Math.min(100, score), level, reasons };
}

// src/services/security/authProtection.ts
// Protecao de autenticacao: tentativas, lockout, validacao - NOVAIX FITNESS

import { isAllowed, recordAttempt, resetLimiter, LIMITS } from '../../utils/rateLimiter';

const failedAttempts = new Map<string, number>();
const lockouts = new Map<string, number>();

const MAX_FAILED_BEFORE_LOCKOUT = 5;
const LOCKOUT_DURATION_MS = 30 * 60 * 1000;

// Verifica se o usuario pode tentar login
export function canAttemptLogin(identifier: string): {
  allowed: boolean;
  reason?: string;
  retryAfterMs: number;
} {
  const lockoutEnd = lockouts.get(identifier);
  if (lockoutEnd && Date.now() < lockoutEnd) {
    return { allowed: false, reason: 'Conta temporariamente bloqueada', retryAfterMs: lockoutEnd - Date.now() };
  }

  const result = isAllowed(`login:${identifier}`, LIMITS.login);
  if (!result.allowed) {
    return { allowed: false, reason: 'Muitas tentativas. Aguarde.', retryAfterMs: result.retryAfterMs };
  }

  return { allowed: true, retryAfterMs: 0 };
}

// Registra tentativa de login falha
export function recordFailedLogin(identifier: string): { locked: boolean; attempts: number } {
  const attempts = (failedAttempts.get(identifier) || 0) + 1;
  failedAttempts.set(identifier, attempts);

  if (attempts >= MAX_FAILED_BEFORE_LOCKOUT) {
    lockouts.set(identifier, Date.now() + LOCKOUT_DURATION_MS);
    return { locked: true, attempts };
  }

  return { locked: false, attempts };
}

// Registra login bem-sucedido - limpa contadores
export function recordSuccessfulLogin(identifier: string) {
  failedAttempts.delete(identifier);
  lockouts.delete(identifier);
  resetLimiter(`login:${identifier}`);
}

// Verifica se registro e permitido
export function canRegister(email: string): {
  allowed: boolean;
  reason?: string;
  retryAfterMs: number;
} {
  const result = isAllowed(`register:${email}`, LIMITS.register);
  if (!result.allowed) {
    return { allowed: false, reason: 'Muitas tentativas de registro', retryAfterMs: result.retryAfterMs };
  }
  return { allowed: true, retryAfterMs: 0 };
}

// Verifica se recuperação de senha e permitida
export function canResetPassword(email: string): {
  allowed: boolean;
  reason?: string;
  retryAfterMs: number;
} {
  const result = isAllowed(`forgot:${email}`, LIMITS.forgotPassword);
  if (!result.allowed) {
    return { allowed: false, reason: 'Muitas solicitacoes', retryAfterMs: result.retryAfterMs };
  }
  return { allowed: true, retryAfterMs: 0 };
}

// Valida senha forte
export function validatePasswordStrength(password: string): {
  valid: boolean;
  score: number;
  issues: string[];
} {
  const issues: string[] = [];
  let score = 0;

  if (password.length >= 8) score++;
  else issues.push('Minimo 8 caracteres');

  if (password.length >= 12) score++;

  if (/[A-Z]/.test(password)) score++;
  else issues.push('Pelo menos 1 letra maiuscula');

  if (/[a-z]/.test(password)) score++;
  else issues.push('Pelo menos 1 letra minuscula');

  if (/[0-9]/.test(password)) score++;
  else issues.push('Pelo menos 1 numero');

  if (/[^A-Za-z0-9]/.test(password)) score++;
  else issues.push('Pelo menos 1 caractere especial');

  const commonPatterns = ['123456', 'password', 'qwerty', 'abc123', '111111', 'novaix'];
  if (commonPatterns.some(p => password.toLowerCase().includes(p))) {
    score = Math.max(0, score - 2);
    issues.push('Senha muito comum');
  }

  return { valid: score >= 4, score, issues };
}

// Valida formato de email
export function validateEmailFormat(email: string): boolean {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email) && email.length <= 254;
}

// Gera delay exponencial entre tentativas
export function getBackoffDelay(attempt: number): number {
  return Math.min(1000 * Math.pow(2, attempt), 60000);
}

// Verifica se o usuario esta bloqueado
export function isLockedOut(identifier: string): boolean {
  const lockoutEnd = lockouts.get(identifier);
  if (!lockoutEnd) return false;
  if (Date.now() >= lockoutEnd) {
    lockouts.delete(identifier);
    return false;
  }
  return true;
}

// Obtem numero de tentativas falhas
export function getFailedAttempts(identifier: string): number {
  return failedAttempts.get(identifier) || 0;
}

// src/services/security/jwtBlocklist.ts
// JWT Blocklist — revogacao de tokens em tempo real
// Baseado no conceito: JWT com TTL curto + Refresh Token + Blocklist

import { supabase } from '../../config/supabase';

const BLOCKLIST_PREFIX = 'jwt:blocklist:';

// Adiciona token a blocklist (quando usuario desloga, e bloqueado, ou roubo)
export async function revokeToken(tokenId: string, expiresAt: number): Promise<void> {
  const ttlSeconds = Math.max(0, Math.floor((expiresAt - Date.now()) / 1000));
  if (ttlSeconds <= 0) return;

  try {
    await supabase.from('token_blocklist').upsert({
      token_id: tokenId,
      revoked_at: new Date().toISOString(),
      expires_at: new Date(expiresAt).toISOString(),
    });
  } catch (err) {
    if (__DEV__) console.error('[Blocklist] Erro ao revogar token:', err);
  }
}

// Verifica se token esta na blocklist
export async function isTokenRevoked(tokenId: string): Promise<boolean> {
  try {
    const { data } = await supabase
      .from('token_blocklist')
      .select('id')
      .eq('token_id', tokenId)
      .single();

    return !!data;
  } catch {
    return false;
  }
}

// Revoga todos os tokens de um usuario (logout geral, seguranca de conta)
export async function revokeAllUserTokens(userId: string): Promise<void> {
  try {
    await supabase.from('token_blocklist').upsert({
      token_id: `user:${userId}:all`,
      revoked_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    });
  } catch (err) {
    if (__DEV__) console.error('[Blocklist] Erro ao revogar todos tokens:', err);
  }
}

// Verifica se todos os tokens de um usuario estao revogados
export async function areAllUserTokensRevoked(userId: string): Promise<boolean> {
  try {
    const { data } = await supabase
      .from('token_blocklist')
      .select('id')
      .eq('token_id', `user:${userId}:all`)
      .single();

    return !!data;
  } catch {
    return false;
  }
}

// Limpa blocklist de tokens expirados (manutencao periodica)
export async function cleanupExpiredBlocks(): Promise<number> {
  try {
    const { data, error } = await supabase
      .from('token_blocklist')
      .delete()
      .lt('expires_at', new Date().toISOString())
      .select('id');

    return data?.length || 0;
  } catch {
    return 0;
  }
}

