// src/utils/accessibility.js
// Utilitários de acessibilidade - NOVAIX FITNESS

import { Platform, AccessibilityInfo } from 'react-native';

// Minimum touch target size (44x44 points per WCAG)
export const MIN_TOUCH_TARGET = 44;

// Check if screen reader is enabled
export async function isScreenReaderEnabled() {
  try {
    return await AccessibilityInfo.isScreenReaderEnabled();
  } catch {
    return false;
  }
}

// Check if reduce motion is enabled
export async function isReduceMotionEnabled() {
  try {
    return await AccessibilityInfo.isReduceMotionEnabled();
  } catch {
    return false;
  }
}

// Announce to screen reader
export function announceForAccessibility(message: string): void {
  AccessibilityInfo.announceForAccessibility(message);
}

// Set accessibility focus
export function setAccessibilityFocus(reactTag: number): void {
  AccessibilityInfo.setAccessibilityFocus(reactTag);
}

// Generate accessibility props for interactive elements
export function getAccessibilityProps(label: string, role: string, state: Record<string, boolean> = {}) {
  return {
    accessibilityLabel: label,
    accessibilityRole: role,
    accessibilityState: state,
  };
}

// Common accessibility roles
export const ROLES = {
  BUTTON: 'button',
  LINK: 'link',
  HEADER: 'header',
  IMAGE: 'image',
  TEXT: 'text',
  SEARCH: 'search',
  MENU: 'menu',
  MENUITEM: 'menuitem',
  TAB: 'tab',
  TABLIST: 'tablist',
  TABPANEL: 'tabpanel',
  CHECKBOX: 'checkbox',
  SWITCH: 'switch',
  SLIDER: 'slider',
  PROGRESSBAR: 'progressbar',
  TIMER: 'timer',
  ALERT: 'alert',
};

// Common accessibility states
export function getState({ disabled, selected, checked, expanded, busy }: {
  disabled?: boolean;
  selected?: boolean;
  checked?: boolean;
  expanded?: boolean;
  busy?: boolean;
} = {}) {
  const state: Record<string, boolean> = {};
  if (disabled !== undefined) state.disabled = disabled;
  if (selected !== undefined) state.selected = selected;
  if (checked !== undefined) state.checked = checked;
  if (expanded !== undefined) state.expanded = expanded;
  if (busy !== undefined) state.busy = busy;
  return state;
}

// Ensure minimum touch target size
export function ensureTouchTarget(style: Record<string, number> = {}) {
  const minWidth = MIN_TOUCH_TARGET;
  const minHeight = MIN_TOUCH_TARGET;
  
  return {
    ...style,
    minWidth: Math.max(style?.minWidth || 0, minWidth),
    minHeight: Math.max(style?.minHeight || 0, minHeight),
  };
}

// Generate hint text for complex interactions
export function getHint(action: string, result?: string) {
  if (result) {
    return `${action}. ${result}`;
  }
  return action;
}

// Color contrast checker (WCAG AA requires 4.5:1 for normal text)
export function getContrastRatio(hex1: string, hex2: string): number {
  const getLuminance = (hex: string): number => {
    const rgb = hex.replace('#', '').match(/.{2}/g)!.map(x => {
      const val = parseInt(x, 16) / 255;
      return val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
  };

  const l1 = getLuminance(hex1);
  const l2 = getLuminance(hex2);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

// Check if color combination meets WCAG AA
export function meetsWCAG_AA(foreground: string, background: string): boolean {
  const ratio = getContrastRatio(foreground, background);
  return ratio >= 4.5;
}

// Check if color combination meets WCAG AAA
export function meetsWCAG_AAA(foreground: string, background: string): boolean {
  const ratio = getContrastRatio(foreground, background);
  return ratio >= 7;
}

// src/utils/animations.js
// Biblioteca de animações universais - NOVAIX FITNESS

import { useState, useEffect, useCallback } from 'react';
import { Animated, Easing } from 'react-native';

// ─── HOOKS BÁSICOS ─────────────────────────────────────────

export function useFadeInUp(delay = 0) {
  const [opacity] = useState(() => new Animated.Value(0));
  const [translateY] = useState(() => new Animated.Value(20));

  useEffect(() => {
    Animated.parallel([
      Animated.timing(opacity, { toValue: 1, duration: 400, delay, easing: Easing.out(Easing.cubic), useNativeDriver: true }),
      Animated.timing(translateY, { toValue: 0, duration: 500, delay, easing: Easing.out(Easing.cubic), useNativeDriver: true }),
    ]).start();
  }, []);

  return { opacity, translateY };
}

export function useStaggeredEntry(index: number, baseDelay = 80) {
  return useFadeInUp(index * baseDelay);
}

export function useAnimatedNumber(targetValue: number, duration = 800) {
  const [animValue] = useState(() => new Animated.Value(0));
  useEffect(() => {
    Animated.timing(animValue, { toValue: targetValue, duration, easing: Easing.out(Easing.cubic), useNativeDriver: false }).start();
  }, [targetValue]);
  return animValue;
}

export function useAnimatedProgress(percentage: number, duration = 1000) {
  const [progress] = useState(() => new Animated.Value(0));
  useEffect(() => {
    progress.setValue(0);
    Animated.timing(progress, { toValue: Math.min(percentage, 100), duration, delay: 200, easing: Easing.out(Easing.cubic), useNativeDriver: false }).start();
  }, [percentage]);
  return progress;
}

export function usePulseGlow(active = true) {
  const [pulse] = useState(() => new Animated.Value(0.4));
  useEffect(() => {
    if (!active) { pulse.setValue(0); return; }
    const anim = Animated.loop(Animated.sequence([
      Animated.timing(pulse, { toValue: 1, duration: 1200, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
      Animated.timing(pulse, { toValue: 0.4, duration: 1200, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
    ]));
    anim.start();
    return () => anim.stop();
  }, [active]);
  return pulse;
}

// ─── HOOKS NOVOS ────────────────────────────────────────────

export function useCardPress() {
  const [scaleAnim] = useState(() => new Animated.Value(1));

  const onPressIn = useCallback(() => {
    Animated.spring(scaleAnim, { toValue: 0.97, tension: 50, friction: 3, useNativeDriver: true }).start();
  }, []);

  const onPressOut = useCallback(() => {
    Animated.spring(scaleAnim, { toValue: 1, tension: 50, friction: 3, useNativeDriver: true }).start();
  }, []);

  return { scaleAnim, onPressIn, onPressOut };
}

export function useCountUp(target: number, duration = 800) {
  const [display, setDisplay] = useState(0);
  const [animValue] = useState(() => new Animated.Value(0));

  useEffect(() => {
    Animated.timing(animValue, { toValue: target, duration, easing: Easing.out(Easing.cubic), useNativeDriver: false }).start();
    const listener = animValue.addListener(({ value }) => setDisplay(Math.round(value)));
    return () => animValue.removeListener(listener);
  }, [target]);

  return display;
}

export function useShimmer(active = true) {
  const [shimmerAnim] = useState(() => new Animated.Value(0));

  useEffect(() => {
    if (!active) return;
    const anim = Animated.loop(
      Animated.timing(shimmerAnim, { toValue: 1, duration: 1500, easing: Easing.linear, useNativeDriver: true })
    );
    anim.start();
    return () => anim.stop();
  }, [active]);

  return shimmerAnim;
}

export function usePageTransition() {
  const [opacity] = useState(() => new Animated.Value(0));
  const [translateX] = useState(() => new Animated.Value(30));

  useEffect(() => {
    Animated.parallel([
      Animated.timing(opacity, { toValue: 1, duration: 300, useNativeDriver: true }),
      Animated.spring(translateX, { toValue: 0, tension: 30, friction: 8, useNativeDriver: true }),
    ]).start();
  }, []);

  return { opacity, translateX };
}

export function useConfetti(active = false) {
  const [particles] = useState(() => Array.from({ length: 20 }, () => ({
    x: new Animated.Value(0),
    y: new Animated.Value(0),
    opacity: new Animated.Value(1),
    rotation: new Animated.Value(0),
  })));

  useEffect(() => {
    if (!active) return;
    particles.forEach((p, i) => {
      const angle = (Math.PI * 2 * i) / particles.length;
      const distance = 80 + Math.random() * 40;
      Animated.parallel([
        Animated.timing(p.x, { toValue: Math.cos(angle) * distance, duration: 800, useNativeDriver: true }),
        Animated.timing(p.y, { toValue: Math.sin(angle) * distance - 50, duration: 800, useNativeDriver: true }),
        Animated.timing(p.opacity, { toValue: 0, duration: 800, useNativeDriver: true }),
        Animated.timing(p.rotation, { toValue: Math.random() * 360, duration: 800, useNativeDriver: true }),
      ]).start();
    });
  }, [active]);

  return particles;
}

export function useShake(active = false) {
  const [shakeAnim] = useState(() => new Animated.Value(0));

  useEffect(() => {
    if (!active) return;
    Animated.sequence([
      Animated.timing(shakeAnim, { toValue: 10, duration: 50, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue: -10, duration: 50, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue: 8, duration: 50, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue: -8, duration: 50, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue: 0, duration: 50, useNativeDriver: true }),
    ]).start();
  }, [active]);

  return shakeAnim;
}

// src/utils/memoize.ts
// Utilitarios de memoizacao - NOVAIX FITNESS

import { useMemo, useCallback, useState, useEffect } from 'react';

// Memoizacao profunda para objetos
export function useDeepMemo<T>(factory: () => T, deps: any[]): T {
  return useMemo(() => factory(), deps);
}

// Memoizacao para callbacks com dependencias estaveis
export function useStableCallback<T extends (...args: any[]) => any>(
  callback: T,
  deps: any[]
): T {
  return useCallback(callback, deps) as T;
}

// Memoizacao para listas filtradas
export function useFilteredList<T>(
  list: T[],
  filterFn: (item: T) => boolean,
  deps: any[]
): T[] {
  return useMemo(() => list.filter(filterFn), [list, ...deps]);
}

// Memoizacao para listas ordenadas
export function useSortedList<T>(
  list: T[],
  sortFn: (a: T, b: T) => number,
  deps: any[]
): T[] {
  return useMemo(() => [...list].sort(sortFn), [list, ...deps]);
}

// Memoizacao para agrupamento
export function useGroupedList<T>(
  list: T[],
  groupFn: (item: T) => string,
  deps: any[]
): Record<string, T[]> {
  return useMemo(() => {
    const groups: Record<string, T[]> = {};
    for (const item of list) {
      const key = groupFn(item);
      if (!groups[key]) groups[key] = [];
      groups[key].push(item);
    }
    return groups;
  }, [list, ...deps]);
}

// Comparador profundo para React.memo
export function deepCompare(a: any, b: any): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  if (typeof a !== typeof b) return false;

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    return a.every((item, i) => deepCompare(item, b[i]));
  }

  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every(key => deepCompare(a[key], b[key]));
  }

  return false;
}

// Hook para debounce de valores
export function useDebouncedValue<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(handler);
  }, [value, delay]);

  return debouncedValue;
}

// src/utils/performance.ts
// Utilitarios de performance e otimizacao - NOVAIX FITNESS

import React, { memo, useCallback, useMemo, useRef, useEffect } from 'react';
import { InteractionManager } from 'react-native';

// ─── Memoizacao Profunda ───────────────────────────────────
export function deepMemo<T extends React.ComponentType<any>>(
  Component: T,
  compareFn?: (prevProps: any, nextProps: any) => boolean
): React.MemoExoticComponent<T> {
  return memo(Component, compareFn ?? compareProps);
}

function compareProps(prevProps: any, nextProps: any): boolean {
  if (prevProps === nextProps) return true;
  if (!prevProps || !nextProps) return false;

  const keys1 = Object.keys(prevProps);
  const keys2 = Object.keys(nextProps);

  if (keys1.length !== keys2.length) return false;

  for (const key of keys1) {
    const val1 = prevProps[key];
    const val2 = nextProps[key];

    if (typeof val1 === 'function' || typeof val2 === 'function') continue;
    if (val1 === val2) continue;
    if (typeof val1 !== typeof val2) return false;
    if (typeof val1 === 'object') {
      if (JSON.stringify(val1) !== JSON.stringify(val2)) return false;
    } else {
      return false;
    }
  }

  return true;
}

// ─── Cache de Dados ────────────────────────────────────────
const dataCache = new Map<string, { data: any; timestamp: number }>();

export function getCachedData<T>(key: string, ttl: number = 5 * 60 * 1000): T | null {
  const cached = dataCache.get(key);
  if (cached && Date.now() - cached.timestamp < ttl) {
    return cached.data as T;
  }
  return null;
}

export function setCachedData(key: string, data: any): void {
  dataCache.set(key, { data, timestamp: Date.now() });
}

export function clearCache(key?: string): void {
  if (key) {
    dataCache.delete(key);
  } else {
    dataCache.clear();
  }
}

// ─── Lazy Loading ──────────────────────────────────────────
export function runAfterInteractions(fn: () => void): void {
  InteractionManager.runAfterInteractions(fn);
}

// ─── Throttle ──────────────────────────────────────────────
export function throttle<T extends (...args: any[]) => any>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let lastCall = 0;
  let timeoutId: ReturnType<typeof setTimeout>;

  return (...args: Parameters<T>) => {
    const now = Date.now();
    if (now - lastCall >= delay) {
      lastCall = now;
      fn(...args);
    } else {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        lastCall = Date.now();
        fn(...args);
      }, delay - (now - lastCall));
    }
  };
}

// ─── Debounce ──────────────────────────────────────────────
export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout>;

  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}

// ─── Batch Updates ─────────────────────────────────────────
export function batchUpdates(updates: (() => void)[]): void {
  updates.forEach(update => update());
}

// ─── Prefetch de Imagens ───────────────────────────────────
const prefetchedImages = new Set<string>();

export async function prefetchImages(urls: string[]): Promise<void> {
  try {
    const { Image } = require('expo-image');
    await Promise.allSettled(
      urls
        .filter(url => url && !prefetchedImages.has(url))
        .map(url => {
          prefetchedImages.add(url);
          return Image.prefetch(url);
        })
    );
  } catch {}
}

// ─── Preload de Telas ──────────────────────────────────────
const preloadedScreens = new Set<string>();

export function preloadScreen(name: string, importFn: () => Promise<any>): void {
  if (preloadedScreens.has(name)) return;
  preloadedScreens.add(name);
  importFn().catch(() => preloadedScreens.delete(name));
}

// ─── Hook: useStableCallback ───────────────────────────────
export function useStableCallback<T extends (...args: any[]) => any>(
  callback: T
): T {
  const callbackRef = useRef(callback);
  useEffect(() => { callbackRef.current = callback; });

  return useCallback((...args: any[]) => {
    return callbackRef.current(...args);
  }, []) as T;
}

// ─── Hook: useLatest ──────────────────────────────────────
export function useLatest<T>(value: T): { readonly current: T } {
  const ref = useRef(value);
  useEffect(() => { ref.current = value; });
  return ref;
}

// src/utils/validators.ts
// Validacao centralizada de inputs antes de chamadas async - NOVAIX FITNESS

export type ValidationRule<T> = {
  test: (value: T) => boolean;
  message: string;
};

export type ValidationResult = {
  valid: boolean;
  errors: string[];
};

export function validate<T>(value: T, rules: ValidationRule<T>[]): ValidationResult {
  const errors: string[] = [];
  for (const rule of rules) {
    if (!rule.test(value)) errors.push(rule.message);
  }
  return { valid: errors.length === 0, errors };
}

// Regras comuns reutilizaveis
export const Rules = {
  required: (label: string): ValidationRule<string | null | undefined> => ({
    test: (v) => v !== null && v !== undefined && v !== '',
    message: `${label} e obrigatorio`,
  }),
  minLength: (min: number, label: string): ValidationRule<string> => ({
    test: (v) => v.length >= min,
    message: `${label} deve ter pelo menos ${min} caracteres`,
  }),
  maxLength: (max: number, label: string): ValidationRule<string> => ({
    test: (v) => v.length <= max,
    message: `${label} deve ter no maximo ${max} caracteres`,
  }),
  email: (): ValidationRule<string> => ({
    test: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
    message: 'E-mail invalido',
  }),
  pattern: (regex: RegExp, message: string): ValidationRule<string> => ({
    test: (v) => regex.test(v),
    message,
  }),
  positive: (label: string): ValidationRule<number> => ({
    test: (v) => v > 0,
    message: `${label} deve ser positivo`,
  }),
  range: (min: number, max: number, label: string): ValidationRule<number> => ({
    test: (v) => v >= min && v <= max,
    message: `${label} deve estar entre ${min} e ${max}`,
  }),
  cpf: (): ValidationRule<string> => ({
    test: (v) => /^\d{11}$/.test(v.replace(/\D/g, '')),
    message: 'CPF invalido',
  }),
  phone: (): ValidationRule<string> => ({
    test: (v) => /^\d{10,11}$/.test(v.replace(/\D/g, '')),
    message: 'Telefone invalido',
  }),
};

// Valida multiplos campos de uma vez
export function validateFields(
  fields: Record<string, { value: any; rules: ValidationRule<any>[] }>
): ValidationResult {
  const errors: string[] = [];
  for (const [name, { value, rules }] of Object.entries(fields)) {
    const result = validate(value, rules);
    if (!result.valid) {
      errors.push(...result.errors);
    }
  }
  return { valid: errors.length === 0, errors };
}
